UPGRADE_SQL = '\nCREATE FUNCTION @SCHEMA@.mineagent_rd_v4_seed_binding(rid uuid) RETURNS void\nLANGUAGE plpgsql SET search_path=@SCHEMA@,pg_catalog AS $$\nDECLARE r research_runs%ROWTYPE;\nBEGIN\n SELECT * INTO r FROM research_runs WHERE id=rid;\n IF r.config->>\'controller_profile\' IS DISTINCT FROM \'mineagent.rdagent-orchestrator.v4\' THEN RETURN; END IF;\n IF (r.engine,r.purpose,r.config->>\'schema_version\') IS DISTINCT FROM (\'rdagent\',\'factor_research\',\'mineagent.factor-research.v2\')\n OR (SELECT count(*) FROM factor_seeded_submissions s JOIN factor_versions v ON v.id=s.parent_factor_version_id\n JOIN factor_objects o ON o.id=s.parent_code_object_id\n WHERE s.run_id=r.id AND s.owner_id=r.owner_id AND v.owner_id=r.owner_id AND o.owner_id=r.owner_id\n AND v.factor_id=s.parent_factor_id AND v.ordinal=s.parent_ordinal\n AND v.code_object_id=o.id AND v.code_sha256=s.parent_code_sha256\n AND v.definition_sha256=s.parent_definition_sha256 AND o.sha256=s.parent_code_sha256)<>1\n OR EXISTS(SELECT 1 FROM factor_research_submissions WHERE run_id=r.id)\n THEN RAISE EXCEPTION \'Controller v4 requires exact provider seeded parent binding\'; END IF;\nEND $$;\nCREATE FUNCTION @SCHEMA@.mineagent_rd_v4_seed_deferred() RETURNS trigger\nLANGUAGE plpgsql SET search_path=@SCHEMA@,pg_catalog AS $$\nDECLARE rid uuid; sid uuid; ids uuid[];\nBEGIN\n IF TG_TABLE_NAME=\'research_runs\' THEN ids:=ARRAY[NEW.id,OLD.id];\n ELSE ids:=ARRAY[NEW.run_id,OLD.run_id]; END IF;\n FOR rid IN SELECT DISTINCT value FROM unnest(ids) value WHERE value IS NOT NULL LOOP\n PERFORM mineagent_rd_v4_seed_binding(rid);\n IF EXISTS(SELECT 1 FROM research_runs WHERE id=rid AND config->>\'controller_profile\'=\'mineagent.rdagent-orchestrator.v4\') THEN\n  FOR sid IN SELECT id FROM factor_seeded_submissions WHERE run_id=rid LOOP\n   PERFORM mineagent_rd_seed_check(sid);\n  END LOOP;\n END IF;\n END LOOP;\n RETURN NULL;\nEND $$;\n\nCREATE OR REPLACE FUNCTION @SCHEMA@.mineagent_rd_controller_selection(v jsonb) RETURNS jsonb\nLANGUAGE sql IMMUTABLE SET search_path=@SCHEMA@,pg_catalog AS $$\n SELECT CASE WHEN jsonb_typeof(v) IS DISTINCT FROM \'object\' THEN NULL\n WHEN NOT (v ? \'controller_profile\') THEN \'{}\'::jsonb\n WHEN v->\'controller_profile\'=\'"mineagent.rdagent-orchestrator.v3"\'::jsonb\n THEN jsonb_build_object(\'controller_profile\',\'mineagent.rdagent-orchestrator.v3\')\n WHEN v->>\'controller_profile\'=\'mineagent.rdagent-orchestrator.v4\' THEN jsonb_build_object(\'controller_profile\',\'mineagent.rdagent-orchestrator.v4\')\n ELSE NULL END\n$$;\nCREATE OR REPLACE FUNCTION @SCHEMA@.mineagent_rd_controller_profile_matches(v jsonb, profile text) RETURNS boolean\nLANGUAGE sql IMMUTABLE SET search_path=@SCHEMA@,pg_catalog AS $$\n SELECT (jsonb_typeof(v)=\'object\' AND CASE WHEN v ? \'controller_profile\' THEN\n   v->>\'controller_profile\' IN (\'mineagent.rdagent-orchestrator.v3\',\'mineagent.rdagent-orchestrator.v4\') AND jsonb_typeof(v->\'controller_profile\')=\'string\' AND profile=v->>\'controller_profile\'\n ELSE profile IN (\'mineagent.rdagent-orchestrator.v1\',\'mineagent.rdagent-orchestrator.v2\') END) IS TRUE\n$$;\nCREATE OR REPLACE FUNCTION @SCHEMA@.mineagent_rd_provider_config(v jsonb) RETURNS boolean\nLANGUAGE plpgsql IMMUTABLE SET search_path=@SCHEMA@,pg_catalog AS $$\nBEGIN\n IF NOT (v ? \'controller_profile\') THEN RETURN mineagent_rd_provider_config_026_frozen(v); END IF;\n RETURN (mineagent_rd_controller_selection(v) IS NOT NULL\n  AND mineagent_rd_json_bytes(v,true)<=1048576\n  AND mineagent_rd_provider_config_026_frozen(v-\'controller_profile\') IS TRUE\n  AND v->>\'max_iterations\'=\'1\'\n  AND (v#>>\'{budget,wall_milliseconds}\')::numeric>=(CASE WHEN v->>\'controller_profile\'=\'mineagent.rdagent-orchestrator.v4\' THEN 360000 ELSE 300000 END)+32*(v#>>\'{model_binding,request_deadline_ms}\')::numeric) IS TRUE;\nEXCEPTION WHEN OTHERS THEN RETURN false;\nEND $$;\nCREATE OR REPLACE FUNCTION @SCHEMA@.mineagent_rd_source_config(v jsonb) RETURNS boolean\nLANGUAGE plpgsql IMMUTABLE SET search_path=@SCHEMA@,pg_catalog AS $$\nBEGIN\n IF v->>\'schema_version\'=\'mineagent.factor-research.v2\' THEN RETURN mineagent_rd_provider_config(v); END IF;\n IF v->>\'controller_profile\'=\'mineagent.rdagent-orchestrator.v4\' THEN RETURN false; END IF;\n IF NOT (v ? \'controller_profile\') THEN RETURN mineagent_rd_fixture_config_026(v); END IF;\n RETURN (mineagent_rd_controller_selection(v) IS NOT NULL\n  AND mineagent_rd_json_bytes(v,true)<=1048576\n  AND mineagent_rd_fixture_config_026(v-\'controller_profile\') IS TRUE\n  AND v->>\'max_iterations\'=\'1\'\n  AND (v#>>\'{budget,wall_milliseconds}\')::numeric>=300000) IS TRUE;\nEXCEPTION WHEN OTHERS THEN RETURN false;\nEND $$;\nCREATE OR REPLACE FUNCTION @SCHEMA@.mineagent_rd_shared_consistent() RETURNS trigger\nLANGUAGE plpgsql SET search_path=@SCHEMA@,pg_catalog AS $$\nDECLARE owner_uuid uuid; r record; spec record; b record; cl record; pa record; ab record; expected jsonb;\nBEGIN\n owner_uuid:=(CASE WHEN TG_OP=\'DELETE\' THEN OLD.owner_id ELSE NEW.owner_id END);\n IF EXISTS(SELECT 1 FROM research_model_operations op JOIN research_runs rr ON rr.id=op.run_id\n   JOIN research_operation_contexts cx ON cx.id=op.context_id\n   WHERE op.owner_id=owner_uuid AND (\n    (rr.engine=\'legacy\' AND (op.protocol<>\'mineagent.neutral-model.v1\' OR cx.context->>\'schema_version\'<>\'mineagent.neutral-fixture-context.v1\'))\n    OR (rr.engine=\'rdagent\' AND ((CASE WHEN rr.config->>\'schema_version\'=\'mineagent.factor-research.v2\' THEN op.protocol NOT IN (\'mineagent.rdagent-provider-chat.v1\',\'mineagent.rdagent-provider-embedding.v1\') ELSE op.protocol NOT IN (\'mineagent.rdagent-chat.v1\',\'mineagent.rdagent-embedding.v1\') END) OR cx.context->>\'schema_version\'<>\'mineagent.rdagent-context.v1\'\n       OR mineagent_rd_source_request(op.request,op.protocol) IS NOT TRUE\n       OR op.request_sha256<>encode(sha256(convert_to(mineagent_rd_canonical_json(op.request,false),\'UTF8\')),\'hex\')))\n    OR (rr.engine=\'openevolve\' AND (op.protocol<>\'mineagent.openevolve-chat.v1\'\n       OR mineagent_oe_request(op.request,op.protocol) IS NOT TRUE\n       OR mineagent_oe_context(cx.context) IS NOT TRUE\n       OR op.request_sha256 IS DISTINCT FROM encode(sha256(convert_to(mineagent_rd_canonical_json(op.request,false),\'UTF8\')),\'hex\')))))\n THEN RAISE EXCEPTION \'Run/context/model protocol disagreement\'; END IF;\n IF EXISTS(SELECT 1 FROM research_operation_contexts cx JOIN research_runs rr ON rr.id=cx.run_id\n   WHERE cx.owner_id=owner_uuid AND ((rr.engine=\'legacy\' AND cx.context->>\'schema_version\'<>\'mineagent.neutral-fixture-context.v1\')\n    OR (rr.engine=\'rdagent\' AND mineagent_rd_source_context(cx.context) IS NOT TRUE)\n    OR (rr.engine=\'openevolve\' AND (mineagent_oe_context(cx.context) IS NOT TRUE\n       OR cx.context->>\'owner_id\' IS DISTINCT FROM cx.owner_id::text\n       OR cx.context->>\'run_id\' IS DISTINCT FROM cx.run_id::text\n       OR cx.context_sha256 IS DISTINCT FROM encode(sha256(convert_to(mineagent_rd_canonical_json(cx.context,false),\'UTF8\')),\'hex\')))))\n THEN RAISE EXCEPTION \'Run/context version disagreement\'; END IF;\n IF EXISTS(SELECT 1 FROM factor_generation_model_operations m JOIN research_model_operations op ON op.id=m.operation_id\n   WHERE m.owner_id=owner_uuid AND (m.protocol<>op.protocol OR m.context_id<>op.context_id))\n THEN RAISE EXCEPTION \'RD request membership differs from exact protocol\'; END IF;\n IF EXISTS(SELECT 1 FROM research_budget_reservations br JOIN research_runs rr ON rr.id=br.run_id\n   WHERE br.owner_id=owner_uuid AND br.purpose=\'engine_mutation\' AND\n    (br.amounts IS DISTINCT FROM \'{"calls":0,"tokens":0,"cost_microunits":0,"wall_milliseconds":0,"storage_bytes":0,"mutation_slots":1,"evaluator_executions":0,"process_slots":0}\'::jsonb\n     OR NOT ((rr.engine=\'rdagent\' AND EXISTS(\n       SELECT 1 FROM factor_generation_starts st WHERE st.mutation_reservation_id=br.id\n       AND (st.owner_id,st.run_id,st.attempt_id,st.generation)=(br.owner_id,br.run_id,br.attempt_id,br.generation)))\n       OR (rr.engine=\'openevolve\' AND EXISTS(\n       SELECT 1 FROM search_iteration_intents st WHERE st.mutation_reservation_id=br.id\n       AND (st.owner_id,st.run_id,st.attempt_id,st.generation)=(br.owner_id,br.run_id,br.attempt_id,br.generation))))))\n THEN RAISE EXCEPTION \'RD mutation slot requires exact start consumer\'; END IF;\n IF EXISTS(SELECT 1 FROM research_object_publications p JOIN research_runs rr ON rr.id=p.run_id\n   WHERE p.owner_id=owner_uuid AND p.object_kind=\'factor_response_assembly\' AND rr.engine<>\'rdagent\')\n THEN RAISE EXCEPTION \'RD assembly publication cannot use legacy run\'; END IF;\n FOR r IN SELECT * FROM research_runs WHERE owner_id=owner_uuid AND engine=\'rdagent\' LOOP\n  SELECT * INTO spec FROM factor_research_specs WHERE run_id=r.id;\n  IF NOT FOUND OR spec.owner_id<>r.owner_id OR spec.config<>r.config\n   OR spec.config_sha256<>r.request_sha256 OR spec.input_sha256<>encode(sha256(convert_to(mineagent_rd_canonical_json(r.config->\'input\',true),\'UTF8\')),\'hex\')\n  THEN RAISE EXCEPTION \'RD immutable spec/run agreement\'; END IF;\n  SELECT * INTO b FROM research_budget_controls WHERE run_id=r.id;\n  IF NOT FOUND OR b.owner_id<>r.owner_id OR b.limits<>r.config->\'budget\'\n  THEN RAISE EXCEPTION \'RD immutable global budget differs\'; END IF;\n  IF EXISTS(SELECT 1 FROM research_operation_contexts cx WHERE cx.run_id=r.id AND\n    (cx.context->>\'spec_sha256\'<>spec.config_sha256 OR cx.context->>\'input_sha256\'<>spec.input_sha256\n     OR (cx.context->>\'logical_step\')::integer >= (r.config->>\'max_iterations\')::integer\n     OR cx.context_sha256<>encode(sha256(convert_to(mineagent_rd_canonical_json(cx.context,false),\'UTF8\')),\'hex\')))\n  THEN RAISE EXCEPTION \'RD context differs from frozen specification\'; END IF;\n END LOOP;\n FOR cl IN SELECT * FROM factor_controller_launches WHERE owner_id=owner_uuid LOOP\n  SELECT * INTO ab FROM factor_research_attempt_bindings WHERE id=cl.attempt_binding_id;\n  SELECT * INTO spec FROM factor_research_specs WHERE id=ab.spec_id;\n  SELECT * INTO pa FROM research_process_admissions WHERE id=cl.admission_id;\n  expected:=jsonb_build_object(\'schema_version\',\'mineagent.rdagent-operational-bootstrap.v1\',\n   \'owner_id\',cl.owner_id,\'run_id\',cl.run_id,\'attempt_id\',cl.attempt_id,\'generation\',cl.generation,\n   \'spec_id\',spec.id,\'attempt_binding_id\',ab.id,\'config\',spec.config,\'config_sha256\',spec.config_sha256,\n   \'input_sha256\',spec.input_sha256,\'continuation\',\'fresh_only\',\'input_layout\',\'single_bootstrap_json_no_other_mounts\');\n\n  IF spec.config->>\'schema_version\'=\'mineagent.factor-research.v2\' THEN\n   expected:=expected || jsonb_build_object(\'schema_version\',\'mineagent.rdagent-provider-operational-bootstrap.v1\');\n   IF (pa.profile IS NULL OR pa.profile NOT IN (\'mineagent.rdagent-orchestrator.v2\',\'mineagent.rdagent-orchestrator.v3\',\'mineagent.rdagent-orchestrator.v4\'))\n   THEN RAISE EXCEPTION \'Configured provider controller requires protected exact profile\'; END IF;\n  END IF;\n  IF EXISTS(SELECT 1 FROM factor_seeded_submissions WHERE run_id=cl.run_id) THEN\n   SELECT expected || jsonb_build_object(\n    \'schema_version\',(CASE WHEN spec.config->>\'schema_version\'=\'mineagent.factor-research.v2\' THEN \'mineagent.rdagent-provider-seeded-bootstrap.v1\' ELSE \'mineagent.rdagent-seeded-operational-bootstrap.v1\' END),\n    \'continuation\',\'seed_parent_first_generation\',\'seeded_submission_id\',s.id,\n    \'seed\',jsonb_build_object(\'reference\',mineagent_rd_seed_reference(s.id),\n      \'definition\',v.definition,\'source\',v.code)) INTO expected\n   FROM factor_seeded_submissions s JOIN factor_versions v ON v.id=s.parent_factor_version_id\n   WHERE s.run_id=cl.run_id AND s.owner_id=cl.owner_id;\n   IF (pa.profile IS NULL OR pa.profile NOT IN (\'mineagent.rdagent-orchestrator.v2\',\'mineagent.rdagent-orchestrator.v3\',\'mineagent.rdagent-orchestrator.v4\'))\n   THEN RAISE EXCEPTION \'Seeded controller requires protected exact profile\'; END IF;\n  END IF;\n  IF ab.resumed_checkpoint_id IS NOT NULL OR cl.bootstrap IS DISTINCT FROM expected\n   OR cl.bootstrap_sha256<>encode(sha256(convert_to(mineagent_rd_canonical_json(expected,true),\'UTF8\')),\'hex\')\n   OR (pa.schema_version,pa.ipc_policy,pa.role,pa.logical_operation_id,pa.input_sha256,pa.image_id)\n     IS DISTINCT FROM (\'mineagent.process-admission.v2\'::varchar,\'host_ticket\'::varchar,\'rd_orchestrator\'::varchar,ab.id,cl.bootstrap_sha256,spec.config->\'runtime\'->>\'orchestrator_image\')\n   OR pa.profile NOT IN (\'mineagent.rdagent-orchestrator.v1\',\'mineagent.rdagent-orchestrator.v2\',\'mineagent.rdagent-orchestrator.v3\',\'mineagent.rdagent-orchestrator.v4\')\n  THEN RAISE EXCEPTION \'RD controller persistence binding differs\'; END IF;\n END LOOP;\n\n IF EXISTS(SELECT 1 FROM research_object_publications p JOIN research_runs rr ON rr.id=p.run_id\n   WHERE p.owner_id=owner_uuid AND p.object_kind IN (\'search_checkpoint_chunk\',\'search_checkpoint_file\',\'search_checkpoint_inventory\',\'search_evaluation_input\',\'search_source\',\'search_rendered_prompt\',\'search_proposal_source\',\'search_checkpoint_closure\',\'search_worker_identity\',\'search_population\',\'search_context\',\'search_controller_event\',\'search_worker_outcome\',\'search_native_observation\',\'search_native_failure\',\'search_objective\') AND rr.engine<>\'openevolve\')\n THEN RAISE EXCEPTION \'OE object publication requires exact search run\'; END IF;\n FOR r IN SELECT * FROM research_runs WHERE owner_id=owner_uuid AND engine=\'openevolve\' LOOP\n  SELECT * INTO spec FROM strategy_search_specs WHERE run_id=r.id;\n  IF NOT FOUND OR spec.owner_id IS DISTINCT FROM r.owner_id OR spec.spec IS DISTINCT FROM r.config\n   OR spec.spec_sha256 IS DISTINCT FROM r.request_sha256\n   OR spec.spec_sha256 IS DISTINCT FROM encode(sha256(convert_to(mineagent_rd_canonical_json(spec.spec,false),\'UTF8\')),\'hex\')\n   OR (spec.original_strategy_id::text,spec.original_source_sha256,spec.prepared_strategy_id::text,spec.prepared_source_sha256,\n       spec.dataset_id::text,spec.dataset_sha256)\n   IS DISTINCT FROM (r.config#>>\'{preparation,original,strategy_version_id}\',r.config#>>\'{preparation,original,source_sha256}\',\n       r.config#>>\'{preparation,prepared,strategy_version_id}\',r.config#>>\'{preparation,prepared,source_sha256}\',\n       r.config#>>\'{execution,dataset_version_id}\',r.config#>>\'{execution,dataset_sha256}\')\n   OR spec.objective_sha256 IS DISTINCT FROM encode(sha256(convert_to(mineagent_rd_canonical_json(r.config->\'objective\',false),\'UTF8\')),\'hex\')\n   OR spec.execution_sha256 IS DISTINCT FROM encode(sha256(convert_to(mineagent_rd_canonical_json(r.config->\'execution\',false),\'UTF8\')),\'hex\')\n  THEN RAISE EXCEPTION \'OE immutable spec/run agreement\'; END IF;\n  SELECT * INTO b FROM research_budget_controls WHERE run_id=r.id;\n  IF NOT FOUND OR b.owner_id IS DISTINCT FROM r.owner_id OR b.limits IS DISTINCT FROM r.config->\'budget\'\n  THEN RAISE EXCEPTION \'OE immutable global budget differs\'; END IF;\n END LOOP;\n\n RETURN NULL;\nEND $$;\nCREATE OR REPLACE FUNCTION @SCHEMA@.mineagent_rd_controller_receipt_order() RETURNS trigger\nLANGUAGE plpgsql SET search_path=@SCHEMA@,pg_catalog AS $$\nDECLARE a record; protected boolean;\nBEGIN\n SELECT * INTO STRICT a FROM research_process_admissions WHERE id=NEW.admission_id;\n protected:=((a.profile IN (\'mineagent.rdagent-orchestrator.v2\',\'mineagent.rdagent-orchestrator.v3\',\'mineagent.rdagent-orchestrator.v4\') AND a.role=\'rd_orchestrator\') OR\n   (a.profile=\'mineagent.openevolve-orchestrator.v1\' AND a.role=\'openevolve_orchestrator\'\n    AND a.schema_version=\'mineagent.process-admission.v2\' AND a.ipc_policy=\'host_ticket\'\n    AND a.ticket_sha256 ~ \'^[a-f0-9]{64}$\')) IS TRUE;\n IF NEW.kind=\'controller_child\' AND NOT protected\n THEN RAISE EXCEPTION \'Child receipt requires exact protected controller\'; END IF;\n IF NOT protected THEN RETURN NEW; END IF;\n IF NEW.kind NOT IN (\'launch_intent\',\'launch_identity\',\'controller_child\',\'stop\')\n THEN RAISE EXCEPTION \'Protected controller cannot publish extraction\'; END IF;\n IF EXISTS(SELECT 1 FROM research_process_receipts WHERE admission_id=a.id AND kind=\'stop\')\n THEN RAISE EXCEPTION \'Stopped controller receipt chain is closed\'; END IF;\n IF NEW.kind<>\'launch_intent\' AND NOT EXISTS(SELECT 1 FROM research_process_receipts WHERE admission_id=a.id AND kind=\'launch_intent\')\n THEN RAISE EXCEPTION \'Controller intent must precede physical identity\'; END IF;\n IF NEW.kind IN (\'controller_child\',\'stop\') AND NOT EXISTS(SELECT 1 FROM research_process_receipts WHERE admission_id=a.id AND kind=\'launch_identity\')\n THEN RAISE EXCEPTION \'Protected leader identity must precede child or stop\'; END IF;\n RETURN NEW;\nEND $$;\nCREATE OR REPLACE FUNCTION @SCHEMA@.mineagent_rd_controller_consistent() RETURNS trigger\nLANGUAGE plpgsql SET search_path=@SCHEMA@,pg_catalog AS $$\nDECLARE owner_uuid uuid; a record; rr record; br record; bs record; ps record;\n sp record; ab record; cl record; p record; intent jsonb; ident jsonb; child jsonb; stopped jsonb;\n decl jsonb; launch jsonb; expected_bootstrap jsonb; report jsonb; n integer;\n intent_hash text; identity_hash text; child_hash text; launch_hash text;\nBEGIN\n owner_uuid:=(CASE WHEN TG_OP=\'DELETE\' THEN OLD.owner_id ELSE NEW.owner_id END);\n IF EXISTS(SELECT 1 FROM research_process_receipts child_receipt JOIN research_process_admissions child_admission ON child_admission.id=child_receipt.admission_id\n WHERE child_receipt.owner_id=owner_uuid AND child_receipt.kind=\'controller_child\' AND\n  NOT ((child_admission.profile IN (\'mineagent.rdagent-orchestrator.v2\',\'mineagent.rdagent-orchestrator.v3\',\'mineagent.rdagent-orchestrator.v4\') AND child_admission.role=\'rd_orchestrator\')\n       OR (child_admission.profile=\'mineagent.openevolve-orchestrator.v1\' AND child_admission.role=\'openevolve_orchestrator\'\n           AND child_admission.schema_version=\'mineagent.process-admission.v2\' AND child_admission.ipc_policy=\'host_ticket\'\n           AND child_admission.ticket_sha256 ~ \'^[a-f0-9]{64}$\')))\n THEN RAISE EXCEPTION \'RD child cannot extend historical process grammar\'; END IF;\n FOR a IN SELECT * FROM research_process_admissions WHERE owner_id=owner_uuid AND profile IN (\'mineagent.rdagent-orchestrator.v2\',\'mineagent.rdagent-orchestrator.v3\',\'mineagent.rdagent-orchestrator.v4\') LOOP\n  IF (a.schema_version,a.role,a.ipc_policy) IS DISTINCT FROM\n    (\'mineagent.process-admission.v2\'::varchar,\'rd_orchestrator\'::varchar,\'host_ticket\'::varchar)\n    OR a.ticket_sha256 IS NULL OR a.ticket_sha256 !~ \'^[a-f0-9]{64}$\'\n  THEN RAISE EXCEPTION \'Exact RD controller declaration required\'; END IF;\n  SELECT * INTO rr FROM research_runs WHERE id=a.run_id AND owner_id=a.owner_id;\n  IF NOT FOUND OR rr.engine<>\'rdagent\' OR rr.purpose<>\'factor_research\'\n  THEN RAISE EXCEPTION \'RD controller requires genuine RD run\'; END IF;\n  SELECT * INTO sp FROM factor_research_specs WHERE run_id=a.run_id AND owner_id=a.owner_id;\n  IF NOT FOUND OR sp.config<>rr.config OR sp.config_sha256<>rr.request_sha256\n  THEN RAISE EXCEPTION \'Controller immutable spec missing\'; END IF;\n  SELECT * INTO ab FROM factor_research_attempt_bindings WHERE id=a.logical_operation_id\n   AND (owner_id,run_id,attempt_id,generation)=(a.owner_id,a.run_id,a.attempt_id,a.generation);\n  IF NOT FOUND OR ab.spec_id<>sp.id OR ab.resumed_checkpoint_id IS NOT NULL\n  THEN RAISE EXCEPTION \'Controller attempt binding differs\'; END IF;\n  SELECT * INTO cl FROM factor_controller_launches WHERE admission_id=a.id\n   AND (owner_id,run_id,attempt_id,generation)=(a.owner_id,a.run_id,a.attempt_id,a.generation);\n  IF NOT FOUND OR cl.attempt_binding_id<>ab.id THEN RAISE EXCEPTION \'Controller launch domain binding missing\'; END IF;\n  expected_bootstrap:=jsonb_build_object(\'schema_version\',\'mineagent.rdagent-operational-bootstrap.v1\',\n   \'owner_id\',a.owner_id,\'run_id\',a.run_id,\'attempt_id\',a.attempt_id,\'generation\',a.generation,\n   \'spec_id\',sp.id,\'attempt_binding_id\',ab.id,\'config\',sp.config,\'config_sha256\',sp.config_sha256,\n   \'input_sha256\',sp.input_sha256,\'continuation\',\'fresh_only\',\'input_layout\',\'single_bootstrap_json_no_other_mounts\');\n\n  IF sp.config->>\'schema_version\'=\'mineagent.factor-research.v2\' THEN\n   expected_bootstrap:=expected_bootstrap || jsonb_build_object(\'schema_version\',\'mineagent.rdagent-provider-operational-bootstrap.v1\');\n   IF (a.profile IS NULL OR a.profile NOT IN (\'mineagent.rdagent-orchestrator.v2\',\'mineagent.rdagent-orchestrator.v3\',\'mineagent.rdagent-orchestrator.v4\'))\n   THEN RAISE EXCEPTION \'Configured provider controller requires protected exact profile\'; END IF;\n  END IF;\n  IF EXISTS(SELECT 1 FROM factor_seeded_submissions WHERE run_id=cl.run_id) THEN\n   SELECT expected_bootstrap || jsonb_build_object(\n    \'schema_version\',(CASE WHEN sp.config->>\'schema_version\'=\'mineagent.factor-research.v2\' THEN \'mineagent.rdagent-provider-seeded-bootstrap.v1\' ELSE \'mineagent.rdagent-seeded-operational-bootstrap.v1\' END),\n    \'continuation\',\'seed_parent_first_generation\',\'seeded_submission_id\',s.id,\n    \'seed\',jsonb_build_object(\'reference\',mineagent_rd_seed_reference(s.id),\n      \'definition\',v.definition,\'source\',v.code)) INTO expected_bootstrap\n   FROM factor_seeded_submissions s JOIN factor_versions v ON v.id=s.parent_factor_version_id\n   WHERE s.run_id=cl.run_id AND s.owner_id=cl.owner_id;\n   IF (a.profile IS NULL OR a.profile NOT IN (\'mineagent.rdagent-orchestrator.v2\',\'mineagent.rdagent-orchestrator.v3\',\'mineagent.rdagent-orchestrator.v4\'))\n   THEN RAISE EXCEPTION \'Seeded controller requires protected exact profile\'; END IF;\n  END IF;\n  IF cl.bootstrap<>expected_bootstrap OR cl.bootstrap_sha256<>a.input_sha256\n   OR a.input_sha256<>encode(sha256(convert_to(@SCHEMA@.mineagent_rd_canonical_json(expected_bootstrap,true),\'UTF8\')),\'hex\')\n   OR a.image_id<>sp.config->\'runtime\'->>\'orchestrator_image\'\n  THEN RAISE EXCEPTION \'Controller bootstrap/image commitment differs\'; END IF;\n  SELECT * INTO br FROM research_budget_reservations WHERE id=a.reservation_id;\n  IF NOT FOUND OR (br.owner_id,br.run_id,br.attempt_id,br.generation) IS DISTINCT FROM\n    (a.owner_id,a.run_id,a.attempt_id,a.generation) OR br.purpose<>\'process_unit\'\n    OR (br.amounts->>\'process_slots\')::numeric<>1 OR (br.amounts->>\'wall_milliseconds\')::numeric < (CASE WHEN a.profile=\'mineagent.rdagent-orchestrator.v4\' THEN 180000 WHEN a.profile=\'mineagent.rdagent-orchestrator.v3\' THEN 120000 ELSE 60000 END)\n    OR (br.amounts->>\'storage_bytes\')::numeric<67174400\n    OR br.amounts->>\'calls\'<>\'0\' OR br.amounts->>\'tokens\'<>\'0\'\n    OR br.amounts->>\'mutation_slots\'<>\'0\' OR br.amounts->>\'evaluator_executions\'<>\'0\'\n  THEN RAISE EXCEPTION \'Controller physical reservation floor/scope differs\'; END IF;\n  SELECT * INTO ps FROM research_process_states WHERE admission_id=a.id;\n  IF NOT FOUND OR (ps.owner_id,ps.run_id,ps.attempt_id,ps.generation) IS DISTINCT FROM\n    (a.owner_id,a.run_id,a.attempt_id,a.generation) OR ps.status NOT IN (\'launch_intended\',\'running\',\'uncertain\',\'stopped\')\n  THEN RAISE EXCEPTION \'Controller projection differs\'; END IF;\n  intent:=NULL;ident:=NULL;child:=NULL;stopped:=NULL;\n  FOR p IN SELECT * FROM research_process_receipts WHERE admission_id=a.id LOOP\n   IF (p.owner_id,p.run_id,p.attempt_id,p.generation) IS DISTINCT FROM\n      (a.owner_id,a.run_id,a.attempt_id,a.generation)\n    OR @SCHEMA@.mineagent_rd_controller_payload(p.kind,p.payload) IS NOT TRUE\n    OR p.payload_sha256<>encode(sha256(convert_to(@SCHEMA@.mineagent_rd_canonical_json(p.payload,true),\'UTF8\')),\'hex\')\n   THEN RAISE EXCEPTION \'Exact controller receipt grammar/hash required\'; END IF;\n   CASE p.kind WHEN \'launch_intent\' THEN intent:=p.payload;\n    WHEN \'launch_identity\' THEN ident:=p.payload;\n    WHEN \'controller_child\' THEN child:=p.payload;\n    WHEN \'stop\' THEN stopped:=p.payload;\n    ELSE RAISE EXCEPTION \'Unexpected controller receipt\'; END CASE;\n  END LOOP;\n  IF intent IS NULL THEN RAISE EXCEPTION \'Controller launch intent required\'; END IF;\n  decl:=jsonb_build_object(\'schema_version\',a.schema_version,\'id\',a.id,\'owner_id\',a.owner_id,\n   \'run_id\',a.run_id,\'attempt_id\',a.attempt_id,\'generation\',a.generation,\'role\',a.role,\n   \'logical_operation_id\',a.logical_operation_id,\'launch_ordinal\',a.launch_ordinal,\'profile\',a.profile,\n   \'input_sha256\',a.input_sha256,\'reservation_id\',a.reservation_id,\'image_id\',a.image_id,\n   \'ipc\',jsonb_build_object(\'ipc_policy\',\'host_ticket\',\'ticket_sha256\',a.ticket_sha256));\n  IF intent->\'admission\'<>decl OR intent->>\'bootstrap_sha256\'<>a.input_sha256\n   OR (intent->>\'bootstrap_size_bytes\')::integer<>octet_length(convert_to(@SCHEMA@.mineagent_rd_canonical_json(expected_bootstrap,true),\'UTF8\'))\n   OR (intent->>\'not_after\')::timestamptz <= (intent->>\'issued_at\')::timestamptz\n   OR (intent->>\'not_after\')::timestamptz-(intent->>\'issued_at\')::timestamptz> (CASE WHEN a.profile=\'mineagent.rdagent-orchestrator.v4\' THEN interval \'180 seconds\' WHEN a.profile=\'mineagent.rdagent-orchestrator.v3\' THEN interval \'120 seconds\' ELSE interval \'60 seconds\' END)\n  THEN RAISE EXCEPTION \'Controller immutable intent differs\'; END IF;\n  IF ps.status IN (\'running\',\'stopped\') AND ident IS NULL THEN RAISE EXCEPTION \'Controller leader required\'; END IF;\n  IF (stopped IS NOT NULL) IS DISTINCT FROM (ps.status=\'stopped\') THEN RAISE EXCEPTION \'Controller stopped projection differs\'; END IF;\n  IF ident IS NULL AND (child IS NOT NULL OR stopped IS NOT NULL) THEN RAISE EXCEPTION \'Controller leader predecessor missing\'; END IF;\n  IF ident IS NOT NULL THEN\n   launch:=jsonb_build_object(\'schema_version\',\'mineagent.rd-controller-launch.v1\',\'intent\',intent,\n    \'runtime_name\',\'mineagent-rd-controller-\'||a.id::text,\'root_device\',ident->\'root_device\',\'root_inode\',ident->\'root_inode\');\n   launch_hash:=encode(sha256(convert_to(@SCHEMA@.mineagent_rd_canonical_json(launch,true),\'UTF8\')),\'hex\');\n   identity_hash:=encode(sha256(convert_to(@SCHEMA@.mineagent_rd_canonical_json(ident,true),\'UTF8\')),\'hex\');\n   IF ident->>\'launch_sha256\'<>launch_hash OR ident->>\'image_id\'<>a.image_id\n    OR ident->>\'admission_sha256\'<>encode(sha256(convert_to(@SCHEMA@.mineagent_rd_canonical_json(decl,true),\'UTF8\')),\'hex\')\n    OR @SCHEMA@.mineagent_rd_controller_kernel(ident->\'leader\',0) IS NOT TRUE\n   THEN RAISE EXCEPTION \'Protected leader physical identity differs\'; END IF;\n  END IF;\n  child_hash:=NULL;\n  IF child IS NOT NULL THEN\n   n:=jsonb_array_length(child->\'namespace_pids\');\n   IF child->>\'identity_sha256\'<>identity_hash OR child->>\'admission_sha256\'<>ident->>\'admission_sha256\'\n    OR @SCHEMA@.mineagent_rd_controller_kernel(child->\'controller\',65533) IS NOT TRUE\n    OR child->\'controller\'->\'ppid\'<>ident->\'leader\'->\'host_pid\'\n    OR child->\'controller\'->\'host_pid\'=ident->\'leader\'->\'host_pid\'\n    OR child->\'controller\'->\'pid_namespace\'<>ident->\'leader\'->\'pid_namespace\'\n    OR child->\'controller\'->\'cgroup\'<>ident->\'leader\'->\'cgroup\'\n    OR child->\'peer_pid\'<>child->\'controller\'->\'host_pid\'\n    OR child->\'namespace_pids\'->0<>child->\'controller\'->\'host_pid\'\n    OR child->\'namespace_pids\'->(n-1)<>child->\'namespace_pid\'\n    OR EXISTS(SELECT 1 FROM jsonb_array_elements(child->\'namespace_pids\') x WHERE (x.value::text)::numeric<=0)\n   THEN RAISE EXCEPTION \'Exact trusted child/peer/NSpid identity differs\'; END IF;\n   report:=jsonb_build_object(\'schema\',\'mineagent.rdagent-controller-report.v1\',\'event\',\'started\',\n    \'child_namespace_pid\',child->\'namespace_pid\',\'child_start_ticks\',child->\'controller\'->\'start_ticks\');\n   IF child->>\'started_report_sha256\'<>encode(sha256(convert_to(@SCHEMA@.mineagent_rd_canonical_json(report,true)||E\'\\n\',\'UTF8\')),\'hex\')\n   THEN RAISE EXCEPTION \'Trusted startup frame commitment differs\'; END IF;\n   child_hash:=encode(sha256(convert_to(@SCHEMA@.mineagent_rd_canonical_json(child,true),\'UTF8\')),\'hex\');\n  END IF;\n  IF stopped IS NOT NULL AND (stopped->>\'launch_sha256\'<>launch_hash\n    OR stopped->>\'identity_sha256\'<>identity_hash OR stopped->>\'container_id\'<>ident->>\'container_id\'\n    OR (stopped->>\'child_sha256\') IS DISTINCT FROM child_hash\n    OR (stopped->\'child_kernel_identity_absent\') IS DISTINCT FROM (CASE WHEN child IS NULL THEN \'null\'::jsonb ELSE \'true\'::jsonb END))\n  THEN RAISE EXCEPTION \'Controller positive stop metadata differs\'; END IF;\n  SELECT * INTO bs FROM research_budget_settlements WHERE reservation_id=br.id;\n  IF br.state=\'settled\' THEN\n   IF NOT FOUND OR stopped IS NULL OR bs.outcome<>\'conservative_unknown\'\n    OR bs.charge IS DISTINCT FROM br.amounts\n    OR (bs.owner_id,bs.run_id,bs.attempt_id,bs.generation) IS DISTINCT FROM\n      (a.owner_id,a.run_id,a.attempt_id,a.generation)\n   THEN RAISE EXCEPTION \'Controller settlement requires stopped full conservative charge\'; END IF;\n  ELSIF FOUND OR br.state NOT IN (\'reserved\',\'uncertain\') THEN RAISE EXCEPTION \'Controller unresolved budget must remain held\'; END IF;\n END LOOP;\n RETURN NULL;\nEND $$;\nCREATE OR REPLACE FUNCTION mineagent_rd_operational_actor() RETURNS trigger LANGUAGE plpgsql SET search_path=@SCHEMA@,pg_catalog AS $$\nDECLARE admission_uuid uuid;\nBEGIN\n SELECT cl.admission_id INTO admission_uuid FROM factor_controller_launches cl\n JOIN research_process_admissions p ON p.id=cl.admission_id\n JOIN research_process_states s ON s.admission_id=p.id\n WHERE cl.id=NEW.controller_launch_id\n AND (cl.owner_id,cl.run_id,cl.attempt_id,cl.generation)=(NEW.owner_id,NEW.run_id,NEW.attempt_id,NEW.generation)\n AND p.profile IN (\'mineagent.rdagent-orchestrator.v2\',\'mineagent.rdagent-orchestrator.v3\',\'mineagent.rdagent-orchestrator.v4\') AND s.status=\'running\'\n AND EXISTS(SELECT 1 FROM research_process_receipts r WHERE r.admission_id=p.id AND r.kind=\'controller_child\');\n IF admission_uuid IS NULL THEN RAISE EXCEPTION \'Current protected controller required\'; END IF;\n RETURN NEW;\nEND $$;\nCREATE OR REPLACE FUNCTION mineagent_rd_operational_boundary_consistent() RETURNS trigger LANGUAGE plpgsql SET search_path=@SCHEMA@,pg_catalog AS $$\nDECLARE owner_uuid uuid; o record; st record; src record; cl record; expected jsonb; c record; co record; members jsonb; outcomes jsonb; count_members integer;\nBEGIN\n owner_uuid:=CASE WHEN TG_OP=\'DELETE\' THEN OLD.owner_id ELSE NEW.owner_id END;\n IF EXISTS(SELECT 1 FROM factor_generation_sources source\n JOIN factor_source_read_witnesses w ON w.source_id=source.id\n JOIN factor_controller_launches launch ON launch.id=w.controller_launch_id\n JOIN research_process_admissions p ON p.id=launch.admission_id\n WHERE source.owner_id=owner_uuid AND p.profile IN (\'mineagent.rdagent-orchestrator.v2\',\'mineagent.rdagent-orchestrator.v3\',\'mineagent.rdagent-orchestrator.v4\')\n AND NOT EXISTS(SELECT 1 FROM research_process_receipts r WHERE r.admission_id=p.id AND r.kind=\'controller_child\'))\n THEN RAISE EXCEPTION \'Operational source requires retained child identity\'; END IF;\n FOR o IN SELECT * FROM factor_generation_observations WHERE owner_id=owner_uuid LOOP\n  SELECT * INTO st FROM factor_generation_starts WHERE id=o.start_id;\n  SELECT * INTO src FROM factor_generation_sources WHERE start_id=st.id;\n  SELECT * INTO cl FROM factor_controller_launches WHERE id=o.controller_launch_id;\n  IF src.id IS NULL OR st.logical_step<>0 OR o.logical_step<>0\n   OR cl.bootstrap->\'config\'->>\'max_iterations\'<>\'1\'\n   OR (st.owner_id,st.run_id,st.attempt_id,st.generation) IS DISTINCT FROM (o.owner_id,o.run_id,o.attempt_id,o.generation)\n  THEN RAISE EXCEPTION \'Initial actual generation boundary required\'; END IF;\n  expected:=jsonb_build_object(\'schema_version\',\'mineagent.rdagent-adoption-observation.v1\',\'logical_step\',0,\n   \'evaluated_source_id\',src.id,\'previous_adopted_source_id\',NULL,\'adopted_source_id\',src.id,\n   \'continuation_source_id\',src.id,\'adopted_new\',true);\n  IF o.decision IS DISTINCT FROM expected OR o.decision_sha256<>encode(sha256(convert_to(mineagent_rd_canonical_json(expected,true),\'UTF8\')),\'hex\')\n  THEN RAISE EXCEPTION \'Exact first generation adoption required\'; END IF;\n  IF NOT EXISTS(SELECT 1 FROM factor_upstream_calls WHERE start_id=st.id AND phase=\'knowledge_update\' AND kind=\'embedding\')\n  THEN RAISE EXCEPTION \'Actual upstream knowledge boundary required\'; END IF;\n  FOR c IN SELECT * FROM factor_upstream_calls WHERE start_id=st.id LOOP\n   SELECT * INTO co FROM factor_upstream_call_outcomes WHERE call_id=c.id;\n   SELECT count(*),jsonb_agg(m.id::text ORDER BY m.request_ordinal),jsonb_agg(mo.id::text ORDER BY m.request_ordinal)\n    INTO count_members,members,outcomes FROM factor_generation_model_operations m\n    JOIN research_model_operations op ON op.id=m.operation_id AND op.state=\'completed\'\n    JOIN research_model_transports mt ON mt.operation_id=op.id AND mt.state=\'completed\'\n    JOIN research_model_outcomes mo ON mo.transport_id=mt.id AND mo.outcome=\'completed\'\n    WHERE m.call_id=c.id AND m.protocol=(CASE WHEN cl.bootstrap#>>\'{config,schema_version}\'=\'mineagent.factor-research.v2\'\n      THEN (CASE c.kind WHEN \'chat\' THEN \'mineagent.rdagent-provider-chat.v1\' ELSE \'mineagent.rdagent-provider-embedding.v1\' END)\n      ELSE (CASE c.kind WHEN \'chat\' THEN \'mineagent.rdagent-chat.v1\' ELSE \'mineagent.rdagent-embedding.v1\' END) END);\n   IF co.id IS NULL OR co.status<>\'completed\' OR co.controller_launch_id<>cl.id OR count_members<1\n    OR count_members<>(SELECT count(*) FROM factor_generation_model_operations WHERE call_id=c.id)\n    OR (SELECT min(request_ordinal) FROM factor_generation_model_operations WHERE call_id=c.id)<>0\n    OR (SELECT max(request_ordinal) FROM factor_generation_model_operations WHERE call_id=c.id)<>count_members-1\n    OR co.member_count<>count_members OR co.member_ids IS DISTINCT FROM members OR co.response_outcome_ids IS DISTINCT FROM outcomes\n   THEN RAISE EXCEPTION \'All actual model calls must close before adoption\'; END IF;\n  END LOOP;\n END LOOP;\n IF EXISTS(SELECT 1 FROM factor_generation_boundaries b JOIN factor_generation_observations boundary_observation ON boundary_observation.id=b.observation_id\n WHERE b.owner_id=owner_uuid AND (b.boundary<>\'returned\' OR b.next_logical_step IS NOT NULL\n  OR (b.start_id,b.controller_launch_id,b.logical_step) IS DISTINCT FROM (boundary_observation.start_id,boundary_observation.controller_launch_id,boundary_observation.logical_step)))\n THEN RAISE EXCEPTION \'Exact returned first generation boundary required\'; END IF;\n RETURN NULL;\nEND $$;\nCREATE OR REPLACE FUNCTION @SCHEMA@.mineagent_rd_execution_generation_actor() RETURNS trigger\nLANGUAGE plpgsql SET search_path=@SCHEMA@,pg_catalog AS $$\nBEGIN\n IF NEW.outcome<>\'accepted\' OR NOT EXISTS(\n SELECT 1 FROM factor_execution_evaluation_outcomes ev\n JOIN factor_generation_boundaries b ON b.id=ev.boundary_id\n JOIN factor_controller_launches cl ON cl.id=ev.controller_launch_id\n JOIN research_process_admissions p ON p.id=cl.admission_id\n JOIN research_process_states state ON state.admission_id=p.id\n WHERE (ev.owner_id,ev.run_id,ev.attempt_id,ev.generation,ev.generation_start_id)=\n       (NEW.owner_id,NEW.run_id,NEW.attempt_id,NEW.generation,NEW.start_id)\n AND b.start_id=NEW.start_id AND b.boundary=\'returned\'\n AND p.profile IN (\'mineagent.rdagent-orchestrator.v2\',\'mineagent.rdagent-orchestrator.v3\',\'mineagent.rdagent-orchestrator.v4\') AND state.status=\'running\'\n AND EXISTS(SELECT 1 FROM research_process_receipts r WHERE r.admission_id=p.id AND r.kind=\'controller_child\'))\n THEN RAISE EXCEPTION \'Accepted execution requires current protected actor and actual snapshot result\'; END IF;\n RETURN NEW;\nEND $$;\nCREATE OR REPLACE FUNCTION @SCHEMA@.mineagent_rd_provider_graph(rid uuid) RETURNS void\nLANGUAGE plpgsql SET search_path=@SCHEMA@,pg_catalog AS $$\nDECLARE op record; run record; t record; w record; held record; settlement record; outcome record; amount jsonb; selected jsonb; n integer; attempt record; must_be_stopped boolean; config_checked boolean:=false; config_valid boolean; steer_digest text; binding jsonb; binding_valid boolean; binding_digest text; request_valid boolean; request_digest text; request_utf8 text; request_ascii text; output_tokens bigint; cost numeric;\nBEGIN\n SELECT * INTO run FROM research_runs WHERE id=rid;\n IF run.config->>\'controller_profile\'=\'mineagent.rdagent-orchestrator.v4\' THEN\n  PERFORM mineagent_rd_v4_seed_binding(rid);\n END IF;\n IF (SELECT count(*) FROM research_model_operations WHERE run_id=rid AND protocol IN (\'mineagent.rdagent-provider-chat.v1\',\'mineagent.rdagent-provider-embedding.v1\'))>32\n THEN RAISE EXCEPTION \'Provider profile permits at most 32 operations per run\'; END IF;\n FOR op IN SELECT * FROM research_model_operations WHERE run_id=rid AND protocol IN (\'mineagent.rdagent-provider-chat.v1\',\'mineagent.rdagent-provider-embedding.v1\') LOOP\n  IF run.id IS NULL OR (run.purpose,run.engine) IS DISTINCT FROM (\'factor_research\',\'rdagent\')\n  OR run.owner_id IS DISTINCT FROM op.owner_id\n  THEN RAISE EXCEPTION \'Provider operation/config/request identity differs\'; END IF;\n  -- Function-local pure values from the single captured run record only.\n  -- Lazy first operation preserves the empty-run and 32-operation boundaries.\n  -- No relational evidence or result survives this function invocation.\n  IF NOT config_checked THEN\n   config_valid:=mineagent_rd_provider_config(run.config);\n   IF config_valid IS TRUE THEN\n    steer_digest:=encode(sha256(convert_to(mineagent_rd_canonical_json(run.config->\'steer_snapshot\',true),\'UTF8\')),\'hex\');\n   END IF;\n\n   binding:=run.config->\'model_binding\'; binding_valid:=false; binding_digest:=NULL;\n   BEGIN\n    binding_valid:=mineagent_rd_provider_payload(\'binding\',binding);\n    IF binding_valid IS TRUE THEN\n     binding_digest:=encode(sha256(convert_to(mineagent_rd_canonical_json(binding,true),\'UTF8\')),\'hex\');\n    END IF;\n   EXCEPTION WHEN OTHERS THEN binding_valid:=false; binding_digest:=NULL;\n   END;\n   config_checked:=true;\n  END IF;\n\n  request_valid:=false; request_digest:=NULL; amount:=NULL;\n  BEGIN\n   IF binding_valid IS TRUE\n   AND mineagent_rd_provider_payload(op.request->>\'kind\',op.request) IS TRUE THEN\n    request_utf8:=mineagent_rd_canonical_json(op.request,false);\n    request_ascii:=mineagent_rd_canonical_json(op.request,true);\n    request_valid:=COALESCE(\n      op.request->>\'schema_version\'=\'mineagent.rdagent-provider-\'||(op.request->>\'kind\')||\'.v1\'\n      AND op.request->>\'model_profile_id\'=binding->>\'profile_id\'\n      AND op.request->>\'model_binding_sha256\'=binding_digest\n      AND octet_length(request_utf8)<=262144\n      AND octet_length(request_ascii)<=(binding->>\'max_request_bytes\')::bigint\n      AND CASE WHEN op.request->>\'kind\'=\'chat\' THEN\n       op.request->>\'model\'=binding->>\'chat_model\'\n       AND (op.request->>\'max_output_tokens\')::bigint<=(binding->>\'max_output_tokens\')::bigint\n      ELSE op.request->>\'model\'=binding->>\'embedding_model\'\n       AND op.request->\'dimensions\'=binding->\'embedding_dimensions\'\n       AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(op.request->\'inputs\') value WHERE length(value) NOT BETWEEN 1 AND 8192)\n      END,false);\n    IF request_valid IS TRUE THEN\n     request_digest:=encode(sha256(convert_to(request_utf8,\'UTF8\')),\'hex\');\n    END IF;\n   END IF;\n  EXCEPTION WHEN OTHERS THEN request_valid:=false; request_digest:=NULL;\n  END;\n  IF request_valid IS TRUE THEN\n   BEGIN\n    IF binding->\'pricing\'->>\'status\'=\'operator_declared\' THEN\n     output_tokens:=0;\n     IF op.request->>\'kind\'=\'chat\' THEN\n      output_tokens:=(op.request->>\'max_output_tokens\')::bigint;\n      cost:=262144::numeric*(binding->\'pricing\'->>\'chat_input_microusd_per_million\')::numeric\n       +output_tokens::numeric*(binding->\'pricing\'->>\'chat_output_microusd_per_million\')::numeric;\n     ELSE cost:=262144::numeric*(binding->\'pricing\'->>\'embedding_microusd_per_million\')::numeric;\n     END IF;\n     amount:=jsonb_build_object(\'calls\',1,\'tokens\',262144+output_tokens,\n      \'cost_microunits\',ceil(cost/1000000)::bigint,\'mutation_slots\',0,\'evaluator_executions\',0,\n      \'wall_milliseconds\',(binding->>\'request_deadline_ms\')::bigint,\'storage_bytes\',589824,\'process_slots\',1);\n    END IF;\n   EXCEPTION WHEN OTHERS THEN amount:=NULL;\n   END;\n  END IF;\n  IF config_valid IS NOT TRUE\n  OR run.config->\'steer_snapshot\'->>\'owner_id\' IS DISTINCT FROM op.owner_id::text\n  OR run.config->>\'steer_snapshot_sha256\' IS DISTINCT FROM steer_digest\n  OR request_valid IS NOT TRUE\n  OR op.protocol IS DISTINCT FROM op.request->>\'schema_version\'\n  OR op.request_sha256 IS DISTINCT FROM request_digest\n  THEN RAISE EXCEPTION \'Provider operation/config/request identity differs\'; END IF;\n  FOR selected IN SELECT value FROM jsonb_array_elements(run.config->\'steer_snapshot\'->\'versions\') LOOP\n   IF NOT EXISTS(SELECT 1 FROM rd_steer_versions sv\n    WHERE sv.owner_id=op.owner_id AND sv.id=(selected->>\'version_id\')::uuid\n    AND sv.steer_id=(selected->>\'steer_id\')::uuid AND sv.ordinal=(selected->>\'ordinal\')::integer\n    AND sv.kind=selected->>\'kind\' AND sv.text=selected->>\'text\' AND sv.text_sha256=selected->>\'text_sha256\'\n    AND sv.content_canonical::jsonb=selected\n    AND sv.content_sha256=encode(sha256(convert_to(mineagent_rd_canonical_json(selected,true),\'UTF8\')),\'hex\'))\n   THEN RAISE EXCEPTION \'Provider request selected steer version differs\'; END IF;\n  END LOOP;\n  IF amount IS NULL THEN RAISE EXCEPTION \'Provider pricing/reservation is unavailable\'; END IF;\n  SELECT count(*) INTO n FROM factor_generation_model_operations m\n   JOIN factor_upstream_calls c ON c.id=m.call_id\n   JOIN factor_generation_starts g ON g.id=m.start_id\n   JOIN factor_research_specs s ON s.id=g.spec_id\n   JOIN research_operation_contexts ctx ON ctx.id=m.context_id\n   WHERE m.operation_id=op.id AND m.protocol=op.protocol\n   AND (m.owner_id,m.run_id,m.attempt_id,m.generation)=(op.owner_id,op.run_id,op.attempt_id,op.generation)\n   AND (c.owner_id,c.run_id,c.attempt_id,c.generation)=(op.owner_id,op.run_id,op.attempt_id,op.generation)\n   AND (g.owner_id,g.run_id,g.attempt_id,g.generation)=(op.owner_id,op.run_id,op.attempt_id,op.generation)\n   AND (ctx.owner_id,ctx.run_id,ctx.attempt_id,ctx.generation)=(op.owner_id,op.run_id,op.attempt_id,op.generation)\n   AND (s.owner_id,s.run_id)=(op.owner_id,op.run_id) AND s.config=run.config AND s.config_sha256=run.request_sha256\n   AND c.start_id=g.id AND c.context_id=m.context_id AND g.context_id=m.context_id AND op.context_id=m.context_id\n   AND ctx.context->>\'spec_sha256\'=s.config_sha256 AND ctx.context->>\'input_sha256\'=s.input_sha256\n   AND c.kind=op.request->>\'kind\'\n   AND EXISTS(SELECT 1 FROM factor_controller_launches l JOIN factor_research_attempt_bindings b ON b.id=l.attempt_binding_id\n    JOIN research_process_admissions a ON a.id=l.admission_id\n    WHERE (l.owner_id,l.run_id,l.attempt_id,l.generation)=(op.owner_id,op.run_id,op.attempt_id,op.generation)\n    AND (b.owner_id,b.run_id,b.attempt_id,b.generation)=(op.owner_id,op.run_id,op.attempt_id,op.generation)\n    AND (a.owner_id,a.run_id,a.attempt_id,a.generation)=(op.owner_id,op.run_id,op.attempt_id,op.generation)\n    AND b.spec_id=s.id AND a.logical_operation_id=b.id\n    AND a.image_id=run.config->\'runtime\'->>\'orchestrator_image\' AND a.role=\'rd_orchestrator\' AND a.profile IN (\'mineagent.rdagent-orchestrator.v2\',\'mineagent.rdagent-orchestrator.v3\',\'mineagent.rdagent-orchestrator.v4\')\n    AND l.bootstrap->\'config\'=run.config AND l.bootstrap->>\'config_sha256\'=s.config_sha256);\n  IF n<>1 OR (SELECT count(*) FROM factor_generation_model_operations WHERE operation_id=op.id)<>1\n  THEN RAISE EXCEPTION \'Provider operation must belong to one exact controller call\'; END IF;\n  SELECT count(*) INTO n FROM research_model_transports WHERE operation_id=op.id;\n  IF n<>1 THEN RAISE EXCEPTION \'Provider operation needs exactly one initial transport; cannot automatically retry\'; END IF;\n  SELECT * INTO attempt FROM execution_attempts WHERE id=op.attempt_id;\n  IF attempt.id IS NULL OR (attempt.run_id,attempt.generation) IS DISTINCT FROM (op.run_id,op.generation)\n  THEN RAISE EXCEPTION \'Provider operation attempt scope differs\'; END IF;\n  must_be_stopped:=attempt.sandbox_stopped IS TRUE OR attempt.finished_at IS NOT NULL\n   OR attempt.status IN (\'succeeded\',\'failed\',\'cancelled\',\'interrupted\')\n   OR run.status IN (\'succeeded\',\'failed\',\'cancelled\',\'interrupted\');\n  FOR t IN SELECT * FROM research_model_transports WHERE operation_id=op.id LOOP\n   IF must_be_stopped AND (t.state IS NULL OR t.state NOT IN (\'completed\',\'failed\',\'unknown\'))\n   THEN RAISE EXCEPTION \'Terminal provider attempt requires terminal charged transport\'; END IF;\n   SELECT * INTO held FROM research_budget_reservations WHERE id=t.reservation_id;\n   IF (t.owner_id,t.run_id,t.attempt_id,t.generation) IS DISTINCT FROM (op.owner_id,op.run_id,op.attempt_id,op.generation)\n   OR (held.owner_id,held.run_id,held.attempt_id,held.generation) IS DISTINCT FROM (op.owner_id,op.run_id,op.attempt_id,op.generation)\n   OR held.purpose IS DISTINCT FROM \'model_transport\' OR held.amounts IS DISTINCT FROM amount OR t.ordinal<>1\n   THEN RAISE EXCEPTION \'Provider exact conservative reservation differs\'; END IF;\n   IF t.state IN (\'completed\',\'failed\',\'unknown\') THEN\n    SELECT * INTO settlement FROM research_budget_settlements WHERE reservation_id=held.id;\n    SELECT * INTO outcome FROM research_model_outcomes WHERE transport_id=t.id;\n    IF held.state IS DISTINCT FROM \'settled\' OR settlement.outcome IS DISTINCT FROM \'conservative_unknown\'\n    OR settlement.charge IS DISTINCT FROM amount OR outcome.usage IS DISTINCT FROM amount\n    OR outcome.outcome IS DISTINCT FROM t.state\n    OR (settlement.owner_id,settlement.run_id,settlement.attempt_id,settlement.generation) IS DISTINCT FROM (op.owner_id,op.run_id,op.attempt_id,op.generation)\n    OR (outcome.owner_id,outcome.run_id,outcome.attempt_id,outcome.generation) IS DISTINCT FROM (op.owner_id,op.run_id,op.attempt_id,op.generation)\n    THEN RAISE EXCEPTION \'Provider terminal usage cannot refund its whole held vector\'; END IF;\n   END IF;\n   IF (t.state=\'completed\' OR must_be_stopped) AND (SELECT array_agg(kind ORDER BY kind) FROM rd_provider_transport_receipts WHERE transport_id=t.id)\n      IS DISTINCT FROM ARRAY[\'intent\',\'started\',\'stopped\']::varchar[]\n   THEN RAISE EXCEPTION \'Provider completion needs all registered SDK evidence\'; END IF;\n  END LOOP;\n END LOOP;\n FOR w IN SELECT * FROM rd_provider_transport_receipts WHERE run_id=rid LOOP\n  IF NOT EXISTS(SELECT 1 FROM research_model_transports sdk_transport JOIN research_model_operations sdk_operation ON sdk_operation.id=sdk_transport.operation_id\n   JOIN research_objects obj ON obj.id=w.receipt_object_id\n   JOIN research_object_outcomes done ON done.object_id=obj.id AND done.owner_id=obj.owner_id AND done.object_kind=obj.object_kind AND done.sha256=obj.sha256\n   JOIN research_object_publications pub ON pub.id=done.publication_id\n   JOIN research_budget_reservations object_hold ON object_hold.id=pub.budget_reservation_id\n   JOIN research_budget_settlements settled ON settled.reservation_id=object_hold.id\n   WHERE sdk_transport.id=w.transport_id AND sdk_operation.protocol IN (\'mineagent.rdagent-provider-chat.v1\',\'mineagent.rdagent-provider-embedding.v1\')\n   AND (sdk_transport.owner_id,sdk_transport.run_id,sdk_transport.attempt_id,sdk_transport.generation)=(w.owner_id,w.run_id,w.attempt_id,w.generation)\n   AND (sdk_operation.owner_id,sdk_operation.run_id,sdk_operation.attempt_id,sdk_operation.generation)=(w.owner_id,w.run_id,w.attempt_id,w.generation)\n   AND (pub.owner_id,pub.run_id,pub.attempt_id,pub.generation)=(w.owner_id,w.run_id,w.attempt_id,w.generation)\n   AND (object_hold.owner_id,object_hold.run_id,object_hold.attempt_id,object_hold.generation)=(w.owner_id,w.run_id,w.attempt_id,w.generation)\n   AND (settled.owner_id,settled.run_id,settled.attempt_id,settled.generation)=(w.owner_id,w.run_id,w.attempt_id,w.generation)\n   AND w.receipt_object_kind=\'rd_provider_process_receipt\' AND obj.object_kind=w.receipt_object_kind AND obj.owner_id=w.owner_id\n   AND obj.sha256=w.receipt_sha256 AND obj.size_bytes=w.size_bytes AND w.size_bytes BETWEEN 1 AND 16384\n   AND pub.object_kind=obj.object_kind AND pub.sha256=obj.sha256 AND pub.size_bytes=obj.size_bytes\n   AND object_hold.purpose=\'object_storage\' AND object_hold.state=\'settled\' AND settled.outcome=\'conservative_unknown\' AND settled.charge=object_hold.amounts\n   AND (object_hold.amounts->>\'storage_bytes\')::numeric>=pub.peak_bytes)\n  THEN RAISE EXCEPTION \'Provider SDK membership needs exact charged published object\'; END IF;\n END LOOP;\nEND $$;\nCREATE OR REPLACE FUNCTION @SCHEMA@.mineagent_rd_fixture_source_violation_026(source_uuid uuid)\nRETURNS text LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog AS $$\nDECLARE s record; st record; c record; a record; w record; v record; obj record;\n p record; po record; co record; m record; op record; final_outcome record;\n ap record; wp record; r record; count_members integer; count_transports integer;\n selected_first integer; idx integer := 0; previous_id uuid := NULL;\n metadata jsonb; part_documents jsonb := \'[]\'::jsonb;\n member_ids uuid[] := ARRAY[]::uuid[]; outcome_ids uuid[] := ARRAY[]::uuid[];\nBEGIN\n SELECT * INTO s FROM @SCHEMA@.factor_generation_sources WHERE id=source_uuid;\n IF NOT FOUND THEN RETURN \'source_missing\'; END IF;\n IF NOT EXISTS (SELECT 1 FROM @SCHEMA@.research_runs rr WHERE rr.id=s.run_id AND rr.owner_id=s.owner_id\n  AND rr.purpose=\'factor_research\' AND rr.engine=\'rdagent\') THEN RETURN \'run_identity\'; END IF;\n SELECT * INTO st FROM @SCHEMA@.factor_generation_starts WHERE id=s.start_id;\n IF NOT FOUND OR (st.owner_id,st.run_id,st.attempt_id,st.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR st.context_id<>s.context_id THEN RETURN \'start_scope\'; END IF;\n SELECT * INTO c FROM @SCHEMA@.factor_upstream_calls WHERE id=s.call_id;\n IF NOT FOUND OR (c.owner_id,c.run_id,c.attempt_id,c.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR (c.start_id,c.context_id,c.phase,c.kind)\n  IS DISTINCT FROM (s.start_id,s.context_id,\'generation\'::varchar,\'chat\'::varchar) THEN RETURN \'generation_call\'; END IF;\n SELECT * INTO a FROM @SCHEMA@.factor_response_assemblies WHERE id=s.assembly_id;\n IF NOT FOUND OR (a.owner_id,a.run_id,a.attempt_id,a.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR (a.start_id,a.context_id,a.call_id)\n  IS DISTINCT FROM (s.start_id,s.context_id,s.call_id) THEN RETURN \'assembly_scope\'; END IF;\n SELECT * INTO w FROM @SCHEMA@.factor_source_read_witnesses WHERE source_id=s.id;\n IF NOT FOUND OR (w.owner_id,w.run_id,w.attempt_id,w.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR (w.assembly_id,w.call_id,w.source_sha256,w.part_count)\n  IS DISTINCT FROM (a.id,c.id,s.source_sha256,a.part_count) THEN RETURN \'source_read_witness\'; END IF;\n IF w.parser_profile<>\'mineagent.rdagent-source-parser.v1\' OR w.parser_source_sha256<>\n  \'a5a6a4a397f86b71caac2b1e056d200411c9d6254dff5e81d84aad8c19d1a583\' THEN RETURN \'parser_identity\'; END IF;\n SELECT * INTO co FROM @SCHEMA@.factor_upstream_call_outcomes WHERE call_id=c.id;\n IF NOT FOUND OR (co.owner_id,co.run_id,co.attempt_id,co.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR co.status<>\'completed\'\n  OR co.controller_launch_id<>w.controller_launch_id THEN RETURN \'call_completion\'; END IF;\n IF NOT EXISTS (SELECT 1 FROM @SCHEMA@.factor_controller_launches cl WHERE cl.id=w.controller_launch_id\n  AND (cl.owner_id,cl.run_id,cl.attempt_id,cl.generation)=(s.owner_id,s.run_id,s.attempt_id,s.generation)) THEN RETURN \'controller_scope\'; END IF;\n IF NOT EXISTS (SELECT 1 FROM @SCHEMA@.factor_controller_launches cl\n  JOIN @SCHEMA@.research_process_admissions pa ON pa.id=cl.admission_id\n  JOIN @SCHEMA@.factor_research_attempt_bindings ab ON ab.id=cl.attempt_binding_id\n  JOIN @SCHEMA@.factor_research_specs sp ON sp.id=ab.spec_id\n  JOIN @SCHEMA@.research_runs rr ON rr.id=s.run_id\n  WHERE cl.id=w.controller_launch_id AND (pa.owner_id,pa.run_id,pa.attempt_id,pa.generation)=(s.owner_id,s.run_id,s.attempt_id,s.generation) AND (ab.owner_id,ab.run_id,ab.attempt_id,ab.generation)=(s.owner_id,s.run_id,s.attempt_id,s.generation)\n  AND sp.owner_id=s.owner_id AND sp.run_id=s.run_id AND sp.id=st.spec_id AND rr.config=sp.config\n  AND pa.role=\'rd_orchestrator\' AND pa.profile IN (\'mineagent.rdagent-orchestrator.v1\',\'mineagent.rdagent-orchestrator.v2\',\'mineagent.rdagent-orchestrator.v3\',\'mineagent.rdagent-orchestrator.v4\')\n  AND pa.input_sha256=cl.bootstrap_sha256 AND pa.logical_operation_id=ab.id\n  AND pa.image_id=sp.config->\'runtime\'->>\'orchestrator_image\') THEN RETURN \'controller_admission\'; END IF;\n SELECT * INTO v FROM @SCHEMA@.factor_versions WHERE id=s.factor_version_id;\n IF NOT FOUND OR v.owner_id<>s.owner_id OR v.code_sha256<>s.source_sha256 OR v.source_kind<>\'rdagent\'\n  OR v.parent_version_id IS DISTINCT FROM st.parent_factor_version_id\n  OR v.source_event_key IS DISTINCT FROM \'rdagent:\'||s.start_id::text\n  OR v.source_provenance->>\'run_id\' IS DISTINCT FROM s.run_id::text\n  OR v.source_provenance->>\'start_id\' IS DISTINCT FROM s.start_id::text\n  OR v.source_provenance->>\'call_id\' IS DISTINCT FROM s.call_id::text\n  OR v.source_provenance->>\'assembly_sha256\' IS DISTINCT FROM a.object_sha256\n  OR encode(sha256(convert_to(v.code,\'UTF8\')),\'hex\')<>s.source_sha256\n  OR octet_length(v.code)<>w.source_size_bytes THEN RETURN \'factor_version\'; END IF;\n SELECT * INTO obj FROM @SCHEMA@.factor_objects WHERE id=v.code_object_id;\n IF NOT FOUND OR (obj.owner_id,obj.object_kind,obj.media_type,obj.sha256,obj.size_bytes,obj.id)\n  IS DISTINCT FROM (s.owner_id,\'code\'::varchar,\'text/plain\'::varchar,s.source_sha256,w.source_size_bytes::bigint,w.source_object_id)\n  OR w.source_object_kind<>\'code\' THEN RETURN \'source_code_object\'; END IF;\n SELECT * INTO p FROM @SCHEMA@.factor_source_publications WHERE start_id=s.start_id;\n IF NOT FOUND OR (p.owner_id,p.run_id,p.attempt_id,p.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR\n  (p.call_id,p.assembly_object_id,p.assembly_object_kind,p.assembly_sha256,p.source_sha256,p.size_bytes,p.factor_id,p.factor_version_id)\n  IS DISTINCT FROM (c.id,a.object_id,a.object_kind,a.object_sha256,s.source_sha256,w.source_size_bytes,v.factor_id,v.id)\n  THEN RETURN \'source_publication\'; END IF;\n SELECT * INTO po FROM @SCHEMA@.factor_source_publication_outcomes WHERE source_id=s.id;\n IF NOT FOUND OR (po.owner_id,po.run_id,po.attempt_id,po.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR po.publication_id<>p.id THEN RETURN \'source_publication_outcome\'; END IF;\n SELECT * INTO r FROM @SCHEMA@.research_budget_reservations WHERE id=p.budget_reservation_id;\n IF NOT FOUND OR (r.owner_id,r.run_id,r.attempt_id,r.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR r.purpose<>\'object_storage\'\n  OR r.logical_key<>\'rdsource:\'||s.start_id::text OR (r.amounts->>\'storage_bytes\')::numeric IS DISTINCT FROM p.peak_bytes::numeric\n  OR EXISTS (SELECT 1 FROM jsonb_each(r.amounts) x WHERE x.key<>\'storage_bytes\' AND x.value<>\'0\'::jsonb)\n  THEN RETURN \'source_reservation\'; END IF;\n IF NOT EXISTS (SELECT 1 FROM @SCHEMA@.engine_object_reservation_consumers ec WHERE ec.reservation_id=r.id\n  AND (ec.owner_id,ec.run_id,ec.attempt_id,ec.generation)=(s.owner_id,s.run_id,s.attempt_id,s.generation) AND ec.consumer_kind=\'factor_source\' AND ec.consumer_id=p.id)\n  THEN RETURN \'source_consumer_claim\'; END IF;\n SELECT count(*),max(request_ordinal) FILTER (WHERE relation<>\'continuation\') INTO count_members,selected_first\n  FROM @SCHEMA@.factor_generation_model_operations WHERE call_id=c.id;\n IF count_members NOT BETWEEN 1 AND 60 OR selected_first IS NULL OR\n  count_members-selected_first NOT BETWEEN 1 AND 6 OR co.member_count<>count_members\n  OR w.selected_first_ordinal<>selected_first OR w.part_count<>count_members-selected_first THEN RETURN \'member_cardinality\'; END IF;\n FOR m IN SELECT * FROM @SCHEMA@.factor_generation_model_operations WHERE call_id=c.id ORDER BY request_ordinal LOOP\n  IF (m.owner_id,m.run_id,m.attempt_id,m.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR (m.start_id,m.context_id,m.protocol)\n   IS DISTINCT FROM (s.start_id,s.context_id,\'mineagent.rdagent-chat.v1\'::varchar)\n   OR m.request_ordinal<>idx OR m.predecessor_id IS DISTINCT FROM previous_id\n   OR (idx=0 AND m.relation<>\'initial\') OR (idx>0 AND m.relation NOT IN (\'continuation\',\'semantic_repair\'))\n   THEN RETURN \'member_order_scope\'; END IF;\n  SELECT * INTO op FROM @SCHEMA@.research_model_operations WHERE id=m.operation_id;\n  IF NOT FOUND OR (op.owner_id,op.run_id,op.attempt_id,op.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR op.context_id<>s.context_id OR op.state<>\'completed\'\n   OR op.protocol<>m.protocol\n   OR op.purpose<>(CASE WHEN m.relation=\'continuation\' THEN \'continuation\' ELSE \'chat\' END)\n   OR op.request->>\'kind\' IS DISTINCT FROM \'chat\' OR op.request->>\'model\' IS DISTINCT FROM \'fixture.rdagent.v1\'\n   OR op.request->\'response_format\' IS DISTINCT FROM \'{"type":"json_object"}\'::jsonb THEN RETURN \'operation_scope\'; END IF;\n  SELECT count(*) INTO count_transports FROM @SCHEMA@.research_model_transports WHERE operation_id=op.id;\n  IF count_transports NOT BETWEEN 1 AND 256 OR EXISTS (\n   SELECT 1 FROM @SCHEMA@.research_model_transports t LEFT JOIN @SCHEMA@.research_model_outcomes o ON o.transport_id=t.id\n    LEFT JOIN @SCHEMA@.research_budget_reservations br ON br.id=t.reservation_id\n    LEFT JOIN @SCHEMA@.research_budget_settlements bs ON bs.reservation_id=br.id\n   WHERE t.operation_id=op.id AND ((t.owner_id,t.run_id,t.attempt_id,t.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR (o.owner_id,o.run_id,o.attempt_id,o.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation)\n    OR (br.owner_id,br.run_id,br.attempt_id,br.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR (bs.owner_id,bs.run_id,bs.attempt_id,bs.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation)\n    OR t.ordinal NOT BETWEEN 1 AND count_transports OR br.purpose<>\'model_transport\' OR br.state<>\'settled\'\n    OR t.state<>(CASE WHEN t.ordinal=count_transports THEN \'completed\' ELSE \'failed\' END)\n    OR o.outcome<>t.state OR o.usage IS DISTINCT FROM bs.charge OR bs.outcome<>\'measured\'\n    OR EXISTS (SELECT 1 FROM jsonb_each(bs.charge) amount WHERE amount.value::text::numeric>(br.amounts->>amount.key)::numeric)\n    OR (o.usage->>\'calls\')::numeric<>1 OR (br.amounts->>\'calls\')::numeric<>1)) THEN RETURN \'physical_transport_closure\'; END IF;\n  SELECT o.* INTO final_outcome FROM @SCHEMA@.research_model_transports t\n   JOIN @SCHEMA@.research_model_outcomes o ON o.transport_id=t.id\n   WHERE t.operation_id=op.id AND t.ordinal=count_transports AND o.outcome=\'completed\';\n  IF NOT FOUND OR NOT EXISTS (SELECT 1 FROM @SCHEMA@.research_objects ro\n    WHERE ro.id=final_outcome.response_object_id AND (ro.owner_id,ro.object_kind,ro.sha256)\n    =(s.owner_id,\'model_response\'::varchar,final_outcome.response_sha256)) THEN RETURN \'completed_response\'; END IF;\n  member_ids:=array_append(member_ids,m.id); outcome_ids:=array_append(outcome_ids,final_outcome.id);\n  IF idx>=selected_first THEN\n   SELECT * INTO ap FROM @SCHEMA@.factor_response_assembly_parts WHERE assembly_id=a.id AND ordinal=idx-selected_first;\n   IF NOT FOUND OR (ap.owner_id,ap.run_id,ap.attempt_id,ap.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR\n    (ap.call_id,ap.member_id,ap.outcome_id,ap.response_object_id,ap.response_object_kind,ap.response_sha256)\n    IS DISTINCT FROM (c.id,m.id,final_outcome.id,final_outcome.response_object_id,\'model_response\'::varchar,final_outcome.response_sha256)\n    THEN RETURN \'selected_assembly_part\'; END IF;\n   SELECT * INTO wp FROM @SCHEMA@.factor_source_read_parts WHERE witness_id=w.id AND ordinal=idx-selected_first;\n   IF NOT FOUND OR (wp.owner_id,wp.run_id,wp.attempt_id,wp.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR\n    (wp.assembly_part_id,wp.member_id,wp.outcome_id,wp.response_object_id,wp.response_object_kind,wp.response_sha256)\n    IS DISTINCT FROM (ap.id,m.id,final_outcome.id,ap.response_object_id,ap.response_object_kind,ap.response_sha256)\n    OR wp.finish_reason<>(CASE WHEN idx=count_members-1 THEN \'stop\' ELSE \'length\' END)\n    THEN RETURN \'selected_read_part\'; END IF;\n   part_documents:=part_documents||jsonb_build_array(to_jsonb(wp)-ARRAY[\'id\',\'created_at\',\'owner_id\',\'run_id\',\'attempt_id\',\'generation\',\'witness_id\']);\n  END IF;\n  previous_id:=m.id; idx:=idx+1;\n END LOOP;\n IF co.member_ids IS DISTINCT FROM to_jsonb(member_ids) OR co.response_outcome_ids IS DISTINCT FROM to_jsonb(outcome_ids)\n  THEN RETURN \'completed_call_inventory\'; END IF;\n IF (SELECT count(*) FROM @SCHEMA@.factor_response_assembly_parts WHERE assembly_id=a.id)<>w.part_count OR\n  (SELECT count(*) FROM @SCHEMA@.factor_source_read_parts WHERE witness_id=w.id)<>w.part_count OR\n  (SELECT sum(content_size_bytes) FROM @SCHEMA@.factor_source_read_parts WHERE witness_id=w.id) IS DISTINCT FROM w.raw_text_bytes::bigint\n  THEN RETURN \'selected_inventory_size\'; END IF;\n metadata:=jsonb_build_object(\'schema_version\',\'mineagent.source-read-witness.v1\',\n  \'scope\',jsonb_build_object(\'owner_id\',s.owner_id,\'run_id\',s.run_id,\'attempt_id\',s.attempt_id,\'generation\',s.generation),\n  \'header\',to_jsonb(w)-ARRAY[\'id\',\'created_at\',\'owner_id\',\'run_id\',\'attempt_id\',\'generation\',\'witness_sha256\'],\n  \'parts\',part_documents);\n IF encode(sha256(convert_to(@SCHEMA@.mineagent_rd_ascii_metadata(metadata),\'UTF8\')),\'hex\')<>w.witness_sha256\n  THEN RETURN \'witness_metadata_digest\'; END IF;\n RETURN NULL;\nEND $$;\nCREATE OR REPLACE FUNCTION @SCHEMA@.mineagent_rd_provider_source_violation(source_uuid uuid)\nRETURNS text LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog AS $$\nDECLARE s record; st record; c record; a record; w record; v record; obj record;\n p record; po record; co record; m record; op record; final_outcome record;\n ap record; wp record; r record; count_members integer; count_transports integer;\n selected_first integer; idx integer := 0; previous_id uuid := NULL;\n metadata jsonb; part_documents jsonb := \'[]\'::jsonb;\n member_ids uuid[] := ARRAY[]::uuid[]; outcome_ids uuid[] := ARRAY[]::uuid[];\nBEGIN\n SELECT * INTO s FROM @SCHEMA@.factor_generation_sources WHERE id=source_uuid;\n IF NOT FOUND THEN RETURN \'source_missing\'; END IF;\n IF NOT EXISTS (SELECT 1 FROM @SCHEMA@.research_runs rr WHERE rr.id=s.run_id AND rr.owner_id=s.owner_id\n  AND rr.purpose=\'factor_research\' AND rr.engine=\'rdagent\') THEN RETURN \'run_identity\'; END IF;\n SELECT * INTO st FROM @SCHEMA@.factor_generation_starts WHERE id=s.start_id;\n IF NOT FOUND OR (st.owner_id,st.run_id,st.attempt_id,st.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR st.context_id<>s.context_id THEN RETURN \'start_scope\'; END IF;\n SELECT * INTO c FROM @SCHEMA@.factor_upstream_calls WHERE id=s.call_id;\n IF NOT FOUND OR (c.owner_id,c.run_id,c.attempt_id,c.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR (c.start_id,c.context_id,c.phase,c.kind)\n  IS DISTINCT FROM (s.start_id,s.context_id,\'generation\'::varchar,\'chat\'::varchar) THEN RETURN \'generation_call\'; END IF;\n SELECT * INTO a FROM @SCHEMA@.factor_response_assemblies WHERE id=s.assembly_id;\n IF NOT FOUND OR (a.owner_id,a.run_id,a.attempt_id,a.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR (a.start_id,a.context_id,a.call_id)\n  IS DISTINCT FROM (s.start_id,s.context_id,s.call_id) THEN RETURN \'assembly_scope\'; END IF;\n SELECT * INTO w FROM @SCHEMA@.factor_source_read_witnesses WHERE source_id=s.id;\n IF NOT FOUND OR (w.owner_id,w.run_id,w.attempt_id,w.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR (w.assembly_id,w.call_id,w.source_sha256,w.part_count)\n  IS DISTINCT FROM (a.id,c.id,s.source_sha256,a.part_count) THEN RETURN \'source_read_witness\'; END IF;\n IF w.parser_profile<>\'mineagent.rdagent-provider-source-parser.v1\' OR w.parser_source_sha256<>\n  \'a5a6a4a397f86b71caac2b1e056d200411c9d6254dff5e81d84aad8c19d1a583\' THEN RETURN \'parser_identity\'; END IF;\n SELECT * INTO co FROM @SCHEMA@.factor_upstream_call_outcomes WHERE call_id=c.id;\n IF NOT FOUND OR (co.owner_id,co.run_id,co.attempt_id,co.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR co.status<>\'completed\'\n  OR co.controller_launch_id<>w.controller_launch_id THEN RETURN \'call_completion\'; END IF;\n IF NOT EXISTS (SELECT 1 FROM @SCHEMA@.factor_controller_launches cl WHERE cl.id=w.controller_launch_id\n  AND (cl.owner_id,cl.run_id,cl.attempt_id,cl.generation)=(s.owner_id,s.run_id,s.attempt_id,s.generation)) THEN RETURN \'controller_scope\'; END IF;\n IF NOT EXISTS (SELECT 1 FROM @SCHEMA@.factor_controller_launches cl\n  JOIN @SCHEMA@.research_process_admissions pa ON pa.id=cl.admission_id\n  JOIN @SCHEMA@.factor_research_attempt_bindings ab ON ab.id=cl.attempt_binding_id\n  JOIN @SCHEMA@.factor_research_specs sp ON sp.id=ab.spec_id\n  JOIN @SCHEMA@.research_runs rr ON rr.id=s.run_id\n  WHERE cl.id=w.controller_launch_id AND (pa.owner_id,pa.run_id,pa.attempt_id,pa.generation)=(s.owner_id,s.run_id,s.attempt_id,s.generation) AND (ab.owner_id,ab.run_id,ab.attempt_id,ab.generation)=(s.owner_id,s.run_id,s.attempt_id,s.generation)\n  AND sp.owner_id=s.owner_id AND sp.run_id=s.run_id AND sp.id=st.spec_id AND rr.config=sp.config\n  AND pa.role=\'rd_orchestrator\' AND pa.profile IN (\'mineagent.rdagent-orchestrator.v1\',\'mineagent.rdagent-orchestrator.v2\',\'mineagent.rdagent-orchestrator.v3\',\'mineagent.rdagent-orchestrator.v4\')\n  AND pa.input_sha256=cl.bootstrap_sha256 AND pa.logical_operation_id=ab.id\n  AND pa.image_id=sp.config->\'runtime\'->>\'orchestrator_image\') THEN RETURN \'controller_admission\'; END IF;\n SELECT * INTO v FROM @SCHEMA@.factor_versions WHERE id=s.factor_version_id;\n IF NOT FOUND OR v.owner_id<>s.owner_id OR v.code_sha256<>s.source_sha256 OR v.source_kind<>\'rdagent\'\n  OR v.parent_version_id IS DISTINCT FROM st.parent_factor_version_id\n  OR v.source_event_key IS DISTINCT FROM \'rdagent:\'||s.start_id::text\n  OR v.source_provenance->>\'run_id\' IS DISTINCT FROM s.run_id::text\n  OR v.source_provenance->>\'start_id\' IS DISTINCT FROM s.start_id::text\n  OR v.source_provenance->>\'call_id\' IS DISTINCT FROM s.call_id::text\n  OR v.source_provenance->>\'assembly_sha256\' IS DISTINCT FROM a.object_sha256\n  OR encode(sha256(convert_to(v.code,\'UTF8\')),\'hex\')<>s.source_sha256\n  OR octet_length(v.code)<>w.source_size_bytes THEN RETURN \'factor_version\'; END IF;\n SELECT * INTO obj FROM @SCHEMA@.factor_objects WHERE id=v.code_object_id;\n IF NOT FOUND OR (obj.owner_id,obj.object_kind,obj.media_type,obj.sha256,obj.size_bytes,obj.id)\n  IS DISTINCT FROM (s.owner_id,\'code\'::varchar,\'text/plain\'::varchar,s.source_sha256,w.source_size_bytes::bigint,w.source_object_id)\n  OR w.source_object_kind<>\'code\' THEN RETURN \'source_code_object\'; END IF;\n SELECT * INTO p FROM @SCHEMA@.factor_source_publications WHERE start_id=s.start_id;\n IF NOT FOUND OR (p.owner_id,p.run_id,p.attempt_id,p.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR\n  (p.call_id,p.assembly_object_id,p.assembly_object_kind,p.assembly_sha256,p.source_sha256,p.size_bytes,p.factor_id,p.factor_version_id)\n  IS DISTINCT FROM (c.id,a.object_id,a.object_kind,a.object_sha256,s.source_sha256,w.source_size_bytes,v.factor_id,v.id)\n  THEN RETURN \'source_publication\'; END IF;\n SELECT * INTO po FROM @SCHEMA@.factor_source_publication_outcomes WHERE source_id=s.id;\n IF NOT FOUND OR (po.owner_id,po.run_id,po.attempt_id,po.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR po.publication_id<>p.id THEN RETURN \'source_publication_outcome\'; END IF;\n SELECT * INTO r FROM @SCHEMA@.research_budget_reservations WHERE id=p.budget_reservation_id;\n IF NOT FOUND OR (r.owner_id,r.run_id,r.attempt_id,r.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR r.purpose<>\'object_storage\'\n  OR r.logical_key<>\'rdsource:\'||s.start_id::text OR (r.amounts->>\'storage_bytes\')::numeric IS DISTINCT FROM p.peak_bytes::numeric\n  OR EXISTS (SELECT 1 FROM jsonb_each(r.amounts) x WHERE x.key<>\'storage_bytes\' AND x.value<>\'0\'::jsonb)\n  THEN RETURN \'source_reservation\'; END IF;\n IF NOT EXISTS (SELECT 1 FROM @SCHEMA@.engine_object_reservation_consumers ec WHERE ec.reservation_id=r.id\n  AND (ec.owner_id,ec.run_id,ec.attempt_id,ec.generation)=(s.owner_id,s.run_id,s.attempt_id,s.generation) AND ec.consumer_kind=\'factor_source\' AND ec.consumer_id=p.id)\n  THEN RETURN \'source_consumer_claim\'; END IF;\n SELECT count(*),max(request_ordinal) FILTER (WHERE relation<>\'continuation\') INTO count_members,selected_first\n  FROM @SCHEMA@.factor_generation_model_operations WHERE call_id=c.id;\n IF count_members NOT BETWEEN 1 AND 60 OR selected_first IS NULL OR\n  count_members-selected_first NOT BETWEEN 1 AND 6 OR co.member_count<>count_members\n  OR w.selected_first_ordinal<>selected_first OR w.part_count<>count_members-selected_first THEN RETURN \'member_cardinality\'; END IF;\n FOR m IN SELECT * FROM @SCHEMA@.factor_generation_model_operations WHERE call_id=c.id ORDER BY request_ordinal LOOP\n  IF (m.owner_id,m.run_id,m.attempt_id,m.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR (m.start_id,m.context_id,m.protocol)\n   IS DISTINCT FROM (s.start_id,s.context_id,\'mineagent.rdagent-provider-chat.v1\'::varchar)\n   OR m.request_ordinal<>idx OR m.predecessor_id IS DISTINCT FROM previous_id\n   OR (idx=0 AND m.relation<>\'initial\') OR (idx>0 AND m.relation NOT IN (\'continuation\',\'semantic_repair\'))\n   THEN RETURN \'member_order_scope\'; END IF;\n  SELECT * INTO op FROM @SCHEMA@.research_model_operations WHERE id=m.operation_id;\n  IF NOT FOUND OR (op.owner_id,op.run_id,op.attempt_id,op.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR op.context_id<>s.context_id OR op.state<>\'completed\'\n   OR op.protocol<>m.protocol\n   OR op.purpose<>(CASE WHEN m.relation=\'continuation\' THEN \'continuation\' ELSE \'chat\' END)\n   OR op.request->>\'kind\' IS DISTINCT FROM \'chat\' OR op.request->>\'model\' IS DISTINCT FROM (SELECT config#>>\'{model_binding,chat_model}\' FROM @SCHEMA@.research_runs WHERE id=s.run_id)\n   OR op.request->\'response_format\' IS DISTINCT FROM \'{"type":"json_object"}\'::jsonb THEN RETURN \'operation_scope\'; END IF;\n  SELECT count(*) INTO count_transports FROM @SCHEMA@.research_model_transports WHERE operation_id=op.id;\n  IF count_transports<>1 OR EXISTS (\n   SELECT 1 FROM @SCHEMA@.research_model_transports t LEFT JOIN @SCHEMA@.research_model_outcomes o ON o.transport_id=t.id\n    LEFT JOIN @SCHEMA@.research_budget_reservations br ON br.id=t.reservation_id\n    LEFT JOIN @SCHEMA@.research_budget_settlements bs ON bs.reservation_id=br.id\n   WHERE t.operation_id=op.id AND ((t.owner_id,t.run_id,t.attempt_id,t.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR (o.owner_id,o.run_id,o.attempt_id,o.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation)\n    OR (br.owner_id,br.run_id,br.attempt_id,br.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR (bs.owner_id,bs.run_id,bs.attempt_id,bs.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation)\n    OR t.ordinal NOT BETWEEN 1 AND count_transports OR br.purpose<>\'model_transport\' OR br.state<>\'settled\'\n    OR t.state<>(CASE WHEN t.ordinal=count_transports THEN \'completed\' ELSE \'failed\' END)\n    OR o.outcome<>t.state OR o.usage IS DISTINCT FROM bs.charge OR (bs.outcome<>\'conservative_unknown\' OR bs.charge IS DISTINCT FROM br.amounts)\n    OR EXISTS (SELECT 1 FROM jsonb_each(bs.charge) amount WHERE amount.value::text::numeric>(br.amounts->>amount.key)::numeric)\n    OR (o.usage->>\'calls\')::numeric<>1 OR (br.amounts->>\'calls\')::numeric<>1)) THEN RETURN \'physical_transport_closure\'; END IF;\n  SELECT o.* INTO final_outcome FROM @SCHEMA@.research_model_transports t\n   JOIN @SCHEMA@.research_model_outcomes o ON o.transport_id=t.id\n   WHERE t.operation_id=op.id AND t.ordinal=count_transports AND o.outcome=\'completed\';\n  IF NOT FOUND OR NOT EXISTS (SELECT 1 FROM @SCHEMA@.research_objects ro\n    WHERE ro.id=final_outcome.response_object_id AND (ro.owner_id,ro.object_kind,ro.sha256)\n    =(s.owner_id,\'model_response\'::varchar,final_outcome.response_sha256)) THEN RETURN \'completed_response\'; END IF;\n  member_ids:=array_append(member_ids,m.id); outcome_ids:=array_append(outcome_ids,final_outcome.id);\n  IF idx>=selected_first THEN\n   SELECT * INTO ap FROM @SCHEMA@.factor_response_assembly_parts WHERE assembly_id=a.id AND ordinal=idx-selected_first;\n   IF NOT FOUND OR (ap.owner_id,ap.run_id,ap.attempt_id,ap.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR\n    (ap.call_id,ap.member_id,ap.outcome_id,ap.response_object_id,ap.response_object_kind,ap.response_sha256)\n    IS DISTINCT FROM (c.id,m.id,final_outcome.id,final_outcome.response_object_id,\'model_response\'::varchar,final_outcome.response_sha256)\n    THEN RETURN \'selected_assembly_part\'; END IF;\n   SELECT * INTO wp FROM @SCHEMA@.factor_source_read_parts WHERE witness_id=w.id AND ordinal=idx-selected_first;\n   IF NOT FOUND OR (wp.owner_id,wp.run_id,wp.attempt_id,wp.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR\n    (wp.assembly_part_id,wp.member_id,wp.outcome_id,wp.response_object_id,wp.response_object_kind,wp.response_sha256)\n    IS DISTINCT FROM (ap.id,m.id,final_outcome.id,ap.response_object_id,ap.response_object_kind,ap.response_sha256)\n    OR wp.finish_reason<>(CASE WHEN idx=count_members-1 THEN \'stop\' ELSE \'length\' END)\n    THEN RETURN \'selected_read_part\'; END IF;\n   part_documents:=part_documents||jsonb_build_array(to_jsonb(wp)-ARRAY[\'id\',\'created_at\',\'owner_id\',\'run_id\',\'attempt_id\',\'generation\',\'witness_id\']);\n  END IF;\n  previous_id:=m.id; idx:=idx+1;\n END LOOP;\n IF co.member_ids IS DISTINCT FROM to_jsonb(member_ids) OR co.response_outcome_ids IS DISTINCT FROM to_jsonb(outcome_ids)\n  THEN RETURN \'completed_call_inventory\'; END IF;\n IF (SELECT count(*) FROM @SCHEMA@.factor_response_assembly_parts WHERE assembly_id=a.id)<>w.part_count OR\n  (SELECT count(*) FROM @SCHEMA@.factor_source_read_parts WHERE witness_id=w.id)<>w.part_count OR\n  (SELECT sum(content_size_bytes) FROM @SCHEMA@.factor_source_read_parts WHERE witness_id=w.id) IS DISTINCT FROM w.raw_text_bytes::bigint\n  THEN RETURN \'selected_inventory_size\'; END IF;\n metadata:=jsonb_build_object(\'schema_version\',\'mineagent.source-read-witness.v1\',\n  \'scope\',jsonb_build_object(\'owner_id\',s.owner_id,\'run_id\',s.run_id,\'attempt_id\',s.attempt_id,\'generation\',s.generation),\n  \'header\',to_jsonb(w)-ARRAY[\'id\',\'created_at\',\'owner_id\',\'run_id\',\'attempt_id\',\'generation\',\'witness_sha256\'],\n  \'parts\',part_documents);\n IF encode(sha256(convert_to(@SCHEMA@.mineagent_rd_ascii_metadata(metadata),\'UTF8\')),\'hex\')<>w.witness_sha256\n  THEN RETURN \'witness_metadata_digest\'; END IF;\n RETURN NULL;\nEND $$;\nCREATE OR REPLACE FUNCTION @SCHEMA@.mineagent_rd_provider_queued_config(rid uuid) RETURNS void\nLANGUAGE plpgsql SET search_path=@SCHEMA@,pg_catalog AS $$\nDECLARE r research_runs%ROWTYPE; v jsonb; price jsonb; max_cost numeric;\nBEGIN\n SELECT * INTO STRICT r FROM research_runs WHERE id=rid;\n v:=r.config; price:=v#>\'{model_binding,pricing}\';\n IF mineagent_rd_provider_config(v) IS NOT TRUE OR v->>\'max_iterations\'<>\'1\'\n OR v#>>\'{steer_snapshot,owner_id}\'<>r.owner_id::text\n OR price->>\'status\' IS DISTINCT FROM \'operator_declared\'\n THEN RAISE EXCEPTION \'Configured provider declaration differs\'; END IF;\n max_cost:=32*ceil(greatest(262144*(price->>\'chat_input_microusd_per_million\')::numeric\n  +(v#>>\'{model_binding,max_output_tokens}\')::numeric*(price->>\'chat_output_microusd_per_million\')::numeric,\n  262144*(price->>\'embedding_microusd_per_million\')::numeric)/1000000);\n IF (v#>>\'{budget,calls}\')::numeric<32\n OR (v#>>\'{budget,tokens}\')::numeric<32*(262144+(v#>>\'{model_binding,max_output_tokens}\')::numeric)\n OR (v#>>\'{budget,cost_microunits}\')::numeric<max_cost\n OR (v#>>\'{budget,process_slots}\')::numeric<36\n OR (v#>>\'{budget,wall_milliseconds}\')::numeric< (CASE WHEN v->>\'controller_profile\'=\'mineagent.rdagent-orchestrator.v4\' THEN 360000 WHEN v->>\'controller_profile\'=\'mineagent.rdagent-orchestrator.v3\' THEN 300000 ELSE 240000 END)+32*(v#>>\'{model_binding,request_deadline_ms}\')::numeric\n OR (v#>>\'{budget,storage_bytes}\')::numeric<536870912+32*589824\n OR (v#>>\'{budget,evaluator_executions}\')::numeric<1\n THEN RAISE EXCEPTION \'Configured provider work exceeds declared admission budget\'; END IF;\nEND $$;\nCREATE OR REPLACE FUNCTION @SCHEMA@.mineagent_rd_seed_check(sid uuid) RETURNS void\nLANGUAGE plpgsql SET search_path=@SCHEMA@,pg_catalog AS $$\nDECLARE s factor_seeded_submissions%ROWTYPE; r research_runs%ROWTYPE;\n p factor_analysis_plans%ROWTYPE; sp factor_research_specs%ROWTYPE;\n v factor_versions%ROWTYPE; o factor_objects%ROWTYPE;\n expected jsonb; exact_bytes text; fields jsonb; profile_sha text; provider boolean; preflight jsonb;\nBEGIN\n SELECT * INTO STRICT s FROM factor_seeded_submissions WHERE id=sid;\n SELECT * INTO STRICT r FROM research_runs WHERE id=s.run_id;\n SELECT * INTO STRICT sp FROM factor_research_specs WHERE id=s.spec_id;\n SELECT * INTO STRICT p FROM factor_analysis_plans WHERE id=s.analysis_plan_id;\n provider:=r.config->>\'schema_version\'=\'mineagent.factor-research.v2\';\n SELECT * INTO STRICT v FROM factor_versions WHERE id=s.parent_factor_version_id;\n SELECT * INTO STRICT o FROM factor_objects WHERE id=s.parent_code_object_id;\n PERFORM mineagent_analysis_plan_check(p.id);\n IF provider THEN PERFORM mineagent_rd_provider_queued_config(r.id); END IF;\n IF (r.owner_id,r.idempotency_key,r.purpose,r.engine,r.request_sha256)\n IS DISTINCT FROM (s.owner_id,s.idempotency_key,\'factor_research\'::varchar,\'rdagent\'::varchar,s.config_sha256)\n OR (sp.owner_id,sp.run_id,sp.config_sha256,sp.input_sha256)\n IS DISTINCT FROM (s.owner_id,r.id,s.config_sha256,p.input_sha256)\n OR (p.owner_id,p.run_id,p.spec_id,p.config_sha256)\n IS DISTINCT FROM (s.owner_id,r.id,sp.id,s.config_sha256)\n OR r.config->>\'max_iterations\' IS DISTINCT FROM \'1\'\n OR (NOT provider AND (r.config->\'task\'->>\'factor_kind\' IS DISTINCT FROM \'time_series\'\n OR r.config->\'task\'->>\'output_unit\' IS DISTINCT FROM \'return\'\n OR r.config->\'task\'->>\'formulation\' IS DISTINCT FROM\n (\'close[t]/close[t-\'||(r.config->\'input\'->>\'lookback_sessions\')||\']-1\')))\n THEN RAISE EXCEPTION \'Seeded request exact run/spec/plan/profile binding differs\'; END IF;\n IF (v.owner_id,v.factor_id,v.ordinal,v.code_object_id,v.code_sha256,v.definition_sha256)\n IS DISTINCT FROM (s.owner_id,s.parent_factor_id,s.parent_ordinal,s.parent_code_object_id,s.parent_code_sha256,s.parent_definition_sha256)\n OR (o.owner_id,o.object_kind,o.media_type,o.sha256,o.size_bytes,o.storage_key)\n IS DISTINCT FROM (s.owner_id,\'code\'::varchar,\'text/plain\'::varchar,s.parent_code_sha256,\n s.parent_code_size_bytes::bigint,\'factors/\'||s.owner_id::text||\'/objects/\'||s.parent_code_sha256||\'.py\')\n OR octet_length(v.code)<>s.parent_code_size_bytes\n OR encode(sha256(convert_to(v.code,\'UTF8\')),\'hex\')<>s.parent_code_sha256\n OR NOT EXISTS(SELECT 1 FROM factors WHERE id=s.parent_factor_id AND owner_id=s.owner_id)\n OR mineagent_analysis_raw_commitment(s.parent_provenance_canonical,v.source_provenance,s.parent_provenance_sha256,65536) IS NOT TRUE\n OR s.parent_binding_sha256 IS DISTINCT FROM mineagent_execution_metadata_sha(mineagent_rd_seed_reference(s.id))\n THEN RAISE EXCEPTION \'Seeded parent exact retained metadata binding differs\'; END IF;\n IF NOT EXISTS(SELECT 1 FROM outbox_events WHERE run_id=r.id AND generation=1)\n OR NOT EXISTS(SELECT 1 FROM research_budget_controls WHERE run_id=r.id AND owner_id=r.owner_id AND limits=r.config->\'budget\')\n OR EXISTS(SELECT 1 FROM factor_research_submissions WHERE run_id=r.id)\n THEN RAISE EXCEPTION \'Seeded receipt requires one family, durable outbox and budget\'; END IF;\n SELECT jsonb_agg(value->\'name\' ORDER BY ord) INTO fields\n FROM jsonb_array_elements(r.config->\'input\'->\'input_fields\') WITH ORDINALITY f(value,ord);\n IF NOT provider AND (fields @> \'["close"]\'::jsonb) IS NOT TRUE THEN RAISE EXCEPTION \'Seeded fixed model requires close\'; END IF;\n expected:=jsonb_build_object(\'schema_version\',\'mineagent.rdagent-seeded-submission.v1\',\n \'purpose\',\'factor_research\',\'engine\',\'rdagent\',\'dataset_version_id\',r.dataset_version_id::text,\n \'window\',r.config->\'input\'->\'window\',\'input_fields\',fields,\n \'lookback_sessions\',r.config->\'input\'->\'lookback_sessions\',\'lag_sessions\',r.config->\'input\'->\'lag_sessions\',\n \'task\',r.config->\'task\',\'objective\',p.objective,\'budget\',r.config->\'budget\',\n \'max_iterations\',r.config->\'max_iterations\',\'source_policy\',p.source_policy,\n \'parent_factor_version_id\',s.parent_factor_version_id::text);\n IF provider THEN\n  expected:=expected || jsonb_build_object(\'schema_version\',\'mineagent.rdagent-provider-seeded-submission.v1\',\n   \'model_profile_id\',r.config#>>\'{model_binding,profile_id}\',\n   \'selected_steer_version_ids\',coalesce((SELECT jsonb_agg(value->\'version_id\' ORDER BY ord)\n      FROM jsonb_array_elements(r.config#>\'{steer_snapshot,versions}\') WITH ORDINALITY x(value,ord)),\'[]\'::jsonb));\n END IF;\n SELECT \'{\'||string_agg(mineagent_rd_canonical_json(to_jsonb(key),true)||\':\'||\n CASE WHEN key=\'objective\' THEN p.objective_canonical ELSE mineagent_rd_canonical_json(value,true) END,\n \',\' ORDER BY key COLLATE "C")||\'}\' INTO exact_bytes FROM jsonb_each(expected);\n profile_sha:=mineagent_execution_metadata_sha(jsonb_build_object(\n \'schema_version\',\'mineagent.rdagent-seeded-server-profile.v1\',\'profile\',\'configured_rd_seeded_single_output_session_v1\',\n \'model_profile\',\'fixture.rdagent.v1\',\'runtime\',r.config->\'runtime\',\'qlib_installed_parent_image_id\',p.qlib_installed_parent_image_id) || mineagent_rd_controller_selection(r.config));\n IF provider THEN\n  profile_sha:=mineagent_execution_metadata_sha(jsonb_build_object(\n   \'schema_version\',\'mineagent.rdagent-provider-server-profile.v1\',\'profile\',\'configured_rd_model_single_output_session_v1\',\n   \'model_profile\',\'configured.rdagent.v1\',\'runtime\',r.config->\'runtime\',\'qlib_installed_parent_image_id\',p.qlib_installed_parent_image_id) || CASE WHEN r.config->>\'controller_profile\'=\'mineagent.rdagent-orchestrator.v4\' THEN jsonb_build_object(\'controller_profile\',\'mineagent.rdagent-orchestrator.v3\',\'seeded_controller_profile\',\'mineagent.rdagent-orchestrator.v4\') ELSE mineagent_rd_controller_selection(r.config) END);\n  preflight:=jsonb_build_object(\'schema_version\',\'mineagent.rdagent-provider-preflight-binding.v1\',\n   \'owner_id\',s.owner_id::text,\'request_sha256\',s.request_sha256,\n   \'dataset_content_sha256\',p.label_source_manifest_sha256,\'frozen_input_sha256\',p.input_sha256,\n   \'catalog_revision\',\'configured_rd_model_single_output_session_v1\',\'runtime_profile_sha256\',profile_sha,\n   \'model_binding_sha256\',mineagent_execution_metadata_sha(r.config->\'model_binding\'),\n   \'steer_snapshot_sha256\',r.config->>\'steer_snapshot_sha256\',\'parent_binding_sha256\',s.parent_binding_sha256);\n ELSE\n  preflight:=jsonb_build_object(\n   \'schema_version\',\'mineagent.rdagent-seeded-preflight-binding.v1\',\'owner_id\',s.owner_id::text,\n   \'request_sha256\',s.request_sha256,\'parent_binding_sha256\',s.parent_binding_sha256,\n   \'dataset_content_sha256\',p.label_source_manifest_sha256,\'frozen_input_sha256\',p.input_sha256,\n   \'catalog_revision\',\'configured_rd_seeded_single_output_session_v1\',\'runtime_profile_sha256\',profile_sha);\n END IF;\n IF s.request_canonical IS DISTINCT FROM exact_bytes\n OR s.request_sha256 IS DISTINCT FROM encode(sha256(convert_to(exact_bytes,\'UTF8\')),\'hex\')\n OR s.runtime_profile_sha256 IS DISTINCT FROM profile_sha\n OR s.preflight_sha256 IS DISTINCT FROM mineagent_execution_metadata_sha(preflight)\n THEN RAISE EXCEPTION \'Seeded canonical declaration or preflight differs\'; END IF;\n IF EXISTS(SELECT 1 FROM factor_generation_starts st WHERE st.run_id=r.id AND st.logical_step=0\n AND (st.owner_id<>s.owner_id OR st.parent_factor_version_id IS DISTINCT FROM s.parent_factor_version_id))\n OR EXISTS(SELECT 1 FROM factor_source_publications pub JOIN factor_generation_starts st ON st.id=pub.start_id\n WHERE st.run_id=r.id AND st.logical_step=0 AND pub.factor_id IS DISTINCT FROM s.parent_factor_id)\n THEN RAISE EXCEPTION \'Seeded initial source must retain declared parent and factor family\'; END IF;\nEND $$;ALTER TABLE @SCHEMA@.research_process_admissions DROP CONSTRAINT ck_process_v2_unregistered, ADD CONSTRAINT ck_process_v2_unregistered CHECK ((((schema_version=\'mineagent.process-admission.v1\' OR\n (schema_version=\'mineagent.process-admission.v2\' AND ipc_policy=\'none\' AND ticket_sha256 IS NULL AND (\n (role=\'factor_cutoff_candidate\' AND profile=\'mineagent.factor-prefix-candidate.v2\') OR\n (role=\'factor_normalizer\' AND profile=\'mineagent.factor-numeric-hdf.v1\') OR\n (role=\'native_evaluator\' AND profile IN (\'mineagent.qlib-direct-analysis.v1\',\'mineagent.openevolve-native-evaluator.v1\')))) OR\n (schema_version=\'mineagent.process-admission.v2\' AND ipc_policy=\'host_ticket\' AND ticket_sha256 ~ \'^[a-f0-9]{64}$\' AND (\n (role=\'rd_orchestrator\' AND profile IN (\'mineagent.rdagent-orchestrator.v1\',\'mineagent.rdagent-orchestrator.v2\',\'mineagent.rdagent-orchestrator.v3\',\'mineagent.rdagent-orchestrator.v4\')) OR\n (role=\'openevolve_orchestrator\' AND profile=\'mineagent.openevolve-orchestrator.v1\')))) IS TRUE) OR (schema_version=\'mineagent.process-admission.v2\'\n AND role=\'native_evaluator\' AND profile=\'mineagent.factor-strategy-engine.v1\'\n AND ipc_policy=\'none\' AND ticket_sha256 IS NULL)) IS TRUE);CREATE CONSTRAINT TRIGGER rd_v4_seed_binding AFTER INSERT OR UPDATE OR DELETE ON @SCHEMA@.research_runs DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION @SCHEMA@.mineagent_rd_v4_seed_deferred();\nCREATE CONSTRAINT TRIGGER rd_v4_seed_binding AFTER INSERT OR UPDATE OR DELETE ON @SCHEMA@.factor_seeded_submissions DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION @SCHEMA@.mineagent_rd_v4_seed_deferred();\nCREATE CONSTRAINT TRIGGER rd_v4_seed_binding AFTER INSERT OR UPDATE OR DELETE ON @SCHEMA@.factor_research_submissions DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION @SCHEMA@.mineagent_rd_v4_seed_deferred();\nCREATE CONSTRAINT TRIGGER rd_v4_seed_binding AFTER INSERT OR UPDATE OR DELETE ON @SCHEMA@.research_process_admissions DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION @SCHEMA@.mineagent_rd_v4_seed_deferred();'
DOWNGRADE_SQL = 'DO $$ BEGIN\n IF EXISTS(SELECT 1 FROM @SCHEMA@.research_process_admissions WHERE profile=\'mineagent.rdagent-orchestrator.v4\')\n OR EXISTS(SELECT 1 FROM @SCHEMA@.research_runs WHERE config->>\'controller_profile\'=\'mineagent.rdagent-orchestrator.v4\')\n THEN RAISE EXCEPTION \'Retained controller v4 data forbids downgrade\'; END IF;\nEND $$;\n\nCREATE OR REPLACE FUNCTION @SCHEMA@.mineagent_rd_controller_selection(v jsonb) RETURNS jsonb\nLANGUAGE sql IMMUTABLE SET search_path=@SCHEMA@,pg_catalog AS $$\n SELECT CASE WHEN jsonb_typeof(v) IS DISTINCT FROM \'object\' THEN NULL\n WHEN NOT (v ? \'controller_profile\') THEN \'{}\'::jsonb\n WHEN v->\'controller_profile\'=\'"mineagent.rdagent-orchestrator.v3"\'::jsonb\n THEN jsonb_build_object(\'controller_profile\',\'mineagent.rdagent-orchestrator.v3\')\n ELSE NULL END\n$$;\nCREATE OR REPLACE FUNCTION @SCHEMA@.mineagent_rd_controller_profile_matches(v jsonb, profile text) RETURNS boolean\nLANGUAGE sql IMMUTABLE SET search_path=@SCHEMA@,pg_catalog AS $$\n SELECT (jsonb_typeof(v)=\'object\' AND CASE WHEN v ? \'controller_profile\' THEN\n   v->\'controller_profile\'=\'"mineagent.rdagent-orchestrator.v3"\'::jsonb\n   AND profile=\'mineagent.rdagent-orchestrator.v3\'\n ELSE profile IN (\'mineagent.rdagent-orchestrator.v1\',\'mineagent.rdagent-orchestrator.v2\') END) IS TRUE\n$$;\nCREATE OR REPLACE FUNCTION @SCHEMA@.mineagent_rd_provider_config(v jsonb) RETURNS boolean\nLANGUAGE plpgsql IMMUTABLE SET search_path=@SCHEMA@,pg_catalog AS $$\nBEGIN\n IF NOT (v ? \'controller_profile\') THEN RETURN mineagent_rd_provider_config_026_frozen(v); END IF;\n RETURN (mineagent_rd_controller_selection(v) IS NOT NULL\n  AND mineagent_rd_json_bytes(v,true)<=1048576\n  AND mineagent_rd_provider_config_026_frozen(v-\'controller_profile\') IS TRUE\n  AND v->>\'max_iterations\'=\'1\'\n  AND (v#>>\'{budget,wall_milliseconds}\')::numeric>=300000+32*(v#>>\'{model_binding,request_deadline_ms}\')::numeric) IS TRUE;\nEXCEPTION WHEN OTHERS THEN RETURN false;\nEND $$;\nCREATE OR REPLACE FUNCTION @SCHEMA@.mineagent_rd_source_config(v jsonb) RETURNS boolean\nLANGUAGE plpgsql IMMUTABLE SET search_path=@SCHEMA@,pg_catalog AS $$\nBEGIN\n IF v->>\'schema_version\'=\'mineagent.factor-research.v2\' THEN RETURN mineagent_rd_provider_config(v); END IF;\n IF NOT (v ? \'controller_profile\') THEN RETURN mineagent_rd_fixture_config_026(v); END IF;\n RETURN (mineagent_rd_controller_selection(v) IS NOT NULL\n  AND mineagent_rd_json_bytes(v,true)<=1048576\n  AND mineagent_rd_fixture_config_026(v-\'controller_profile\') IS TRUE\n  AND v->>\'max_iterations\'=\'1\'\n  AND (v#>>\'{budget,wall_milliseconds}\')::numeric>=300000) IS TRUE;\nEXCEPTION WHEN OTHERS THEN RETURN false;\nEND $$;\nCREATE OR REPLACE FUNCTION @SCHEMA@.mineagent_rd_shared_consistent() RETURNS trigger\nLANGUAGE plpgsql SET search_path=@SCHEMA@,pg_catalog AS $$\nDECLARE owner_uuid uuid; r record; spec record; b record; cl record; pa record; ab record; expected jsonb;\nBEGIN\n owner_uuid:=(CASE WHEN TG_OP=\'DELETE\' THEN OLD.owner_id ELSE NEW.owner_id END);\n IF EXISTS(SELECT 1 FROM research_model_operations op JOIN research_runs rr ON rr.id=op.run_id\n   JOIN research_operation_contexts cx ON cx.id=op.context_id\n   WHERE op.owner_id=owner_uuid AND (\n    (rr.engine=\'legacy\' AND (op.protocol<>\'mineagent.neutral-model.v1\' OR cx.context->>\'schema_version\'<>\'mineagent.neutral-fixture-context.v1\'))\n    OR (rr.engine=\'rdagent\' AND ((CASE WHEN rr.config->>\'schema_version\'=\'mineagent.factor-research.v2\' THEN op.protocol NOT IN (\'mineagent.rdagent-provider-chat.v1\',\'mineagent.rdagent-provider-embedding.v1\') ELSE op.protocol NOT IN (\'mineagent.rdagent-chat.v1\',\'mineagent.rdagent-embedding.v1\') END) OR cx.context->>\'schema_version\'<>\'mineagent.rdagent-context.v1\'\n       OR mineagent_rd_source_request(op.request,op.protocol) IS NOT TRUE\n       OR op.request_sha256<>encode(sha256(convert_to(mineagent_rd_canonical_json(op.request,false),\'UTF8\')),\'hex\')))\n    OR (rr.engine=\'openevolve\' AND (op.protocol<>\'mineagent.openevolve-chat.v1\'\n       OR mineagent_oe_request(op.request,op.protocol) IS NOT TRUE\n       OR mineagent_oe_context(cx.context) IS NOT TRUE\n       OR op.request_sha256 IS DISTINCT FROM encode(sha256(convert_to(mineagent_rd_canonical_json(op.request,false),\'UTF8\')),\'hex\')))))\n THEN RAISE EXCEPTION \'Run/context/model protocol disagreement\'; END IF;\n IF EXISTS(SELECT 1 FROM research_operation_contexts cx JOIN research_runs rr ON rr.id=cx.run_id\n   WHERE cx.owner_id=owner_uuid AND ((rr.engine=\'legacy\' AND cx.context->>\'schema_version\'<>\'mineagent.neutral-fixture-context.v1\')\n    OR (rr.engine=\'rdagent\' AND mineagent_rd_source_context(cx.context) IS NOT TRUE)\n    OR (rr.engine=\'openevolve\' AND (mineagent_oe_context(cx.context) IS NOT TRUE\n       OR cx.context->>\'owner_id\' IS DISTINCT FROM cx.owner_id::text\n       OR cx.context->>\'run_id\' IS DISTINCT FROM cx.run_id::text\n       OR cx.context_sha256 IS DISTINCT FROM encode(sha256(convert_to(mineagent_rd_canonical_json(cx.context,false),\'UTF8\')),\'hex\')))))\n THEN RAISE EXCEPTION \'Run/context version disagreement\'; END IF;\n IF EXISTS(SELECT 1 FROM factor_generation_model_operations m JOIN research_model_operations op ON op.id=m.operation_id\n   WHERE m.owner_id=owner_uuid AND (m.protocol<>op.protocol OR m.context_id<>op.context_id))\n THEN RAISE EXCEPTION \'RD request membership differs from exact protocol\'; END IF;\n IF EXISTS(SELECT 1 FROM research_budget_reservations br JOIN research_runs rr ON rr.id=br.run_id\n   WHERE br.owner_id=owner_uuid AND br.purpose=\'engine_mutation\' AND\n    (br.amounts IS DISTINCT FROM \'{"calls":0,"tokens":0,"cost_microunits":0,"wall_milliseconds":0,"storage_bytes":0,"mutation_slots":1,"evaluator_executions":0,"process_slots":0}\'::jsonb\n     OR NOT ((rr.engine=\'rdagent\' AND EXISTS(\n       SELECT 1 FROM factor_generation_starts st WHERE st.mutation_reservation_id=br.id\n       AND (st.owner_id,st.run_id,st.attempt_id,st.generation)=(br.owner_id,br.run_id,br.attempt_id,br.generation)))\n       OR (rr.engine=\'openevolve\' AND EXISTS(\n       SELECT 1 FROM search_iteration_intents st WHERE st.mutation_reservation_id=br.id\n       AND (st.owner_id,st.run_id,st.attempt_id,st.generation)=(br.owner_id,br.run_id,br.attempt_id,br.generation))))))\n THEN RAISE EXCEPTION \'RD mutation slot requires exact start consumer\'; END IF;\n IF EXISTS(SELECT 1 FROM research_object_publications p JOIN research_runs rr ON rr.id=p.run_id\n   WHERE p.owner_id=owner_uuid AND p.object_kind=\'factor_response_assembly\' AND rr.engine<>\'rdagent\')\n THEN RAISE EXCEPTION \'RD assembly publication cannot use legacy run\'; END IF;\n FOR r IN SELECT * FROM research_runs WHERE owner_id=owner_uuid AND engine=\'rdagent\' LOOP\n  SELECT * INTO spec FROM factor_research_specs WHERE run_id=r.id;\n  IF NOT FOUND OR spec.owner_id<>r.owner_id OR spec.config<>r.config\n   OR spec.config_sha256<>r.request_sha256 OR spec.input_sha256<>encode(sha256(convert_to(mineagent_rd_canonical_json(r.config->\'input\',true),\'UTF8\')),\'hex\')\n  THEN RAISE EXCEPTION \'RD immutable spec/run agreement\'; END IF;\n  SELECT * INTO b FROM research_budget_controls WHERE run_id=r.id;\n  IF NOT FOUND OR b.owner_id<>r.owner_id OR b.limits<>r.config->\'budget\'\n  THEN RAISE EXCEPTION \'RD immutable global budget differs\'; END IF;\n  IF EXISTS(SELECT 1 FROM research_operation_contexts cx WHERE cx.run_id=r.id AND\n    (cx.context->>\'spec_sha256\'<>spec.config_sha256 OR cx.context->>\'input_sha256\'<>spec.input_sha256\n     OR (cx.context->>\'logical_step\')::integer >= (r.config->>\'max_iterations\')::integer\n     OR cx.context_sha256<>encode(sha256(convert_to(mineagent_rd_canonical_json(cx.context,false),\'UTF8\')),\'hex\')))\n  THEN RAISE EXCEPTION \'RD context differs from frozen specification\'; END IF;\n END LOOP;\n FOR cl IN SELECT * FROM factor_controller_launches WHERE owner_id=owner_uuid LOOP\n  SELECT * INTO ab FROM factor_research_attempt_bindings WHERE id=cl.attempt_binding_id;\n  SELECT * INTO spec FROM factor_research_specs WHERE id=ab.spec_id;\n  SELECT * INTO pa FROM research_process_admissions WHERE id=cl.admission_id;\n  expected:=jsonb_build_object(\'schema_version\',\'mineagent.rdagent-operational-bootstrap.v1\',\n   \'owner_id\',cl.owner_id,\'run_id\',cl.run_id,\'attempt_id\',cl.attempt_id,\'generation\',cl.generation,\n   \'spec_id\',spec.id,\'attempt_binding_id\',ab.id,\'config\',spec.config,\'config_sha256\',spec.config_sha256,\n   \'input_sha256\',spec.input_sha256,\'continuation\',\'fresh_only\',\'input_layout\',\'single_bootstrap_json_no_other_mounts\');\n\n  IF spec.config->>\'schema_version\'=\'mineagent.factor-research.v2\' THEN\n   expected:=expected || jsonb_build_object(\'schema_version\',\'mineagent.rdagent-provider-operational-bootstrap.v1\');\n   IF (pa.profile IS NULL OR pa.profile NOT IN (\'mineagent.rdagent-orchestrator.v2\',\'mineagent.rdagent-orchestrator.v3\'))\n   THEN RAISE EXCEPTION \'Configured provider controller requires protected exact profile\'; END IF;\n  END IF;\n  IF EXISTS(SELECT 1 FROM factor_seeded_submissions WHERE run_id=cl.run_id) THEN\n   SELECT expected || jsonb_build_object(\n    \'schema_version\',(CASE WHEN spec.config->>\'schema_version\'=\'mineagent.factor-research.v2\' THEN \'mineagent.rdagent-provider-seeded-bootstrap.v1\' ELSE \'mineagent.rdagent-seeded-operational-bootstrap.v1\' END),\n    \'continuation\',\'seed_parent_first_generation\',\'seeded_submission_id\',s.id,\n    \'seed\',jsonb_build_object(\'reference\',mineagent_rd_seed_reference(s.id),\n      \'definition\',v.definition,\'source\',v.code)) INTO expected\n   FROM factor_seeded_submissions s JOIN factor_versions v ON v.id=s.parent_factor_version_id\n   WHERE s.run_id=cl.run_id AND s.owner_id=cl.owner_id;\n   IF (pa.profile IS NULL OR pa.profile NOT IN (\'mineagent.rdagent-orchestrator.v2\',\'mineagent.rdagent-orchestrator.v3\'))\n   THEN RAISE EXCEPTION \'Seeded controller requires protected exact profile\'; END IF;\n  END IF;\n  IF ab.resumed_checkpoint_id IS NOT NULL OR cl.bootstrap IS DISTINCT FROM expected\n   OR cl.bootstrap_sha256<>encode(sha256(convert_to(mineagent_rd_canonical_json(expected,true),\'UTF8\')),\'hex\')\n   OR (pa.schema_version,pa.ipc_policy,pa.role,pa.logical_operation_id,pa.input_sha256,pa.image_id)\n     IS DISTINCT FROM (\'mineagent.process-admission.v2\'::varchar,\'host_ticket\'::varchar,\'rd_orchestrator\'::varchar,ab.id,cl.bootstrap_sha256,spec.config->\'runtime\'->>\'orchestrator_image\')\n   OR pa.profile NOT IN (\'mineagent.rdagent-orchestrator.v1\',\'mineagent.rdagent-orchestrator.v2\',\'mineagent.rdagent-orchestrator.v3\')\n  THEN RAISE EXCEPTION \'RD controller persistence binding differs\'; END IF;\n END LOOP;\n\n IF EXISTS(SELECT 1 FROM research_object_publications p JOIN research_runs rr ON rr.id=p.run_id\n   WHERE p.owner_id=owner_uuid AND p.object_kind IN (\'search_checkpoint_chunk\',\'search_checkpoint_file\',\'search_checkpoint_inventory\',\'search_evaluation_input\',\'search_source\',\'search_rendered_prompt\',\'search_proposal_source\',\'search_checkpoint_closure\',\'search_worker_identity\',\'search_population\',\'search_context\',\'search_controller_event\',\'search_worker_outcome\',\'search_native_observation\',\'search_native_failure\',\'search_objective\') AND rr.engine<>\'openevolve\')\n THEN RAISE EXCEPTION \'OE object publication requires exact search run\'; END IF;\n FOR r IN SELECT * FROM research_runs WHERE owner_id=owner_uuid AND engine=\'openevolve\' LOOP\n  SELECT * INTO spec FROM strategy_search_specs WHERE run_id=r.id;\n  IF NOT FOUND OR spec.owner_id IS DISTINCT FROM r.owner_id OR spec.spec IS DISTINCT FROM r.config\n   OR spec.spec_sha256 IS DISTINCT FROM r.request_sha256\n   OR spec.spec_sha256 IS DISTINCT FROM encode(sha256(convert_to(mineagent_rd_canonical_json(spec.spec,false),\'UTF8\')),\'hex\')\n   OR (spec.original_strategy_id::text,spec.original_source_sha256,spec.prepared_strategy_id::text,spec.prepared_source_sha256,\n       spec.dataset_id::text,spec.dataset_sha256)\n   IS DISTINCT FROM (r.config#>>\'{preparation,original,strategy_version_id}\',r.config#>>\'{preparation,original,source_sha256}\',\n       r.config#>>\'{preparation,prepared,strategy_version_id}\',r.config#>>\'{preparation,prepared,source_sha256}\',\n       r.config#>>\'{execution,dataset_version_id}\',r.config#>>\'{execution,dataset_sha256}\')\n   OR spec.objective_sha256 IS DISTINCT FROM encode(sha256(convert_to(mineagent_rd_canonical_json(r.config->\'objective\',false),\'UTF8\')),\'hex\')\n   OR spec.execution_sha256 IS DISTINCT FROM encode(sha256(convert_to(mineagent_rd_canonical_json(r.config->\'execution\',false),\'UTF8\')),\'hex\')\n  THEN RAISE EXCEPTION \'OE immutable spec/run agreement\'; END IF;\n  SELECT * INTO b FROM research_budget_controls WHERE run_id=r.id;\n  IF NOT FOUND OR b.owner_id IS DISTINCT FROM r.owner_id OR b.limits IS DISTINCT FROM r.config->\'budget\'\n  THEN RAISE EXCEPTION \'OE immutable global budget differs\'; END IF;\n END LOOP;\n\n RETURN NULL;\nEND $$;\nCREATE OR REPLACE FUNCTION @SCHEMA@.mineagent_rd_controller_receipt_order() RETURNS trigger\nLANGUAGE plpgsql SET search_path=@SCHEMA@,pg_catalog AS $$\nDECLARE a record; protected boolean;\nBEGIN\n SELECT * INTO STRICT a FROM research_process_admissions WHERE id=NEW.admission_id;\n protected:=((a.profile IN (\'mineagent.rdagent-orchestrator.v2\',\'mineagent.rdagent-orchestrator.v3\') AND a.role=\'rd_orchestrator\') OR\n   (a.profile=\'mineagent.openevolve-orchestrator.v1\' AND a.role=\'openevolve_orchestrator\'\n    AND a.schema_version=\'mineagent.process-admission.v2\' AND a.ipc_policy=\'host_ticket\'\n    AND a.ticket_sha256 ~ \'^[a-f0-9]{64}$\')) IS TRUE;\n IF NEW.kind=\'controller_child\' AND NOT protected\n THEN RAISE EXCEPTION \'Child receipt requires exact protected controller\'; END IF;\n IF NOT protected THEN RETURN NEW; END IF;\n IF NEW.kind NOT IN (\'launch_intent\',\'launch_identity\',\'controller_child\',\'stop\')\n THEN RAISE EXCEPTION \'Protected controller cannot publish extraction\'; END IF;\n IF EXISTS(SELECT 1 FROM research_process_receipts WHERE admission_id=a.id AND kind=\'stop\')\n THEN RAISE EXCEPTION \'Stopped controller receipt chain is closed\'; END IF;\n IF NEW.kind<>\'launch_intent\' AND NOT EXISTS(SELECT 1 FROM research_process_receipts WHERE admission_id=a.id AND kind=\'launch_intent\')\n THEN RAISE EXCEPTION \'Controller intent must precede physical identity\'; END IF;\n IF NEW.kind IN (\'controller_child\',\'stop\') AND NOT EXISTS(SELECT 1 FROM research_process_receipts WHERE admission_id=a.id AND kind=\'launch_identity\')\n THEN RAISE EXCEPTION \'Protected leader identity must precede child or stop\'; END IF;\n RETURN NEW;\nEND $$;\nCREATE OR REPLACE FUNCTION @SCHEMA@.mineagent_rd_controller_consistent() RETURNS trigger\nLANGUAGE plpgsql SET search_path=@SCHEMA@,pg_catalog AS $$\nDECLARE owner_uuid uuid; a record; rr record; br record; bs record; ps record;\n sp record; ab record; cl record; p record; intent jsonb; ident jsonb; child jsonb; stopped jsonb;\n decl jsonb; launch jsonb; expected_bootstrap jsonb; report jsonb; n integer;\n intent_hash text; identity_hash text; child_hash text; launch_hash text;\nBEGIN\n owner_uuid:=(CASE WHEN TG_OP=\'DELETE\' THEN OLD.owner_id ELSE NEW.owner_id END);\n IF EXISTS(SELECT 1 FROM research_process_receipts child_receipt JOIN research_process_admissions child_admission ON child_admission.id=child_receipt.admission_id\n WHERE child_receipt.owner_id=owner_uuid AND child_receipt.kind=\'controller_child\' AND\n  NOT ((child_admission.profile IN (\'mineagent.rdagent-orchestrator.v2\',\'mineagent.rdagent-orchestrator.v3\') AND child_admission.role=\'rd_orchestrator\')\n       OR (child_admission.profile=\'mineagent.openevolve-orchestrator.v1\' AND child_admission.role=\'openevolve_orchestrator\'\n           AND child_admission.schema_version=\'mineagent.process-admission.v2\' AND child_admission.ipc_policy=\'host_ticket\'\n           AND child_admission.ticket_sha256 ~ \'^[a-f0-9]{64}$\')))\n THEN RAISE EXCEPTION \'RD child cannot extend historical process grammar\'; END IF;\n FOR a IN SELECT * FROM research_process_admissions WHERE owner_id=owner_uuid AND profile IN (\'mineagent.rdagent-orchestrator.v2\',\'mineagent.rdagent-orchestrator.v3\') LOOP\n  IF (a.schema_version,a.role,a.ipc_policy) IS DISTINCT FROM\n    (\'mineagent.process-admission.v2\'::varchar,\'rd_orchestrator\'::varchar,\'host_ticket\'::varchar)\n    OR a.ticket_sha256 IS NULL OR a.ticket_sha256 !~ \'^[a-f0-9]{64}$\'\n  THEN RAISE EXCEPTION \'Exact RD controller declaration required\'; END IF;\n  SELECT * INTO rr FROM research_runs WHERE id=a.run_id AND owner_id=a.owner_id;\n  IF NOT FOUND OR rr.engine<>\'rdagent\' OR rr.purpose<>\'factor_research\'\n  THEN RAISE EXCEPTION \'RD controller requires genuine RD run\'; END IF;\n  SELECT * INTO sp FROM factor_research_specs WHERE run_id=a.run_id AND owner_id=a.owner_id;\n  IF NOT FOUND OR sp.config<>rr.config OR sp.config_sha256<>rr.request_sha256\n  THEN RAISE EXCEPTION \'Controller immutable spec missing\'; END IF;\n  SELECT * INTO ab FROM factor_research_attempt_bindings WHERE id=a.logical_operation_id\n   AND (owner_id,run_id,attempt_id,generation)=(a.owner_id,a.run_id,a.attempt_id,a.generation);\n  IF NOT FOUND OR ab.spec_id<>sp.id OR ab.resumed_checkpoint_id IS NOT NULL\n  THEN RAISE EXCEPTION \'Controller attempt binding differs\'; END IF;\n  SELECT * INTO cl FROM factor_controller_launches WHERE admission_id=a.id\n   AND (owner_id,run_id,attempt_id,generation)=(a.owner_id,a.run_id,a.attempt_id,a.generation);\n  IF NOT FOUND OR cl.attempt_binding_id<>ab.id THEN RAISE EXCEPTION \'Controller launch domain binding missing\'; END IF;\n  expected_bootstrap:=jsonb_build_object(\'schema_version\',\'mineagent.rdagent-operational-bootstrap.v1\',\n   \'owner_id\',a.owner_id,\'run_id\',a.run_id,\'attempt_id\',a.attempt_id,\'generation\',a.generation,\n   \'spec_id\',sp.id,\'attempt_binding_id\',ab.id,\'config\',sp.config,\'config_sha256\',sp.config_sha256,\n   \'input_sha256\',sp.input_sha256,\'continuation\',\'fresh_only\',\'input_layout\',\'single_bootstrap_json_no_other_mounts\');\n\n  IF sp.config->>\'schema_version\'=\'mineagent.factor-research.v2\' THEN\n   expected_bootstrap:=expected_bootstrap || jsonb_build_object(\'schema_version\',\'mineagent.rdagent-provider-operational-bootstrap.v1\');\n   IF (a.profile IS NULL OR a.profile NOT IN (\'mineagent.rdagent-orchestrator.v2\',\'mineagent.rdagent-orchestrator.v3\'))\n   THEN RAISE EXCEPTION \'Configured provider controller requires protected exact profile\'; END IF;\n  END IF;\n  IF EXISTS(SELECT 1 FROM factor_seeded_submissions WHERE run_id=cl.run_id) THEN\n   SELECT expected_bootstrap || jsonb_build_object(\n    \'schema_version\',(CASE WHEN sp.config->>\'schema_version\'=\'mineagent.factor-research.v2\' THEN \'mineagent.rdagent-provider-seeded-bootstrap.v1\' ELSE \'mineagent.rdagent-seeded-operational-bootstrap.v1\' END),\n    \'continuation\',\'seed_parent_first_generation\',\'seeded_submission_id\',s.id,\n    \'seed\',jsonb_build_object(\'reference\',mineagent_rd_seed_reference(s.id),\n      \'definition\',v.definition,\'source\',v.code)) INTO expected_bootstrap\n   FROM factor_seeded_submissions s JOIN factor_versions v ON v.id=s.parent_factor_version_id\n   WHERE s.run_id=cl.run_id AND s.owner_id=cl.owner_id;\n   IF (a.profile IS NULL OR a.profile NOT IN (\'mineagent.rdagent-orchestrator.v2\',\'mineagent.rdagent-orchestrator.v3\'))\n   THEN RAISE EXCEPTION \'Seeded controller requires protected exact profile\'; END IF;\n  END IF;\n  IF cl.bootstrap<>expected_bootstrap OR cl.bootstrap_sha256<>a.input_sha256\n   OR a.input_sha256<>encode(sha256(convert_to(@SCHEMA@.mineagent_rd_canonical_json(expected_bootstrap,true),\'UTF8\')),\'hex\')\n   OR a.image_id<>sp.config->\'runtime\'->>\'orchestrator_image\'\n  THEN RAISE EXCEPTION \'Controller bootstrap/image commitment differs\'; END IF;\n  SELECT * INTO br FROM research_budget_reservations WHERE id=a.reservation_id;\n  IF NOT FOUND OR (br.owner_id,br.run_id,br.attempt_id,br.generation) IS DISTINCT FROM\n    (a.owner_id,a.run_id,a.attempt_id,a.generation) OR br.purpose<>\'process_unit\'\n    OR (br.amounts->>\'process_slots\')::numeric<>1 OR (br.amounts->>\'wall_milliseconds\')::numeric < (CASE WHEN a.profile=\'mineagent.rdagent-orchestrator.v3\' THEN 120000 ELSE 60000 END)\n    OR (br.amounts->>\'storage_bytes\')::numeric<67174400\n    OR br.amounts->>\'calls\'<>\'0\' OR br.amounts->>\'tokens\'<>\'0\'\n    OR br.amounts->>\'mutation_slots\'<>\'0\' OR br.amounts->>\'evaluator_executions\'<>\'0\'\n  THEN RAISE EXCEPTION \'Controller physical reservation floor/scope differs\'; END IF;\n  SELECT * INTO ps FROM research_process_states WHERE admission_id=a.id;\n  IF NOT FOUND OR (ps.owner_id,ps.run_id,ps.attempt_id,ps.generation) IS DISTINCT FROM\n    (a.owner_id,a.run_id,a.attempt_id,a.generation) OR ps.status NOT IN (\'launch_intended\',\'running\',\'uncertain\',\'stopped\')\n  THEN RAISE EXCEPTION \'Controller projection differs\'; END IF;\n  intent:=NULL;ident:=NULL;child:=NULL;stopped:=NULL;\n  FOR p IN SELECT * FROM research_process_receipts WHERE admission_id=a.id LOOP\n   IF (p.owner_id,p.run_id,p.attempt_id,p.generation) IS DISTINCT FROM\n      (a.owner_id,a.run_id,a.attempt_id,a.generation)\n    OR @SCHEMA@.mineagent_rd_controller_payload(p.kind,p.payload) IS NOT TRUE\n    OR p.payload_sha256<>encode(sha256(convert_to(@SCHEMA@.mineagent_rd_canonical_json(p.payload,true),\'UTF8\')),\'hex\')\n   THEN RAISE EXCEPTION \'Exact controller receipt grammar/hash required\'; END IF;\n   CASE p.kind WHEN \'launch_intent\' THEN intent:=p.payload;\n    WHEN \'launch_identity\' THEN ident:=p.payload;\n    WHEN \'controller_child\' THEN child:=p.payload;\n    WHEN \'stop\' THEN stopped:=p.payload;\n    ELSE RAISE EXCEPTION \'Unexpected controller receipt\'; END CASE;\n  END LOOP;\n  IF intent IS NULL THEN RAISE EXCEPTION \'Controller launch intent required\'; END IF;\n  decl:=jsonb_build_object(\'schema_version\',a.schema_version,\'id\',a.id,\'owner_id\',a.owner_id,\n   \'run_id\',a.run_id,\'attempt_id\',a.attempt_id,\'generation\',a.generation,\'role\',a.role,\n   \'logical_operation_id\',a.logical_operation_id,\'launch_ordinal\',a.launch_ordinal,\'profile\',a.profile,\n   \'input_sha256\',a.input_sha256,\'reservation_id\',a.reservation_id,\'image_id\',a.image_id,\n   \'ipc\',jsonb_build_object(\'ipc_policy\',\'host_ticket\',\'ticket_sha256\',a.ticket_sha256));\n  IF intent->\'admission\'<>decl OR intent->>\'bootstrap_sha256\'<>a.input_sha256\n   OR (intent->>\'bootstrap_size_bytes\')::integer<>octet_length(convert_to(@SCHEMA@.mineagent_rd_canonical_json(expected_bootstrap,true),\'UTF8\'))\n   OR (intent->>\'not_after\')::timestamptz <= (intent->>\'issued_at\')::timestamptz\n   OR (intent->>\'not_after\')::timestamptz-(intent->>\'issued_at\')::timestamptz> (CASE WHEN a.profile=\'mineagent.rdagent-orchestrator.v3\' THEN interval \'120 seconds\' ELSE interval \'60 seconds\' END)\n  THEN RAISE EXCEPTION \'Controller immutable intent differs\'; END IF;\n  IF ps.status IN (\'running\',\'stopped\') AND ident IS NULL THEN RAISE EXCEPTION \'Controller leader required\'; END IF;\n  IF (stopped IS NOT NULL) IS DISTINCT FROM (ps.status=\'stopped\') THEN RAISE EXCEPTION \'Controller stopped projection differs\'; END IF;\n  IF ident IS NULL AND (child IS NOT NULL OR stopped IS NOT NULL) THEN RAISE EXCEPTION \'Controller leader predecessor missing\'; END IF;\n  IF ident IS NOT NULL THEN\n   launch:=jsonb_build_object(\'schema_version\',\'mineagent.rd-controller-launch.v1\',\'intent\',intent,\n    \'runtime_name\',\'mineagent-rd-controller-\'||a.id::text,\'root_device\',ident->\'root_device\',\'root_inode\',ident->\'root_inode\');\n   launch_hash:=encode(sha256(convert_to(@SCHEMA@.mineagent_rd_canonical_json(launch,true),\'UTF8\')),\'hex\');\n   identity_hash:=encode(sha256(convert_to(@SCHEMA@.mineagent_rd_canonical_json(ident,true),\'UTF8\')),\'hex\');\n   IF ident->>\'launch_sha256\'<>launch_hash OR ident->>\'image_id\'<>a.image_id\n    OR ident->>\'admission_sha256\'<>encode(sha256(convert_to(@SCHEMA@.mineagent_rd_canonical_json(decl,true),\'UTF8\')),\'hex\')\n    OR @SCHEMA@.mineagent_rd_controller_kernel(ident->\'leader\',0) IS NOT TRUE\n   THEN RAISE EXCEPTION \'Protected leader physical identity differs\'; END IF;\n  END IF;\n  child_hash:=NULL;\n  IF child IS NOT NULL THEN\n   n:=jsonb_array_length(child->\'namespace_pids\');\n   IF child->>\'identity_sha256\'<>identity_hash OR child->>\'admission_sha256\'<>ident->>\'admission_sha256\'\n    OR @SCHEMA@.mineagent_rd_controller_kernel(child->\'controller\',65533) IS NOT TRUE\n    OR child->\'controller\'->\'ppid\'<>ident->\'leader\'->\'host_pid\'\n    OR child->\'controller\'->\'host_pid\'=ident->\'leader\'->\'host_pid\'\n    OR child->\'controller\'->\'pid_namespace\'<>ident->\'leader\'->\'pid_namespace\'\n    OR child->\'controller\'->\'cgroup\'<>ident->\'leader\'->\'cgroup\'\n    OR child->\'peer_pid\'<>child->\'controller\'->\'host_pid\'\n    OR child->\'namespace_pids\'->0<>child->\'controller\'->\'host_pid\'\n    OR child->\'namespace_pids\'->(n-1)<>child->\'namespace_pid\'\n    OR EXISTS(SELECT 1 FROM jsonb_array_elements(child->\'namespace_pids\') x WHERE (x.value::text)::numeric<=0)\n   THEN RAISE EXCEPTION \'Exact trusted child/peer/NSpid identity differs\'; END IF;\n   report:=jsonb_build_object(\'schema\',\'mineagent.rdagent-controller-report.v1\',\'event\',\'started\',\n    \'child_namespace_pid\',child->\'namespace_pid\',\'child_start_ticks\',child->\'controller\'->\'start_ticks\');\n   IF child->>\'started_report_sha256\'<>encode(sha256(convert_to(@SCHEMA@.mineagent_rd_canonical_json(report,true)||E\'\\n\',\'UTF8\')),\'hex\')\n   THEN RAISE EXCEPTION \'Trusted startup frame commitment differs\'; END IF;\n   child_hash:=encode(sha256(convert_to(@SCHEMA@.mineagent_rd_canonical_json(child,true),\'UTF8\')),\'hex\');\n  END IF;\n  IF stopped IS NOT NULL AND (stopped->>\'launch_sha256\'<>launch_hash\n    OR stopped->>\'identity_sha256\'<>identity_hash OR stopped->>\'container_id\'<>ident->>\'container_id\'\n    OR (stopped->>\'child_sha256\') IS DISTINCT FROM child_hash\n    OR (stopped->\'child_kernel_identity_absent\') IS DISTINCT FROM (CASE WHEN child IS NULL THEN \'null\'::jsonb ELSE \'true\'::jsonb END))\n  THEN RAISE EXCEPTION \'Controller positive stop metadata differs\'; END IF;\n  SELECT * INTO bs FROM research_budget_settlements WHERE reservation_id=br.id;\n  IF br.state=\'settled\' THEN\n   IF NOT FOUND OR stopped IS NULL OR bs.outcome<>\'conservative_unknown\'\n    OR bs.charge IS DISTINCT FROM br.amounts\n    OR (bs.owner_id,bs.run_id,bs.attempt_id,bs.generation) IS DISTINCT FROM\n      (a.owner_id,a.run_id,a.attempt_id,a.generation)\n   THEN RAISE EXCEPTION \'Controller settlement requires stopped full conservative charge\'; END IF;\n  ELSIF FOUND OR br.state NOT IN (\'reserved\',\'uncertain\') THEN RAISE EXCEPTION \'Controller unresolved budget must remain held\'; END IF;\n END LOOP;\n RETURN NULL;\nEND $$;\nCREATE OR REPLACE FUNCTION mineagent_rd_operational_actor() RETURNS trigger LANGUAGE plpgsql SET search_path=@SCHEMA@,pg_catalog AS $$\nDECLARE admission_uuid uuid;\nBEGIN\n SELECT cl.admission_id INTO admission_uuid FROM factor_controller_launches cl\n JOIN research_process_admissions p ON p.id=cl.admission_id\n JOIN research_process_states s ON s.admission_id=p.id\n WHERE cl.id=NEW.controller_launch_id\n AND (cl.owner_id,cl.run_id,cl.attempt_id,cl.generation)=(NEW.owner_id,NEW.run_id,NEW.attempt_id,NEW.generation)\n AND p.profile IN (\'mineagent.rdagent-orchestrator.v2\',\'mineagent.rdagent-orchestrator.v3\') AND s.status=\'running\'\n AND EXISTS(SELECT 1 FROM research_process_receipts r WHERE r.admission_id=p.id AND r.kind=\'controller_child\');\n IF admission_uuid IS NULL THEN RAISE EXCEPTION \'Current protected controller required\'; END IF;\n RETURN NEW;\nEND $$;\nCREATE OR REPLACE FUNCTION mineagent_rd_operational_boundary_consistent() RETURNS trigger LANGUAGE plpgsql SET search_path=@SCHEMA@,pg_catalog AS $$\nDECLARE owner_uuid uuid; o record; st record; src record; cl record; expected jsonb; c record; co record; members jsonb; outcomes jsonb; count_members integer;\nBEGIN\n owner_uuid:=CASE WHEN TG_OP=\'DELETE\' THEN OLD.owner_id ELSE NEW.owner_id END;\n IF EXISTS(SELECT 1 FROM factor_generation_sources source\n JOIN factor_source_read_witnesses w ON w.source_id=source.id\n JOIN factor_controller_launches launch ON launch.id=w.controller_launch_id\n JOIN research_process_admissions p ON p.id=launch.admission_id\n WHERE source.owner_id=owner_uuid AND p.profile IN (\'mineagent.rdagent-orchestrator.v2\',\'mineagent.rdagent-orchestrator.v3\')\n AND NOT EXISTS(SELECT 1 FROM research_process_receipts r WHERE r.admission_id=p.id AND r.kind=\'controller_child\'))\n THEN RAISE EXCEPTION \'Operational source requires retained child identity\'; END IF;\n FOR o IN SELECT * FROM factor_generation_observations WHERE owner_id=owner_uuid LOOP\n  SELECT * INTO st FROM factor_generation_starts WHERE id=o.start_id;\n  SELECT * INTO src FROM factor_generation_sources WHERE start_id=st.id;\n  SELECT * INTO cl FROM factor_controller_launches WHERE id=o.controller_launch_id;\n  IF src.id IS NULL OR st.logical_step<>0 OR o.logical_step<>0\n   OR cl.bootstrap->\'config\'->>\'max_iterations\'<>\'1\'\n   OR (st.owner_id,st.run_id,st.attempt_id,st.generation) IS DISTINCT FROM (o.owner_id,o.run_id,o.attempt_id,o.generation)\n  THEN RAISE EXCEPTION \'Initial actual generation boundary required\'; END IF;\n  expected:=jsonb_build_object(\'schema_version\',\'mineagent.rdagent-adoption-observation.v1\',\'logical_step\',0,\n   \'evaluated_source_id\',src.id,\'previous_adopted_source_id\',NULL,\'adopted_source_id\',src.id,\n   \'continuation_source_id\',src.id,\'adopted_new\',true);\n  IF o.decision IS DISTINCT FROM expected OR o.decision_sha256<>encode(sha256(convert_to(mineagent_rd_canonical_json(expected,true),\'UTF8\')),\'hex\')\n  THEN RAISE EXCEPTION \'Exact first generation adoption required\'; END IF;\n  IF NOT EXISTS(SELECT 1 FROM factor_upstream_calls WHERE start_id=st.id AND phase=\'knowledge_update\' AND kind=\'embedding\')\n  THEN RAISE EXCEPTION \'Actual upstream knowledge boundary required\'; END IF;\n  FOR c IN SELECT * FROM factor_upstream_calls WHERE start_id=st.id LOOP\n   SELECT * INTO co FROM factor_upstream_call_outcomes WHERE call_id=c.id;\n   SELECT count(*),jsonb_agg(m.id::text ORDER BY m.request_ordinal),jsonb_agg(mo.id::text ORDER BY m.request_ordinal)\n    INTO count_members,members,outcomes FROM factor_generation_model_operations m\n    JOIN research_model_operations op ON op.id=m.operation_id AND op.state=\'completed\'\n    JOIN research_model_transports mt ON mt.operation_id=op.id AND mt.state=\'completed\'\n    JOIN research_model_outcomes mo ON mo.transport_id=mt.id AND mo.outcome=\'completed\'\n    WHERE m.call_id=c.id AND m.protocol=(CASE WHEN cl.bootstrap#>>\'{config,schema_version}\'=\'mineagent.factor-research.v2\'\n      THEN (CASE c.kind WHEN \'chat\' THEN \'mineagent.rdagent-provider-chat.v1\' ELSE \'mineagent.rdagent-provider-embedding.v1\' END)\n      ELSE (CASE c.kind WHEN \'chat\' THEN \'mineagent.rdagent-chat.v1\' ELSE \'mineagent.rdagent-embedding.v1\' END) END);\n   IF co.id IS NULL OR co.status<>\'completed\' OR co.controller_launch_id<>cl.id OR count_members<1\n    OR count_members<>(SELECT count(*) FROM factor_generation_model_operations WHERE call_id=c.id)\n    OR (SELECT min(request_ordinal) FROM factor_generation_model_operations WHERE call_id=c.id)<>0\n    OR (SELECT max(request_ordinal) FROM factor_generation_model_operations WHERE call_id=c.id)<>count_members-1\n    OR co.member_count<>count_members OR co.member_ids IS DISTINCT FROM members OR co.response_outcome_ids IS DISTINCT FROM outcomes\n   THEN RAISE EXCEPTION \'All actual model calls must close before adoption\'; END IF;\n  END LOOP;\n END LOOP;\n IF EXISTS(SELECT 1 FROM factor_generation_boundaries b JOIN factor_generation_observations boundary_observation ON boundary_observation.id=b.observation_id\n WHERE b.owner_id=owner_uuid AND (b.boundary<>\'returned\' OR b.next_logical_step IS NOT NULL\n  OR (b.start_id,b.controller_launch_id,b.logical_step) IS DISTINCT FROM (boundary_observation.start_id,boundary_observation.controller_launch_id,boundary_observation.logical_step)))\n THEN RAISE EXCEPTION \'Exact returned first generation boundary required\'; END IF;\n RETURN NULL;\nEND $$;\nCREATE OR REPLACE FUNCTION @SCHEMA@.mineagent_rd_execution_generation_actor() RETURNS trigger\nLANGUAGE plpgsql SET search_path=@SCHEMA@,pg_catalog AS $$\nBEGIN\n IF NEW.outcome<>\'accepted\' OR NOT EXISTS(\n SELECT 1 FROM factor_execution_evaluation_outcomes ev\n JOIN factor_generation_boundaries b ON b.id=ev.boundary_id\n JOIN factor_controller_launches cl ON cl.id=ev.controller_launch_id\n JOIN research_process_admissions p ON p.id=cl.admission_id\n JOIN research_process_states state ON state.admission_id=p.id\n WHERE (ev.owner_id,ev.run_id,ev.attempt_id,ev.generation,ev.generation_start_id)=\n       (NEW.owner_id,NEW.run_id,NEW.attempt_id,NEW.generation,NEW.start_id)\n AND b.start_id=NEW.start_id AND b.boundary=\'returned\'\n AND p.profile IN (\'mineagent.rdagent-orchestrator.v2\',\'mineagent.rdagent-orchestrator.v3\') AND state.status=\'running\'\n AND EXISTS(SELECT 1 FROM research_process_receipts r WHERE r.admission_id=p.id AND r.kind=\'controller_child\'))\n THEN RAISE EXCEPTION \'Accepted execution requires current protected actor and actual snapshot result\'; END IF;\n RETURN NEW;\nEND $$;\nCREATE OR REPLACE FUNCTION @SCHEMA@.mineagent_rd_provider_graph(rid uuid) RETURNS void\nLANGUAGE plpgsql SET search_path=@SCHEMA@,pg_catalog AS $$\nDECLARE op record; run record; t record; w record; held record; settlement record; outcome record; amount jsonb; selected jsonb; n integer; attempt record; must_be_stopped boolean; config_checked boolean:=false; config_valid boolean; steer_digest text; binding jsonb; binding_valid boolean; binding_digest text; request_valid boolean; request_digest text; request_utf8 text; request_ascii text; output_tokens bigint; cost numeric;\nBEGIN\n SELECT * INTO run FROM research_runs WHERE id=rid;\n IF (SELECT count(*) FROM research_model_operations WHERE run_id=rid AND protocol IN (\'mineagent.rdagent-provider-chat.v1\',\'mineagent.rdagent-provider-embedding.v1\'))>32\n THEN RAISE EXCEPTION \'Provider profile permits at most 32 operations per run\'; END IF;\n FOR op IN SELECT * FROM research_model_operations WHERE run_id=rid AND protocol IN (\'mineagent.rdagent-provider-chat.v1\',\'mineagent.rdagent-provider-embedding.v1\') LOOP\n  IF run.id IS NULL OR (run.purpose,run.engine) IS DISTINCT FROM (\'factor_research\',\'rdagent\')\n  OR run.owner_id IS DISTINCT FROM op.owner_id\n  THEN RAISE EXCEPTION \'Provider operation/config/request identity differs\'; END IF;\n  -- Function-local pure values from the single captured run record only.\n  -- Lazy first operation preserves the empty-run and 32-operation boundaries.\n  -- No relational evidence or result survives this function invocation.\n  IF NOT config_checked THEN\n   config_valid:=mineagent_rd_provider_config(run.config);\n   IF config_valid IS TRUE THEN\n    steer_digest:=encode(sha256(convert_to(mineagent_rd_canonical_json(run.config->\'steer_snapshot\',true),\'UTF8\')),\'hex\');\n   END IF;\n\n   binding:=run.config->\'model_binding\'; binding_valid:=false; binding_digest:=NULL;\n   BEGIN\n    binding_valid:=mineagent_rd_provider_payload(\'binding\',binding);\n    IF binding_valid IS TRUE THEN\n     binding_digest:=encode(sha256(convert_to(mineagent_rd_canonical_json(binding,true),\'UTF8\')),\'hex\');\n    END IF;\n   EXCEPTION WHEN OTHERS THEN binding_valid:=false; binding_digest:=NULL;\n   END;\n   config_checked:=true;\n  END IF;\n\n  request_valid:=false; request_digest:=NULL; amount:=NULL;\n  BEGIN\n   IF binding_valid IS TRUE\n   AND mineagent_rd_provider_payload(op.request->>\'kind\',op.request) IS TRUE THEN\n    request_utf8:=mineagent_rd_canonical_json(op.request,false);\n    request_ascii:=mineagent_rd_canonical_json(op.request,true);\n    request_valid:=COALESCE(\n      op.request->>\'schema_version\'=\'mineagent.rdagent-provider-\'||(op.request->>\'kind\')||\'.v1\'\n      AND op.request->>\'model_profile_id\'=binding->>\'profile_id\'\n      AND op.request->>\'model_binding_sha256\'=binding_digest\n      AND octet_length(request_utf8)<=262144\n      AND octet_length(request_ascii)<=(binding->>\'max_request_bytes\')::bigint\n      AND CASE WHEN op.request->>\'kind\'=\'chat\' THEN\n       op.request->>\'model\'=binding->>\'chat_model\'\n       AND (op.request->>\'max_output_tokens\')::bigint<=(binding->>\'max_output_tokens\')::bigint\n      ELSE op.request->>\'model\'=binding->>\'embedding_model\'\n       AND op.request->\'dimensions\'=binding->\'embedding_dimensions\'\n       AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(op.request->\'inputs\') value WHERE length(value) NOT BETWEEN 1 AND 8192)\n      END,false);\n    IF request_valid IS TRUE THEN\n     request_digest:=encode(sha256(convert_to(request_utf8,\'UTF8\')),\'hex\');\n    END IF;\n   END IF;\n  EXCEPTION WHEN OTHERS THEN request_valid:=false; request_digest:=NULL;\n  END;\n  IF request_valid IS TRUE THEN\n   BEGIN\n    IF binding->\'pricing\'->>\'status\'=\'operator_declared\' THEN\n     output_tokens:=0;\n     IF op.request->>\'kind\'=\'chat\' THEN\n      output_tokens:=(op.request->>\'max_output_tokens\')::bigint;\n      cost:=262144::numeric*(binding->\'pricing\'->>\'chat_input_microusd_per_million\')::numeric\n       +output_tokens::numeric*(binding->\'pricing\'->>\'chat_output_microusd_per_million\')::numeric;\n     ELSE cost:=262144::numeric*(binding->\'pricing\'->>\'embedding_microusd_per_million\')::numeric;\n     END IF;\n     amount:=jsonb_build_object(\'calls\',1,\'tokens\',262144+output_tokens,\n      \'cost_microunits\',ceil(cost/1000000)::bigint,\'mutation_slots\',0,\'evaluator_executions\',0,\n      \'wall_milliseconds\',(binding->>\'request_deadline_ms\')::bigint,\'storage_bytes\',589824,\'process_slots\',1);\n    END IF;\n   EXCEPTION WHEN OTHERS THEN amount:=NULL;\n   END;\n  END IF;\n  IF config_valid IS NOT TRUE\n  OR run.config->\'steer_snapshot\'->>\'owner_id\' IS DISTINCT FROM op.owner_id::text\n  OR run.config->>\'steer_snapshot_sha256\' IS DISTINCT FROM steer_digest\n  OR request_valid IS NOT TRUE\n  OR op.protocol IS DISTINCT FROM op.request->>\'schema_version\'\n  OR op.request_sha256 IS DISTINCT FROM request_digest\n  THEN RAISE EXCEPTION \'Provider operation/config/request identity differs\'; END IF;\n  FOR selected IN SELECT value FROM jsonb_array_elements(run.config->\'steer_snapshot\'->\'versions\') LOOP\n   IF NOT EXISTS(SELECT 1 FROM rd_steer_versions sv\n    WHERE sv.owner_id=op.owner_id AND sv.id=(selected->>\'version_id\')::uuid\n    AND sv.steer_id=(selected->>\'steer_id\')::uuid AND sv.ordinal=(selected->>\'ordinal\')::integer\n    AND sv.kind=selected->>\'kind\' AND sv.text=selected->>\'text\' AND sv.text_sha256=selected->>\'text_sha256\'\n    AND sv.content_canonical::jsonb=selected\n    AND sv.content_sha256=encode(sha256(convert_to(mineagent_rd_canonical_json(selected,true),\'UTF8\')),\'hex\'))\n   THEN RAISE EXCEPTION \'Provider request selected steer version differs\'; END IF;\n  END LOOP;\n  IF amount IS NULL THEN RAISE EXCEPTION \'Provider pricing/reservation is unavailable\'; END IF;\n  SELECT count(*) INTO n FROM factor_generation_model_operations m\n   JOIN factor_upstream_calls c ON c.id=m.call_id\n   JOIN factor_generation_starts g ON g.id=m.start_id\n   JOIN factor_research_specs s ON s.id=g.spec_id\n   JOIN research_operation_contexts ctx ON ctx.id=m.context_id\n   WHERE m.operation_id=op.id AND m.protocol=op.protocol\n   AND (m.owner_id,m.run_id,m.attempt_id,m.generation)=(op.owner_id,op.run_id,op.attempt_id,op.generation)\n   AND (c.owner_id,c.run_id,c.attempt_id,c.generation)=(op.owner_id,op.run_id,op.attempt_id,op.generation)\n   AND (g.owner_id,g.run_id,g.attempt_id,g.generation)=(op.owner_id,op.run_id,op.attempt_id,op.generation)\n   AND (ctx.owner_id,ctx.run_id,ctx.attempt_id,ctx.generation)=(op.owner_id,op.run_id,op.attempt_id,op.generation)\n   AND (s.owner_id,s.run_id)=(op.owner_id,op.run_id) AND s.config=run.config AND s.config_sha256=run.request_sha256\n   AND c.start_id=g.id AND c.context_id=m.context_id AND g.context_id=m.context_id AND op.context_id=m.context_id\n   AND ctx.context->>\'spec_sha256\'=s.config_sha256 AND ctx.context->>\'input_sha256\'=s.input_sha256\n   AND c.kind=op.request->>\'kind\'\n   AND EXISTS(SELECT 1 FROM factor_controller_launches l JOIN factor_research_attempt_bindings b ON b.id=l.attempt_binding_id\n    JOIN research_process_admissions a ON a.id=l.admission_id\n    WHERE (l.owner_id,l.run_id,l.attempt_id,l.generation)=(op.owner_id,op.run_id,op.attempt_id,op.generation)\n    AND (b.owner_id,b.run_id,b.attempt_id,b.generation)=(op.owner_id,op.run_id,op.attempt_id,op.generation)\n    AND (a.owner_id,a.run_id,a.attempt_id,a.generation)=(op.owner_id,op.run_id,op.attempt_id,op.generation)\n    AND b.spec_id=s.id AND a.logical_operation_id=b.id\n    AND a.image_id=run.config->\'runtime\'->>\'orchestrator_image\' AND a.role=\'rd_orchestrator\' AND a.profile IN (\'mineagent.rdagent-orchestrator.v2\',\'mineagent.rdagent-orchestrator.v3\')\n    AND l.bootstrap->\'config\'=run.config AND l.bootstrap->>\'config_sha256\'=s.config_sha256);\n  IF n<>1 OR (SELECT count(*) FROM factor_generation_model_operations WHERE operation_id=op.id)<>1\n  THEN RAISE EXCEPTION \'Provider operation must belong to one exact controller call\'; END IF;\n  SELECT count(*) INTO n FROM research_model_transports WHERE operation_id=op.id;\n  IF n<>1 THEN RAISE EXCEPTION \'Provider operation needs exactly one initial transport; cannot automatically retry\'; END IF;\n  SELECT * INTO attempt FROM execution_attempts WHERE id=op.attempt_id;\n  IF attempt.id IS NULL OR (attempt.run_id,attempt.generation) IS DISTINCT FROM (op.run_id,op.generation)\n  THEN RAISE EXCEPTION \'Provider operation attempt scope differs\'; END IF;\n  must_be_stopped:=attempt.sandbox_stopped IS TRUE OR attempt.finished_at IS NOT NULL\n   OR attempt.status IN (\'succeeded\',\'failed\',\'cancelled\',\'interrupted\')\n   OR run.status IN (\'succeeded\',\'failed\',\'cancelled\',\'interrupted\');\n  FOR t IN SELECT * FROM research_model_transports WHERE operation_id=op.id LOOP\n   IF must_be_stopped AND (t.state IS NULL OR t.state NOT IN (\'completed\',\'failed\',\'unknown\'))\n   THEN RAISE EXCEPTION \'Terminal provider attempt requires terminal charged transport\'; END IF;\n   SELECT * INTO held FROM research_budget_reservations WHERE id=t.reservation_id;\n   IF (t.owner_id,t.run_id,t.attempt_id,t.generation) IS DISTINCT FROM (op.owner_id,op.run_id,op.attempt_id,op.generation)\n   OR (held.owner_id,held.run_id,held.attempt_id,held.generation) IS DISTINCT FROM (op.owner_id,op.run_id,op.attempt_id,op.generation)\n   OR held.purpose IS DISTINCT FROM \'model_transport\' OR held.amounts IS DISTINCT FROM amount OR t.ordinal<>1\n   THEN RAISE EXCEPTION \'Provider exact conservative reservation differs\'; END IF;\n   IF t.state IN (\'completed\',\'failed\',\'unknown\') THEN\n    SELECT * INTO settlement FROM research_budget_settlements WHERE reservation_id=held.id;\n    SELECT * INTO outcome FROM research_model_outcomes WHERE transport_id=t.id;\n    IF held.state IS DISTINCT FROM \'settled\' OR settlement.outcome IS DISTINCT FROM \'conservative_unknown\'\n    OR settlement.charge IS DISTINCT FROM amount OR outcome.usage IS DISTINCT FROM amount\n    OR outcome.outcome IS DISTINCT FROM t.state\n    OR (settlement.owner_id,settlement.run_id,settlement.attempt_id,settlement.generation) IS DISTINCT FROM (op.owner_id,op.run_id,op.attempt_id,op.generation)\n    OR (outcome.owner_id,outcome.run_id,outcome.attempt_id,outcome.generation) IS DISTINCT FROM (op.owner_id,op.run_id,op.attempt_id,op.generation)\n    THEN RAISE EXCEPTION \'Provider terminal usage cannot refund its whole held vector\'; END IF;\n   END IF;\n   IF (t.state=\'completed\' OR must_be_stopped) AND (SELECT array_agg(kind ORDER BY kind) FROM rd_provider_transport_receipts WHERE transport_id=t.id)\n      IS DISTINCT FROM ARRAY[\'intent\',\'started\',\'stopped\']::varchar[]\n   THEN RAISE EXCEPTION \'Provider completion needs all registered SDK evidence\'; END IF;\n  END LOOP;\n END LOOP;\n FOR w IN SELECT * FROM rd_provider_transport_receipts WHERE run_id=rid LOOP\n  IF NOT EXISTS(SELECT 1 FROM research_model_transports sdk_transport JOIN research_model_operations sdk_operation ON sdk_operation.id=sdk_transport.operation_id\n   JOIN research_objects obj ON obj.id=w.receipt_object_id\n   JOIN research_object_outcomes done ON done.object_id=obj.id AND done.owner_id=obj.owner_id AND done.object_kind=obj.object_kind AND done.sha256=obj.sha256\n   JOIN research_object_publications pub ON pub.id=done.publication_id\n   JOIN research_budget_reservations object_hold ON object_hold.id=pub.budget_reservation_id\n   JOIN research_budget_settlements settled ON settled.reservation_id=object_hold.id\n   WHERE sdk_transport.id=w.transport_id AND sdk_operation.protocol IN (\'mineagent.rdagent-provider-chat.v1\',\'mineagent.rdagent-provider-embedding.v1\')\n   AND (sdk_transport.owner_id,sdk_transport.run_id,sdk_transport.attempt_id,sdk_transport.generation)=(w.owner_id,w.run_id,w.attempt_id,w.generation)\n   AND (sdk_operation.owner_id,sdk_operation.run_id,sdk_operation.attempt_id,sdk_operation.generation)=(w.owner_id,w.run_id,w.attempt_id,w.generation)\n   AND (pub.owner_id,pub.run_id,pub.attempt_id,pub.generation)=(w.owner_id,w.run_id,w.attempt_id,w.generation)\n   AND (object_hold.owner_id,object_hold.run_id,object_hold.attempt_id,object_hold.generation)=(w.owner_id,w.run_id,w.attempt_id,w.generation)\n   AND (settled.owner_id,settled.run_id,settled.attempt_id,settled.generation)=(w.owner_id,w.run_id,w.attempt_id,w.generation)\n   AND w.receipt_object_kind=\'rd_provider_process_receipt\' AND obj.object_kind=w.receipt_object_kind AND obj.owner_id=w.owner_id\n   AND obj.sha256=w.receipt_sha256 AND obj.size_bytes=w.size_bytes AND w.size_bytes BETWEEN 1 AND 16384\n   AND pub.object_kind=obj.object_kind AND pub.sha256=obj.sha256 AND pub.size_bytes=obj.size_bytes\n   AND object_hold.purpose=\'object_storage\' AND object_hold.state=\'settled\' AND settled.outcome=\'conservative_unknown\' AND settled.charge=object_hold.amounts\n   AND (object_hold.amounts->>\'storage_bytes\')::numeric>=pub.peak_bytes)\n  THEN RAISE EXCEPTION \'Provider SDK membership needs exact charged published object\'; END IF;\n END LOOP;\nEND $$;\nCREATE OR REPLACE FUNCTION @SCHEMA@.mineagent_rd_fixture_source_violation_026(source_uuid uuid)\nRETURNS text LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog AS $$\nDECLARE s record; st record; c record; a record; w record; v record; obj record;\n p record; po record; co record; m record; op record; final_outcome record;\n ap record; wp record; r record; count_members integer; count_transports integer;\n selected_first integer; idx integer := 0; previous_id uuid := NULL;\n metadata jsonb; part_documents jsonb := \'[]\'::jsonb;\n member_ids uuid[] := ARRAY[]::uuid[]; outcome_ids uuid[] := ARRAY[]::uuid[];\nBEGIN\n SELECT * INTO s FROM @SCHEMA@.factor_generation_sources WHERE id=source_uuid;\n IF NOT FOUND THEN RETURN \'source_missing\'; END IF;\n IF NOT EXISTS (SELECT 1 FROM @SCHEMA@.research_runs rr WHERE rr.id=s.run_id AND rr.owner_id=s.owner_id\n  AND rr.purpose=\'factor_research\' AND rr.engine=\'rdagent\') THEN RETURN \'run_identity\'; END IF;\n SELECT * INTO st FROM @SCHEMA@.factor_generation_starts WHERE id=s.start_id;\n IF NOT FOUND OR (st.owner_id,st.run_id,st.attempt_id,st.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR st.context_id<>s.context_id THEN RETURN \'start_scope\'; END IF;\n SELECT * INTO c FROM @SCHEMA@.factor_upstream_calls WHERE id=s.call_id;\n IF NOT FOUND OR (c.owner_id,c.run_id,c.attempt_id,c.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR (c.start_id,c.context_id,c.phase,c.kind)\n  IS DISTINCT FROM (s.start_id,s.context_id,\'generation\'::varchar,\'chat\'::varchar) THEN RETURN \'generation_call\'; END IF;\n SELECT * INTO a FROM @SCHEMA@.factor_response_assemblies WHERE id=s.assembly_id;\n IF NOT FOUND OR (a.owner_id,a.run_id,a.attempt_id,a.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR (a.start_id,a.context_id,a.call_id)\n  IS DISTINCT FROM (s.start_id,s.context_id,s.call_id) THEN RETURN \'assembly_scope\'; END IF;\n SELECT * INTO w FROM @SCHEMA@.factor_source_read_witnesses WHERE source_id=s.id;\n IF NOT FOUND OR (w.owner_id,w.run_id,w.attempt_id,w.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR (w.assembly_id,w.call_id,w.source_sha256,w.part_count)\n  IS DISTINCT FROM (a.id,c.id,s.source_sha256,a.part_count) THEN RETURN \'source_read_witness\'; END IF;\n IF w.parser_profile<>\'mineagent.rdagent-source-parser.v1\' OR w.parser_source_sha256<>\n  \'a5a6a4a397f86b71caac2b1e056d200411c9d6254dff5e81d84aad8c19d1a583\' THEN RETURN \'parser_identity\'; END IF;\n SELECT * INTO co FROM @SCHEMA@.factor_upstream_call_outcomes WHERE call_id=c.id;\n IF NOT FOUND OR (co.owner_id,co.run_id,co.attempt_id,co.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR co.status<>\'completed\'\n  OR co.controller_launch_id<>w.controller_launch_id THEN RETURN \'call_completion\'; END IF;\n IF NOT EXISTS (SELECT 1 FROM @SCHEMA@.factor_controller_launches cl WHERE cl.id=w.controller_launch_id\n  AND (cl.owner_id,cl.run_id,cl.attempt_id,cl.generation)=(s.owner_id,s.run_id,s.attempt_id,s.generation)) THEN RETURN \'controller_scope\'; END IF;\n IF NOT EXISTS (SELECT 1 FROM @SCHEMA@.factor_controller_launches cl\n  JOIN @SCHEMA@.research_process_admissions pa ON pa.id=cl.admission_id\n  JOIN @SCHEMA@.factor_research_attempt_bindings ab ON ab.id=cl.attempt_binding_id\n  JOIN @SCHEMA@.factor_research_specs sp ON sp.id=ab.spec_id\n  JOIN @SCHEMA@.research_runs rr ON rr.id=s.run_id\n  WHERE cl.id=w.controller_launch_id AND (pa.owner_id,pa.run_id,pa.attempt_id,pa.generation)=(s.owner_id,s.run_id,s.attempt_id,s.generation) AND (ab.owner_id,ab.run_id,ab.attempt_id,ab.generation)=(s.owner_id,s.run_id,s.attempt_id,s.generation)\n  AND sp.owner_id=s.owner_id AND sp.run_id=s.run_id AND sp.id=st.spec_id AND rr.config=sp.config\n  AND pa.role=\'rd_orchestrator\' AND pa.profile IN (\'mineagent.rdagent-orchestrator.v1\',\'mineagent.rdagent-orchestrator.v2\',\'mineagent.rdagent-orchestrator.v3\')\n  AND pa.input_sha256=cl.bootstrap_sha256 AND pa.logical_operation_id=ab.id\n  AND pa.image_id=sp.config->\'runtime\'->>\'orchestrator_image\') THEN RETURN \'controller_admission\'; END IF;\n SELECT * INTO v FROM @SCHEMA@.factor_versions WHERE id=s.factor_version_id;\n IF NOT FOUND OR v.owner_id<>s.owner_id OR v.code_sha256<>s.source_sha256 OR v.source_kind<>\'rdagent\'\n  OR v.parent_version_id IS DISTINCT FROM st.parent_factor_version_id\n  OR v.source_event_key IS DISTINCT FROM \'rdagent:\'||s.start_id::text\n  OR v.source_provenance->>\'run_id\' IS DISTINCT FROM s.run_id::text\n  OR v.source_provenance->>\'start_id\' IS DISTINCT FROM s.start_id::text\n  OR v.source_provenance->>\'call_id\' IS DISTINCT FROM s.call_id::text\n  OR v.source_provenance->>\'assembly_sha256\' IS DISTINCT FROM a.object_sha256\n  OR encode(sha256(convert_to(v.code,\'UTF8\')),\'hex\')<>s.source_sha256\n  OR octet_length(v.code)<>w.source_size_bytes THEN RETURN \'factor_version\'; END IF;\n SELECT * INTO obj FROM @SCHEMA@.factor_objects WHERE id=v.code_object_id;\n IF NOT FOUND OR (obj.owner_id,obj.object_kind,obj.media_type,obj.sha256,obj.size_bytes,obj.id)\n  IS DISTINCT FROM (s.owner_id,\'code\'::varchar,\'text/plain\'::varchar,s.source_sha256,w.source_size_bytes::bigint,w.source_object_id)\n  OR w.source_object_kind<>\'code\' THEN RETURN \'source_code_object\'; END IF;\n SELECT * INTO p FROM @SCHEMA@.factor_source_publications WHERE start_id=s.start_id;\n IF NOT FOUND OR (p.owner_id,p.run_id,p.attempt_id,p.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR\n  (p.call_id,p.assembly_object_id,p.assembly_object_kind,p.assembly_sha256,p.source_sha256,p.size_bytes,p.factor_id,p.factor_version_id)\n  IS DISTINCT FROM (c.id,a.object_id,a.object_kind,a.object_sha256,s.source_sha256,w.source_size_bytes,v.factor_id,v.id)\n  THEN RETURN \'source_publication\'; END IF;\n SELECT * INTO po FROM @SCHEMA@.factor_source_publication_outcomes WHERE source_id=s.id;\n IF NOT FOUND OR (po.owner_id,po.run_id,po.attempt_id,po.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR po.publication_id<>p.id THEN RETURN \'source_publication_outcome\'; END IF;\n SELECT * INTO r FROM @SCHEMA@.research_budget_reservations WHERE id=p.budget_reservation_id;\n IF NOT FOUND OR (r.owner_id,r.run_id,r.attempt_id,r.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR r.purpose<>\'object_storage\'\n  OR r.logical_key<>\'rdsource:\'||s.start_id::text OR (r.amounts->>\'storage_bytes\')::numeric IS DISTINCT FROM p.peak_bytes::numeric\n  OR EXISTS (SELECT 1 FROM jsonb_each(r.amounts) x WHERE x.key<>\'storage_bytes\' AND x.value<>\'0\'::jsonb)\n  THEN RETURN \'source_reservation\'; END IF;\n IF NOT EXISTS (SELECT 1 FROM @SCHEMA@.engine_object_reservation_consumers ec WHERE ec.reservation_id=r.id\n  AND (ec.owner_id,ec.run_id,ec.attempt_id,ec.generation)=(s.owner_id,s.run_id,s.attempt_id,s.generation) AND ec.consumer_kind=\'factor_source\' AND ec.consumer_id=p.id)\n  THEN RETURN \'source_consumer_claim\'; END IF;\n SELECT count(*),max(request_ordinal) FILTER (WHERE relation<>\'continuation\') INTO count_members,selected_first\n  FROM @SCHEMA@.factor_generation_model_operations WHERE call_id=c.id;\n IF count_members NOT BETWEEN 1 AND 60 OR selected_first IS NULL OR\n  count_members-selected_first NOT BETWEEN 1 AND 6 OR co.member_count<>count_members\n  OR w.selected_first_ordinal<>selected_first OR w.part_count<>count_members-selected_first THEN RETURN \'member_cardinality\'; END IF;\n FOR m IN SELECT * FROM @SCHEMA@.factor_generation_model_operations WHERE call_id=c.id ORDER BY request_ordinal LOOP\n  IF (m.owner_id,m.run_id,m.attempt_id,m.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR (m.start_id,m.context_id,m.protocol)\n   IS DISTINCT FROM (s.start_id,s.context_id,\'mineagent.rdagent-chat.v1\'::varchar)\n   OR m.request_ordinal<>idx OR m.predecessor_id IS DISTINCT FROM previous_id\n   OR (idx=0 AND m.relation<>\'initial\') OR (idx>0 AND m.relation NOT IN (\'continuation\',\'semantic_repair\'))\n   THEN RETURN \'member_order_scope\'; END IF;\n  SELECT * INTO op FROM @SCHEMA@.research_model_operations WHERE id=m.operation_id;\n  IF NOT FOUND OR (op.owner_id,op.run_id,op.attempt_id,op.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR op.context_id<>s.context_id OR op.state<>\'completed\'\n   OR op.protocol<>m.protocol\n   OR op.purpose<>(CASE WHEN m.relation=\'continuation\' THEN \'continuation\' ELSE \'chat\' END)\n   OR op.request->>\'kind\' IS DISTINCT FROM \'chat\' OR op.request->>\'model\' IS DISTINCT FROM \'fixture.rdagent.v1\'\n   OR op.request->\'response_format\' IS DISTINCT FROM \'{"type":"json_object"}\'::jsonb THEN RETURN \'operation_scope\'; END IF;\n  SELECT count(*) INTO count_transports FROM @SCHEMA@.research_model_transports WHERE operation_id=op.id;\n  IF count_transports NOT BETWEEN 1 AND 256 OR EXISTS (\n   SELECT 1 FROM @SCHEMA@.research_model_transports t LEFT JOIN @SCHEMA@.research_model_outcomes o ON o.transport_id=t.id\n    LEFT JOIN @SCHEMA@.research_budget_reservations br ON br.id=t.reservation_id\n    LEFT JOIN @SCHEMA@.research_budget_settlements bs ON bs.reservation_id=br.id\n   WHERE t.operation_id=op.id AND ((t.owner_id,t.run_id,t.attempt_id,t.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR (o.owner_id,o.run_id,o.attempt_id,o.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation)\n    OR (br.owner_id,br.run_id,br.attempt_id,br.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR (bs.owner_id,bs.run_id,bs.attempt_id,bs.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation)\n    OR t.ordinal NOT BETWEEN 1 AND count_transports OR br.purpose<>\'model_transport\' OR br.state<>\'settled\'\n    OR t.state<>(CASE WHEN t.ordinal=count_transports THEN \'completed\' ELSE \'failed\' END)\n    OR o.outcome<>t.state OR o.usage IS DISTINCT FROM bs.charge OR bs.outcome<>\'measured\'\n    OR EXISTS (SELECT 1 FROM jsonb_each(bs.charge) amount WHERE amount.value::text::numeric>(br.amounts->>amount.key)::numeric)\n    OR (o.usage->>\'calls\')::numeric<>1 OR (br.amounts->>\'calls\')::numeric<>1)) THEN RETURN \'physical_transport_closure\'; END IF;\n  SELECT o.* INTO final_outcome FROM @SCHEMA@.research_model_transports t\n   JOIN @SCHEMA@.research_model_outcomes o ON o.transport_id=t.id\n   WHERE t.operation_id=op.id AND t.ordinal=count_transports AND o.outcome=\'completed\';\n  IF NOT FOUND OR NOT EXISTS (SELECT 1 FROM @SCHEMA@.research_objects ro\n    WHERE ro.id=final_outcome.response_object_id AND (ro.owner_id,ro.object_kind,ro.sha256)\n    =(s.owner_id,\'model_response\'::varchar,final_outcome.response_sha256)) THEN RETURN \'completed_response\'; END IF;\n  member_ids:=array_append(member_ids,m.id); outcome_ids:=array_append(outcome_ids,final_outcome.id);\n  IF idx>=selected_first THEN\n   SELECT * INTO ap FROM @SCHEMA@.factor_response_assembly_parts WHERE assembly_id=a.id AND ordinal=idx-selected_first;\n   IF NOT FOUND OR (ap.owner_id,ap.run_id,ap.attempt_id,ap.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR\n    (ap.call_id,ap.member_id,ap.outcome_id,ap.response_object_id,ap.response_object_kind,ap.response_sha256)\n    IS DISTINCT FROM (c.id,m.id,final_outcome.id,final_outcome.response_object_id,\'model_response\'::varchar,final_outcome.response_sha256)\n    THEN RETURN \'selected_assembly_part\'; END IF;\n   SELECT * INTO wp FROM @SCHEMA@.factor_source_read_parts WHERE witness_id=w.id AND ordinal=idx-selected_first;\n   IF NOT FOUND OR (wp.owner_id,wp.run_id,wp.attempt_id,wp.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR\n    (wp.assembly_part_id,wp.member_id,wp.outcome_id,wp.response_object_id,wp.response_object_kind,wp.response_sha256)\n    IS DISTINCT FROM (ap.id,m.id,final_outcome.id,ap.response_object_id,ap.response_object_kind,ap.response_sha256)\n    OR wp.finish_reason<>(CASE WHEN idx=count_members-1 THEN \'stop\' ELSE \'length\' END)\n    THEN RETURN \'selected_read_part\'; END IF;\n   part_documents:=part_documents||jsonb_build_array(to_jsonb(wp)-ARRAY[\'id\',\'created_at\',\'owner_id\',\'run_id\',\'attempt_id\',\'generation\',\'witness_id\']);\n  END IF;\n  previous_id:=m.id; idx:=idx+1;\n END LOOP;\n IF co.member_ids IS DISTINCT FROM to_jsonb(member_ids) OR co.response_outcome_ids IS DISTINCT FROM to_jsonb(outcome_ids)\n  THEN RETURN \'completed_call_inventory\'; END IF;\n IF (SELECT count(*) FROM @SCHEMA@.factor_response_assembly_parts WHERE assembly_id=a.id)<>w.part_count OR\n  (SELECT count(*) FROM @SCHEMA@.factor_source_read_parts WHERE witness_id=w.id)<>w.part_count OR\n  (SELECT sum(content_size_bytes) FROM @SCHEMA@.factor_source_read_parts WHERE witness_id=w.id) IS DISTINCT FROM w.raw_text_bytes::bigint\n  THEN RETURN \'selected_inventory_size\'; END IF;\n metadata:=jsonb_build_object(\'schema_version\',\'mineagent.source-read-witness.v1\',\n  \'scope\',jsonb_build_object(\'owner_id\',s.owner_id,\'run_id\',s.run_id,\'attempt_id\',s.attempt_id,\'generation\',s.generation),\n  \'header\',to_jsonb(w)-ARRAY[\'id\',\'created_at\',\'owner_id\',\'run_id\',\'attempt_id\',\'generation\',\'witness_sha256\'],\n  \'parts\',part_documents);\n IF encode(sha256(convert_to(@SCHEMA@.mineagent_rd_ascii_metadata(metadata),\'UTF8\')),\'hex\')<>w.witness_sha256\n  THEN RETURN \'witness_metadata_digest\'; END IF;\n RETURN NULL;\nEND $$;\nCREATE OR REPLACE FUNCTION @SCHEMA@.mineagent_rd_provider_source_violation(source_uuid uuid)\nRETURNS text LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog AS $$\nDECLARE s record; st record; c record; a record; w record; v record; obj record;\n p record; po record; co record; m record; op record; final_outcome record;\n ap record; wp record; r record; count_members integer; count_transports integer;\n selected_first integer; idx integer := 0; previous_id uuid := NULL;\n metadata jsonb; part_documents jsonb := \'[]\'::jsonb;\n member_ids uuid[] := ARRAY[]::uuid[]; outcome_ids uuid[] := ARRAY[]::uuid[];\nBEGIN\n SELECT * INTO s FROM @SCHEMA@.factor_generation_sources WHERE id=source_uuid;\n IF NOT FOUND THEN RETURN \'source_missing\'; END IF;\n IF NOT EXISTS (SELECT 1 FROM @SCHEMA@.research_runs rr WHERE rr.id=s.run_id AND rr.owner_id=s.owner_id\n  AND rr.purpose=\'factor_research\' AND rr.engine=\'rdagent\') THEN RETURN \'run_identity\'; END IF;\n SELECT * INTO st FROM @SCHEMA@.factor_generation_starts WHERE id=s.start_id;\n IF NOT FOUND OR (st.owner_id,st.run_id,st.attempt_id,st.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR st.context_id<>s.context_id THEN RETURN \'start_scope\'; END IF;\n SELECT * INTO c FROM @SCHEMA@.factor_upstream_calls WHERE id=s.call_id;\n IF NOT FOUND OR (c.owner_id,c.run_id,c.attempt_id,c.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR (c.start_id,c.context_id,c.phase,c.kind)\n  IS DISTINCT FROM (s.start_id,s.context_id,\'generation\'::varchar,\'chat\'::varchar) THEN RETURN \'generation_call\'; END IF;\n SELECT * INTO a FROM @SCHEMA@.factor_response_assemblies WHERE id=s.assembly_id;\n IF NOT FOUND OR (a.owner_id,a.run_id,a.attempt_id,a.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR (a.start_id,a.context_id,a.call_id)\n  IS DISTINCT FROM (s.start_id,s.context_id,s.call_id) THEN RETURN \'assembly_scope\'; END IF;\n SELECT * INTO w FROM @SCHEMA@.factor_source_read_witnesses WHERE source_id=s.id;\n IF NOT FOUND OR (w.owner_id,w.run_id,w.attempt_id,w.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR (w.assembly_id,w.call_id,w.source_sha256,w.part_count)\n  IS DISTINCT FROM (a.id,c.id,s.source_sha256,a.part_count) THEN RETURN \'source_read_witness\'; END IF;\n IF w.parser_profile<>\'mineagent.rdagent-provider-source-parser.v1\' OR w.parser_source_sha256<>\n  \'a5a6a4a397f86b71caac2b1e056d200411c9d6254dff5e81d84aad8c19d1a583\' THEN RETURN \'parser_identity\'; END IF;\n SELECT * INTO co FROM @SCHEMA@.factor_upstream_call_outcomes WHERE call_id=c.id;\n IF NOT FOUND OR (co.owner_id,co.run_id,co.attempt_id,co.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR co.status<>\'completed\'\n  OR co.controller_launch_id<>w.controller_launch_id THEN RETURN \'call_completion\'; END IF;\n IF NOT EXISTS (SELECT 1 FROM @SCHEMA@.factor_controller_launches cl WHERE cl.id=w.controller_launch_id\n  AND (cl.owner_id,cl.run_id,cl.attempt_id,cl.generation)=(s.owner_id,s.run_id,s.attempt_id,s.generation)) THEN RETURN \'controller_scope\'; END IF;\n IF NOT EXISTS (SELECT 1 FROM @SCHEMA@.factor_controller_launches cl\n  JOIN @SCHEMA@.research_process_admissions pa ON pa.id=cl.admission_id\n  JOIN @SCHEMA@.factor_research_attempt_bindings ab ON ab.id=cl.attempt_binding_id\n  JOIN @SCHEMA@.factor_research_specs sp ON sp.id=ab.spec_id\n  JOIN @SCHEMA@.research_runs rr ON rr.id=s.run_id\n  WHERE cl.id=w.controller_launch_id AND (pa.owner_id,pa.run_id,pa.attempt_id,pa.generation)=(s.owner_id,s.run_id,s.attempt_id,s.generation) AND (ab.owner_id,ab.run_id,ab.attempt_id,ab.generation)=(s.owner_id,s.run_id,s.attempt_id,s.generation)\n  AND sp.owner_id=s.owner_id AND sp.run_id=s.run_id AND sp.id=st.spec_id AND rr.config=sp.config\n  AND pa.role=\'rd_orchestrator\' AND pa.profile IN (\'mineagent.rdagent-orchestrator.v1\',\'mineagent.rdagent-orchestrator.v2\',\'mineagent.rdagent-orchestrator.v3\')\n  AND pa.input_sha256=cl.bootstrap_sha256 AND pa.logical_operation_id=ab.id\n  AND pa.image_id=sp.config->\'runtime\'->>\'orchestrator_image\') THEN RETURN \'controller_admission\'; END IF;\n SELECT * INTO v FROM @SCHEMA@.factor_versions WHERE id=s.factor_version_id;\n IF NOT FOUND OR v.owner_id<>s.owner_id OR v.code_sha256<>s.source_sha256 OR v.source_kind<>\'rdagent\'\n  OR v.parent_version_id IS DISTINCT FROM st.parent_factor_version_id\n  OR v.source_event_key IS DISTINCT FROM \'rdagent:\'||s.start_id::text\n  OR v.source_provenance->>\'run_id\' IS DISTINCT FROM s.run_id::text\n  OR v.source_provenance->>\'start_id\' IS DISTINCT FROM s.start_id::text\n  OR v.source_provenance->>\'call_id\' IS DISTINCT FROM s.call_id::text\n  OR v.source_provenance->>\'assembly_sha256\' IS DISTINCT FROM a.object_sha256\n  OR encode(sha256(convert_to(v.code,\'UTF8\')),\'hex\')<>s.source_sha256\n  OR octet_length(v.code)<>w.source_size_bytes THEN RETURN \'factor_version\'; END IF;\n SELECT * INTO obj FROM @SCHEMA@.factor_objects WHERE id=v.code_object_id;\n IF NOT FOUND OR (obj.owner_id,obj.object_kind,obj.media_type,obj.sha256,obj.size_bytes,obj.id)\n  IS DISTINCT FROM (s.owner_id,\'code\'::varchar,\'text/plain\'::varchar,s.source_sha256,w.source_size_bytes::bigint,w.source_object_id)\n  OR w.source_object_kind<>\'code\' THEN RETURN \'source_code_object\'; END IF;\n SELECT * INTO p FROM @SCHEMA@.factor_source_publications WHERE start_id=s.start_id;\n IF NOT FOUND OR (p.owner_id,p.run_id,p.attempt_id,p.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR\n  (p.call_id,p.assembly_object_id,p.assembly_object_kind,p.assembly_sha256,p.source_sha256,p.size_bytes,p.factor_id,p.factor_version_id)\n  IS DISTINCT FROM (c.id,a.object_id,a.object_kind,a.object_sha256,s.source_sha256,w.source_size_bytes,v.factor_id,v.id)\n  THEN RETURN \'source_publication\'; END IF;\n SELECT * INTO po FROM @SCHEMA@.factor_source_publication_outcomes WHERE source_id=s.id;\n IF NOT FOUND OR (po.owner_id,po.run_id,po.attempt_id,po.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR po.publication_id<>p.id THEN RETURN \'source_publication_outcome\'; END IF;\n SELECT * INTO r FROM @SCHEMA@.research_budget_reservations WHERE id=p.budget_reservation_id;\n IF NOT FOUND OR (r.owner_id,r.run_id,r.attempt_id,r.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR r.purpose<>\'object_storage\'\n  OR r.logical_key<>\'rdsource:\'||s.start_id::text OR (r.amounts->>\'storage_bytes\')::numeric IS DISTINCT FROM p.peak_bytes::numeric\n  OR EXISTS (SELECT 1 FROM jsonb_each(r.amounts) x WHERE x.key<>\'storage_bytes\' AND x.value<>\'0\'::jsonb)\n  THEN RETURN \'source_reservation\'; END IF;\n IF NOT EXISTS (SELECT 1 FROM @SCHEMA@.engine_object_reservation_consumers ec WHERE ec.reservation_id=r.id\n  AND (ec.owner_id,ec.run_id,ec.attempt_id,ec.generation)=(s.owner_id,s.run_id,s.attempt_id,s.generation) AND ec.consumer_kind=\'factor_source\' AND ec.consumer_id=p.id)\n  THEN RETURN \'source_consumer_claim\'; END IF;\n SELECT count(*),max(request_ordinal) FILTER (WHERE relation<>\'continuation\') INTO count_members,selected_first\n  FROM @SCHEMA@.factor_generation_model_operations WHERE call_id=c.id;\n IF count_members NOT BETWEEN 1 AND 60 OR selected_first IS NULL OR\n  count_members-selected_first NOT BETWEEN 1 AND 6 OR co.member_count<>count_members\n  OR w.selected_first_ordinal<>selected_first OR w.part_count<>count_members-selected_first THEN RETURN \'member_cardinality\'; END IF;\n FOR m IN SELECT * FROM @SCHEMA@.factor_generation_model_operations WHERE call_id=c.id ORDER BY request_ordinal LOOP\n  IF (m.owner_id,m.run_id,m.attempt_id,m.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR (m.start_id,m.context_id,m.protocol)\n   IS DISTINCT FROM (s.start_id,s.context_id,\'mineagent.rdagent-provider-chat.v1\'::varchar)\n   OR m.request_ordinal<>idx OR m.predecessor_id IS DISTINCT FROM previous_id\n   OR (idx=0 AND m.relation<>\'initial\') OR (idx>0 AND m.relation NOT IN (\'continuation\',\'semantic_repair\'))\n   THEN RETURN \'member_order_scope\'; END IF;\n  SELECT * INTO op FROM @SCHEMA@.research_model_operations WHERE id=m.operation_id;\n  IF NOT FOUND OR (op.owner_id,op.run_id,op.attempt_id,op.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR op.context_id<>s.context_id OR op.state<>\'completed\'\n   OR op.protocol<>m.protocol\n   OR op.purpose<>(CASE WHEN m.relation=\'continuation\' THEN \'continuation\' ELSE \'chat\' END)\n   OR op.request->>\'kind\' IS DISTINCT FROM \'chat\' OR op.request->>\'model\' IS DISTINCT FROM (SELECT config#>>\'{model_binding,chat_model}\' FROM @SCHEMA@.research_runs WHERE id=s.run_id)\n   OR op.request->\'response_format\' IS DISTINCT FROM \'{"type":"json_object"}\'::jsonb THEN RETURN \'operation_scope\'; END IF;\n  SELECT count(*) INTO count_transports FROM @SCHEMA@.research_model_transports WHERE operation_id=op.id;\n  IF count_transports<>1 OR EXISTS (\n   SELECT 1 FROM @SCHEMA@.research_model_transports t LEFT JOIN @SCHEMA@.research_model_outcomes o ON o.transport_id=t.id\n    LEFT JOIN @SCHEMA@.research_budget_reservations br ON br.id=t.reservation_id\n    LEFT JOIN @SCHEMA@.research_budget_settlements bs ON bs.reservation_id=br.id\n   WHERE t.operation_id=op.id AND ((t.owner_id,t.run_id,t.attempt_id,t.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR (o.owner_id,o.run_id,o.attempt_id,o.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation)\n    OR (br.owner_id,br.run_id,br.attempt_id,br.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR (bs.owner_id,bs.run_id,bs.attempt_id,bs.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation)\n    OR t.ordinal NOT BETWEEN 1 AND count_transports OR br.purpose<>\'model_transport\' OR br.state<>\'settled\'\n    OR t.state<>(CASE WHEN t.ordinal=count_transports THEN \'completed\' ELSE \'failed\' END)\n    OR o.outcome<>t.state OR o.usage IS DISTINCT FROM bs.charge OR (bs.outcome<>\'conservative_unknown\' OR bs.charge IS DISTINCT FROM br.amounts)\n    OR EXISTS (SELECT 1 FROM jsonb_each(bs.charge) amount WHERE amount.value::text::numeric>(br.amounts->>amount.key)::numeric)\n    OR (o.usage->>\'calls\')::numeric<>1 OR (br.amounts->>\'calls\')::numeric<>1)) THEN RETURN \'physical_transport_closure\'; END IF;\n  SELECT o.* INTO final_outcome FROM @SCHEMA@.research_model_transports t\n   JOIN @SCHEMA@.research_model_outcomes o ON o.transport_id=t.id\n   WHERE t.operation_id=op.id AND t.ordinal=count_transports AND o.outcome=\'completed\';\n  IF NOT FOUND OR NOT EXISTS (SELECT 1 FROM @SCHEMA@.research_objects ro\n    WHERE ro.id=final_outcome.response_object_id AND (ro.owner_id,ro.object_kind,ro.sha256)\n    =(s.owner_id,\'model_response\'::varchar,final_outcome.response_sha256)) THEN RETURN \'completed_response\'; END IF;\n  member_ids:=array_append(member_ids,m.id); outcome_ids:=array_append(outcome_ids,final_outcome.id);\n  IF idx>=selected_first THEN\n   SELECT * INTO ap FROM @SCHEMA@.factor_response_assembly_parts WHERE assembly_id=a.id AND ordinal=idx-selected_first;\n   IF NOT FOUND OR (ap.owner_id,ap.run_id,ap.attempt_id,ap.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR\n    (ap.call_id,ap.member_id,ap.outcome_id,ap.response_object_id,ap.response_object_kind,ap.response_sha256)\n    IS DISTINCT FROM (c.id,m.id,final_outcome.id,final_outcome.response_object_id,\'model_response\'::varchar,final_outcome.response_sha256)\n    THEN RETURN \'selected_assembly_part\'; END IF;\n   SELECT * INTO wp FROM @SCHEMA@.factor_source_read_parts WHERE witness_id=w.id AND ordinal=idx-selected_first;\n   IF NOT FOUND OR (wp.owner_id,wp.run_id,wp.attempt_id,wp.generation) IS DISTINCT FROM (s.owner_id,s.run_id,s.attempt_id,s.generation) OR\n    (wp.assembly_part_id,wp.member_id,wp.outcome_id,wp.response_object_id,wp.response_object_kind,wp.response_sha256)\n    IS DISTINCT FROM (ap.id,m.id,final_outcome.id,ap.response_object_id,ap.response_object_kind,ap.response_sha256)\n    OR wp.finish_reason<>(CASE WHEN idx=count_members-1 THEN \'stop\' ELSE \'length\' END)\n    THEN RETURN \'selected_read_part\'; END IF;\n   part_documents:=part_documents||jsonb_build_array(to_jsonb(wp)-ARRAY[\'id\',\'created_at\',\'owner_id\',\'run_id\',\'attempt_id\',\'generation\',\'witness_id\']);\n  END IF;\n  previous_id:=m.id; idx:=idx+1;\n END LOOP;\n IF co.member_ids IS DISTINCT FROM to_jsonb(member_ids) OR co.response_outcome_ids IS DISTINCT FROM to_jsonb(outcome_ids)\n  THEN RETURN \'completed_call_inventory\'; END IF;\n IF (SELECT count(*) FROM @SCHEMA@.factor_response_assembly_parts WHERE assembly_id=a.id)<>w.part_count OR\n  (SELECT count(*) FROM @SCHEMA@.factor_source_read_parts WHERE witness_id=w.id)<>w.part_count OR\n  (SELECT sum(content_size_bytes) FROM @SCHEMA@.factor_source_read_parts WHERE witness_id=w.id) IS DISTINCT FROM w.raw_text_bytes::bigint\n  THEN RETURN \'selected_inventory_size\'; END IF;\n metadata:=jsonb_build_object(\'schema_version\',\'mineagent.source-read-witness.v1\',\n  \'scope\',jsonb_build_object(\'owner_id\',s.owner_id,\'run_id\',s.run_id,\'attempt_id\',s.attempt_id,\'generation\',s.generation),\n  \'header\',to_jsonb(w)-ARRAY[\'id\',\'created_at\',\'owner_id\',\'run_id\',\'attempt_id\',\'generation\',\'witness_sha256\'],\n  \'parts\',part_documents);\n IF encode(sha256(convert_to(@SCHEMA@.mineagent_rd_ascii_metadata(metadata),\'UTF8\')),\'hex\')<>w.witness_sha256\n  THEN RETURN \'witness_metadata_digest\'; END IF;\n RETURN NULL;\nEND $$;\nCREATE OR REPLACE FUNCTION @SCHEMA@.mineagent_rd_provider_queued_config(rid uuid) RETURNS void\nLANGUAGE plpgsql SET search_path=@SCHEMA@,pg_catalog AS $$\nDECLARE r research_runs%ROWTYPE; v jsonb; price jsonb; max_cost numeric;\nBEGIN\n SELECT * INTO STRICT r FROM research_runs WHERE id=rid;\n v:=r.config; price:=v#>\'{model_binding,pricing}\';\n IF mineagent_rd_provider_config(v) IS NOT TRUE OR v->>\'max_iterations\'<>\'1\'\n OR v#>>\'{steer_snapshot,owner_id}\'<>r.owner_id::text\n OR price->>\'status\' IS DISTINCT FROM \'operator_declared\'\n THEN RAISE EXCEPTION \'Configured provider declaration differs\'; END IF;\n max_cost:=32*ceil(greatest(262144*(price->>\'chat_input_microusd_per_million\')::numeric\n  +(v#>>\'{model_binding,max_output_tokens}\')::numeric*(price->>\'chat_output_microusd_per_million\')::numeric,\n  262144*(price->>\'embedding_microusd_per_million\')::numeric)/1000000);\n IF (v#>>\'{budget,calls}\')::numeric<32\n OR (v#>>\'{budget,tokens}\')::numeric<32*(262144+(v#>>\'{model_binding,max_output_tokens}\')::numeric)\n OR (v#>>\'{budget,cost_microunits}\')::numeric<max_cost\n OR (v#>>\'{budget,process_slots}\')::numeric<36\n OR (v#>>\'{budget,wall_milliseconds}\')::numeric< (CASE WHEN v->>\'controller_profile\'=\'mineagent.rdagent-orchestrator.v3\' THEN 300000 ELSE 240000 END)+32*(v#>>\'{model_binding,request_deadline_ms}\')::numeric\n OR (v#>>\'{budget,storage_bytes}\')::numeric<536870912+32*589824\n OR (v#>>\'{budget,evaluator_executions}\')::numeric<1\n THEN RAISE EXCEPTION \'Configured provider work exceeds declared admission budget\'; END IF;\nEND $$;\nCREATE OR REPLACE FUNCTION @SCHEMA@.mineagent_rd_seed_check(sid uuid) RETURNS void\nLANGUAGE plpgsql SET search_path=@SCHEMA@,pg_catalog AS $$\nDECLARE s factor_seeded_submissions%ROWTYPE; r research_runs%ROWTYPE;\n p factor_analysis_plans%ROWTYPE; sp factor_research_specs%ROWTYPE;\n v factor_versions%ROWTYPE; o factor_objects%ROWTYPE;\n expected jsonb; exact_bytes text; fields jsonb; profile_sha text; provider boolean; preflight jsonb;\nBEGIN\n SELECT * INTO STRICT s FROM factor_seeded_submissions WHERE id=sid;\n SELECT * INTO STRICT r FROM research_runs WHERE id=s.run_id;\n SELECT * INTO STRICT sp FROM factor_research_specs WHERE id=s.spec_id;\n SELECT * INTO STRICT p FROM factor_analysis_plans WHERE id=s.analysis_plan_id;\n provider:=r.config->>\'schema_version\'=\'mineagent.factor-research.v2\';\n SELECT * INTO STRICT v FROM factor_versions WHERE id=s.parent_factor_version_id;\n SELECT * INTO STRICT o FROM factor_objects WHERE id=s.parent_code_object_id;\n PERFORM mineagent_analysis_plan_check(p.id);\n IF provider THEN PERFORM mineagent_rd_provider_queued_config(r.id); END IF;\n IF (r.owner_id,r.idempotency_key,r.purpose,r.engine,r.request_sha256)\n IS DISTINCT FROM (s.owner_id,s.idempotency_key,\'factor_research\'::varchar,\'rdagent\'::varchar,s.config_sha256)\n OR (sp.owner_id,sp.run_id,sp.config_sha256,sp.input_sha256)\n IS DISTINCT FROM (s.owner_id,r.id,s.config_sha256,p.input_sha256)\n OR (p.owner_id,p.run_id,p.spec_id,p.config_sha256)\n IS DISTINCT FROM (s.owner_id,r.id,sp.id,s.config_sha256)\n OR r.config->>\'max_iterations\' IS DISTINCT FROM \'1\'\n OR (NOT provider AND (r.config->\'task\'->>\'factor_kind\' IS DISTINCT FROM \'time_series\'\n OR r.config->\'task\'->>\'output_unit\' IS DISTINCT FROM \'return\'\n OR r.config->\'task\'->>\'formulation\' IS DISTINCT FROM\n (\'close[t]/close[t-\'||(r.config->\'input\'->>\'lookback_sessions\')||\']-1\')))\n THEN RAISE EXCEPTION \'Seeded request exact run/spec/plan/profile binding differs\'; END IF;\n IF (v.owner_id,v.factor_id,v.ordinal,v.code_object_id,v.code_sha256,v.definition_sha256)\n IS DISTINCT FROM (s.owner_id,s.parent_factor_id,s.parent_ordinal,s.parent_code_object_id,s.parent_code_sha256,s.parent_definition_sha256)\n OR (o.owner_id,o.object_kind,o.media_type,o.sha256,o.size_bytes,o.storage_key)\n IS DISTINCT FROM (s.owner_id,\'code\'::varchar,\'text/plain\'::varchar,s.parent_code_sha256,\n s.parent_code_size_bytes::bigint,\'factors/\'||s.owner_id::text||\'/objects/\'||s.parent_code_sha256||\'.py\')\n OR octet_length(v.code)<>s.parent_code_size_bytes\n OR encode(sha256(convert_to(v.code,\'UTF8\')),\'hex\')<>s.parent_code_sha256\n OR NOT EXISTS(SELECT 1 FROM factors WHERE id=s.parent_factor_id AND owner_id=s.owner_id)\n OR mineagent_analysis_raw_commitment(s.parent_provenance_canonical,v.source_provenance,s.parent_provenance_sha256,65536) IS NOT TRUE\n OR s.parent_binding_sha256 IS DISTINCT FROM mineagent_execution_metadata_sha(mineagent_rd_seed_reference(s.id))\n THEN RAISE EXCEPTION \'Seeded parent exact retained metadata binding differs\'; END IF;\n IF NOT EXISTS(SELECT 1 FROM outbox_events WHERE run_id=r.id AND generation=1)\n OR NOT EXISTS(SELECT 1 FROM research_budget_controls WHERE run_id=r.id AND owner_id=r.owner_id AND limits=r.config->\'budget\')\n OR EXISTS(SELECT 1 FROM factor_research_submissions WHERE run_id=r.id)\n THEN RAISE EXCEPTION \'Seeded receipt requires one family, durable outbox and budget\'; END IF;\n SELECT jsonb_agg(value->\'name\' ORDER BY ord) INTO fields\n FROM jsonb_array_elements(r.config->\'input\'->\'input_fields\') WITH ORDINALITY f(value,ord);\n IF NOT provider AND (fields @> \'["close"]\'::jsonb) IS NOT TRUE THEN RAISE EXCEPTION \'Seeded fixed model requires close\'; END IF;\n expected:=jsonb_build_object(\'schema_version\',\'mineagent.rdagent-seeded-submission.v1\',\n \'purpose\',\'factor_research\',\'engine\',\'rdagent\',\'dataset_version_id\',r.dataset_version_id::text,\n \'window\',r.config->\'input\'->\'window\',\'input_fields\',fields,\n \'lookback_sessions\',r.config->\'input\'->\'lookback_sessions\',\'lag_sessions\',r.config->\'input\'->\'lag_sessions\',\n \'task\',r.config->\'task\',\'objective\',p.objective,\'budget\',r.config->\'budget\',\n \'max_iterations\',r.config->\'max_iterations\',\'source_policy\',p.source_policy,\n \'parent_factor_version_id\',s.parent_factor_version_id::text);\n IF provider THEN\n  expected:=expected || jsonb_build_object(\'schema_version\',\'mineagent.rdagent-provider-seeded-submission.v1\',\n   \'model_profile_id\',r.config#>>\'{model_binding,profile_id}\',\n   \'selected_steer_version_ids\',coalesce((SELECT jsonb_agg(value->\'version_id\' ORDER BY ord)\n      FROM jsonb_array_elements(r.config#>\'{steer_snapshot,versions}\') WITH ORDINALITY x(value,ord)),\'[]\'::jsonb));\n END IF;\n SELECT \'{\'||string_agg(mineagent_rd_canonical_json(to_jsonb(key),true)||\':\'||\n CASE WHEN key=\'objective\' THEN p.objective_canonical ELSE mineagent_rd_canonical_json(value,true) END,\n \',\' ORDER BY key COLLATE "C")||\'}\' INTO exact_bytes FROM jsonb_each(expected);\n profile_sha:=mineagent_execution_metadata_sha(jsonb_build_object(\n \'schema_version\',\'mineagent.rdagent-seeded-server-profile.v1\',\'profile\',\'configured_rd_seeded_single_output_session_v1\',\n \'model_profile\',\'fixture.rdagent.v1\',\'runtime\',r.config->\'runtime\',\'qlib_installed_parent_image_id\',p.qlib_installed_parent_image_id) || mineagent_rd_controller_selection(r.config));\n IF provider THEN\n  profile_sha:=mineagent_execution_metadata_sha(jsonb_build_object(\n   \'schema_version\',\'mineagent.rdagent-provider-server-profile.v1\',\'profile\',\'configured_rd_model_single_output_session_v1\',\n   \'model_profile\',\'configured.rdagent.v1\',\'runtime\',r.config->\'runtime\',\'qlib_installed_parent_image_id\',p.qlib_installed_parent_image_id) || mineagent_rd_controller_selection(r.config));\n  preflight:=jsonb_build_object(\'schema_version\',\'mineagent.rdagent-provider-preflight-binding.v1\',\n   \'owner_id\',s.owner_id::text,\'request_sha256\',s.request_sha256,\n   \'dataset_content_sha256\',p.label_source_manifest_sha256,\'frozen_input_sha256\',p.input_sha256,\n   \'catalog_revision\',\'configured_rd_model_single_output_session_v1\',\'runtime_profile_sha256\',profile_sha,\n   \'model_binding_sha256\',mineagent_execution_metadata_sha(r.config->\'model_binding\'),\n   \'steer_snapshot_sha256\',r.config->>\'steer_snapshot_sha256\',\'parent_binding_sha256\',s.parent_binding_sha256);\n ELSE\n  preflight:=jsonb_build_object(\n   \'schema_version\',\'mineagent.rdagent-seeded-preflight-binding.v1\',\'owner_id\',s.owner_id::text,\n   \'request_sha256\',s.request_sha256,\'parent_binding_sha256\',s.parent_binding_sha256,\n   \'dataset_content_sha256\',p.label_source_manifest_sha256,\'frozen_input_sha256\',p.input_sha256,\n   \'catalog_revision\',\'configured_rd_seeded_single_output_session_v1\',\'runtime_profile_sha256\',profile_sha);\n END IF;\n IF s.request_canonical IS DISTINCT FROM exact_bytes\n OR s.request_sha256 IS DISTINCT FROM encode(sha256(convert_to(exact_bytes,\'UTF8\')),\'hex\')\n OR s.runtime_profile_sha256 IS DISTINCT FROM profile_sha\n OR s.preflight_sha256 IS DISTINCT FROM mineagent_execution_metadata_sha(preflight)\n THEN RAISE EXCEPTION \'Seeded canonical declaration or preflight differs\'; END IF;\n IF EXISTS(SELECT 1 FROM factor_generation_starts st WHERE st.run_id=r.id AND st.logical_step=0\n AND (st.owner_id<>s.owner_id OR st.parent_factor_version_id IS DISTINCT FROM s.parent_factor_version_id))\n OR EXISTS(SELECT 1 FROM factor_source_publications pub JOIN factor_generation_starts st ON st.id=pub.start_id\n WHERE st.run_id=r.id AND st.logical_step=0 AND pub.factor_id IS DISTINCT FROM s.parent_factor_id)\n THEN RAISE EXCEPTION \'Seeded initial source must retain declared parent and factor family\'; END IF;\nEND $$;ALTER TABLE @SCHEMA@.research_process_admissions DROP CONSTRAINT ck_process_v2_unregistered, ADD CONSTRAINT ck_process_v2_unregistered CHECK ((((schema_version=\'mineagent.process-admission.v1\' OR\n (schema_version=\'mineagent.process-admission.v2\' AND ipc_policy=\'none\' AND ticket_sha256 IS NULL AND (\n (role=\'factor_cutoff_candidate\' AND profile=\'mineagent.factor-prefix-candidate.v2\') OR\n (role=\'factor_normalizer\' AND profile=\'mineagent.factor-numeric-hdf.v1\') OR\n (role=\'native_evaluator\' AND profile IN (\'mineagent.qlib-direct-analysis.v1\',\'mineagent.openevolve-native-evaluator.v1\')))) OR\n (schema_version=\'mineagent.process-admission.v2\' AND ipc_policy=\'host_ticket\' AND ticket_sha256 ~ \'^[a-f0-9]{64}$\' AND (\n (role=\'rd_orchestrator\' AND profile IN (\'mineagent.rdagent-orchestrator.v1\',\'mineagent.rdagent-orchestrator.v2\',\'mineagent.rdagent-orchestrator.v3\')) OR\n (role=\'openevolve_orchestrator\' AND profile=\'mineagent.openevolve-orchestrator.v1\')))) IS TRUE) OR (schema_version=\'mineagent.process-admission.v2\'\n AND role=\'native_evaluator\' AND profile=\'mineagent.factor-strategy-engine.v1\'\n AND ipc_policy=\'none\' AND ticket_sha256 IS NULL)) IS TRUE);DROP TRIGGER rd_v4_seed_binding ON @SCHEMA@.research_runs;\nDROP TRIGGER rd_v4_seed_binding ON @SCHEMA@.factor_seeded_submissions;\nDROP TRIGGER rd_v4_seed_binding ON @SCHEMA@.factor_research_submissions;\nDROP TRIGGER rd_v4_seed_binding ON @SCHEMA@.research_process_admissions;\nDROP FUNCTION @SCHEMA@.mineagent_rd_v4_seed_deferred();\nDROP FUNCTION @SCHEMA@.mineagent_rd_v4_seed_binding(uuid);'
# fmt: on


def _schema():
    value = op.get_bind().exec_driver_sql("SELECT current_schema()").scalar_one()
    if type(value) is not str or re.fullmatch(r"[a-z][a-z0-9_]{0,62}", value) is None:
        raise RuntimeError("Exact installation schema required")
    return '"' + value + '"'


def _maintenance(schema):
    op.execute("""DO $$ BEGIN
    IF current_setting('transaction_isolation') <> 'read committed'
    OR NOT pg_try_advisory_xact_lock(1413960260,1129270340)
    THEN RAISE EXCEPTION 'Seeded controller v4 migration requires quiescent maintenance'; END IF;
    END $$;""")
    tables = (
        "research_runs",
        "factors",
        "factor_versions",
        "factor_objects",
        "execution_attempts",
        "research_process_admissions",
        "research_process_states",
        "research_process_receipts",
        "research_budget_reservations",
        "research_budget_settlements",
        "research_budget_controls",
        "factor_research_specs",
        "factor_research_attempt_bindings",
        "factor_controller_launches",
        "factor_research_submissions",
        "factor_seeded_submissions",
        "factor_generation_starts",
        "factor_strategy_executions",
        "research_model_operations",
        "research_model_transports",
        "research_model_outcomes",
        "factor_generation_model_operations",
        "factor_source_publications",
        "factor_source_read_witnesses",
    )
    op.execute(
        "LOCK TABLE "
        + ",".join(schema + "." + name for name in tables)
        + " IN ACCESS EXCLUSIVE MODE NOWAIT"
    )
    op.execute("SET LOCAL search_path = " + schema + ",pg_catalog")


def upgrade():
    schema = _schema()
    _maintenance(schema)
    op.get_bind().exec_driver_sql(
        UPGRADE_SQL.replace("@SCHEMA@", schema),
        execution_options={"no_parameters": True},
    )


def downgrade():
    schema = _schema()
    _maintenance(schema)
    op.get_bind().exec_driver_sql(
        DOWNGRADE_SQL.replace("@SCHEMA@", schema),
        execution_options={"no_parameters": True},
    )
